      "path": "src/main/services/hermesServiceManager.ts",
      "content": "import { createHash, randomBytes, randomUUID } from 'node:crypto';\nimport { createServer } from 'node:net';\nimport { spawn, type ChildProcess } from 'node:child_process';\nimport {\n  existsSync,\n  lstatSync,\n  mkdirSync,\n  renameSync,\n  rmSync,\n  writeFileSync\n} from 'node:fs';\nimport { delimiter, join, relative, resolve } from 'node:path';\nimport { app } from 'electron';\nimport type {\n  HermesChatActivity,\n  HermesChatQueueEvent,\n  HermesChatQueueItem,\n  HermesChatQueueStatus,\n  HermesProjectChatHistory,\n  HermesProjectBinding,\n  HermesProjectTurnResult,\n  HermesRuntimeStatus,\n  HermesUiLease\n} from '../../shared/types.js';\nimport type { Database } from './database.js';\nimport {\n  projectHermesChatMessages,\n  safeHermesActivityDetail\n} from './hermesChatProjection.js';\nimport { HERMES_RUNTIME_VERSION, runtimeStatusError } from './hermesProtocol.js';\nimport { HermesProxy } from './hermesProxy.js';\n\nconst PROJECT_ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/;\nconst HOST = '127.0.0.1' as const;\n// Leave room for the project governance prompt and tool schemas on\n// OpenAI-compatible gateways that reject max_tokens + prompt > context.\nconst HERMES_MAX_OUTPUT_TOKENS = 16_384;\n// Hermes performs a one-time plugin discovery and Python import pass on a\n// cold install. On Windows that can exceed the old 45 second gate even when\n// the dashboard is healthy moments later. Keep the runtime explicitly in\n// `starting-*` during that window instead of reporting a false offline state.\nconst START_TIMEOUT_MS = 120_000;\nconst HEALTH_INTERVAL_MS = 15_000;\nconst MAX_LOG_CHARS = 32_000;\n\nconst HERMES_PROFILE_DDL = [\n  `CREATE TABLE IF NOT EXISTS hermes_project_profiles (\n    id TEXT PRIMARY KEY,\n    organization_id TEXT NOT NULL REFERENCES organizations(id),\n    project_id TEXT NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE,\n    home_path TEXT NOT NULL,\n    runtime_version TEXT NOT NULL DEFAULT '0.19.0',\n    service_port INTEGER,\n    proxy_port INTEGER,\n    auth_secret_ref TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'stopped',\n    last_health_at INTEGER,\n    last_error TEXT,\n    created_at INTEGER NOT NULL,\n    updated_at INTEGER NOT NULL\n  )`,\n  `CREATE INDEX IF NOT EXISTS idx_hermes_project_profiles_status ON hermes_project_profiles(status, updated_at DESC)`,\n  `CREATE TABLE IF NOT EXISTS hermes_session_bindings (\n    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n    principal_id TEXT NOT NULL REFERENCES principals(id),\n    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n    hermes_session_id TEXT NOT NULL,\n    identity_key TEXT,\n    last_seen_at INTEGER NOT NULL,\n    PRIMARY KEY(project_id, conversation_id)\n  )`,\n  `CREATE INDEX IF NOT EXISTS idx_hermes_session_bindings_hermes ON hermes_session_bindings(hermes_session_id, last_seen_at DESC)`,\n  `CREATE TABLE IF NOT EXISTS hermes_conversation_profiles (\n    conversation_id TEXT PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE,\n    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n    employee_id TEXT REFERENCES agents(id) ON DELETE SET NULL,\n    created_at INTEGER NOT NULL,\n    updated_at INTEGER NOT NULL\n  )`,\n  `CREATE TABLE IF NOT EXISTS hermes_run_bindings (\n    hermes_run_id TEXT PRIMARY KEY,\n    nexus_task_id TEXT,\n    worker_run_id TEXT,\n    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n    plan_hash TEXT,\n    status TEXT NOT NULL DEFAULT 'observed',\n    created_at INTEGER NOT NULL,\n    updated_at INTEGER NOT NULL\n  )`,\n  `CREATE INDEX IF NOT EXISTS idx_hermes_run_bindings_project ON hermes_run_bindings(project_id, updated_at DESC)`,\n  `CREATE TABLE IF NOT EXISTS hermes_chat_queue (\n    id TEXT PRIMARY KEY,\n    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n    principal_id TEXT NOT NULL REFERENCES principals(id),\n    message TEXT NOT NULL,\n    title TEXT NOT NULL DEFAULT '',\n    system_message TEXT NOT NULL DEFAULT '',\n    status TEXT NOT NULL DEFAULT 'QUEUED'\n      CHECK(status IN ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),\n    attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0),\n    stream_text TEXT NOT NULL DEFAULT '',\n    activity_json TEXT NOT NULL DEFAULT '[]',\n    result_json TEXT,\n    last_error TEXT,\n    cancel_requested_at INTEGER,\n    created_at INTEGER NOT NULL,\n    started_at INTEGER,\n    completed_at INTEGER,\n    updated_at INTEGER NOT NULL\n  )`,\n  `CREATE INDEX IF NOT EXISTS idx_hermes_chat_queue_conversation\n    ON hermes_chat_queue(project_id, conversation_id, status, created_at, id)`,\n  `CREATE INDEX IF NOT EXISTS idx_hermes_chat_queue_project\n    ON hermes_chat_queue(project_id, updated_at DESC)`\n] as const;\n\nexport interface HermesRuntimeLaunch {\n  pythonPath: string;\n  sourcePath: string;\n  webDistPath: string;\n}\n\nexport interface HermesServiceManagerOptions {\n  root?: string;\n  resolveLaunch?: () => HermesRuntimeLaunch;\n  resolveProviderEnvironment?: (projectId: string) => Record<string, string>;\n  resolveProjectWorkspace?: (projectId: string) => string | null;\n  onUpstreamMessage?: (projectId: string, message: unknown) => void;\n  onClientMessage?: (projectId: string, message: unknown) => Promise<{ handled: boolean; result?: unknown }>;\n  onHostRequest?: (projectId: string, operation: string, payload: unknown) => Promise<unknown>;\n  onProjectRequest?: (\n    projectId: string,\n    operation: string,\n    payload: unknown,\n    audience: 'desktop' | 'mobile-operator'\n  ) => Promise<unknown>;\n  bindSession?: (\n    projectId: string,\n    hermesSessionId: string,\n    requested?: { conversationId: string; principalId: string }\n  ) => { conversationId: string; principalId: string };\n  resolveConversationContext?: (projectId: string, conversationId: string) => string;\n  now?: () => number;\n  startTimeoutMs?: number;\n  onDiagnostic?: (event: {\n    projectId: string;\n    component: 'runtime' | 'proxy' | 'dashboard' | 'gateway';\n    phase: string;\n    elapsedMs: number;\n    detail?: string;\n  }) => void;\n  /** Project-scoped event sink for external OA integrations. */\n  onProjectEvent?: (projectId: string, event: HermesChatQueueEvent | Record<string, unknown>) => void;\n}\n\ninterface ManagedInstance {\n  projectId: string;\n  homePath: string;\n  runtimeModel: string;\n  process: ChildProcess;\n  gatewayProcess: ChildProcess;\n  gatewayUrl: string;\n  gatewayToken: string;\n  proxy: HermesProxy;\n  status: HermesRuntimeStatus;\n  log: string;\n  dashboardLog: string;\n  gatewayLog: string;\n  dashboardReady: boolean;\n  gatewayReady: boolean;\n  healthTimer: NodeJS.Timeout | null;\n  expectedStop: boolean;\n  crashCleanup: Promise<void> | null;\n}\n\ninterface ConversationMemoryPolicy {\n  mode: 'long_term' | 'short_term' | 'none';\n  scope: string;\n}\n\ninterface ProfileRow {\n  project_id: string;\n  home_path: string;\n  runtime_version: string;\n  service_port: number | null;\n  proxy_port: number | null;\n  status: string;\n  last_health_at: number | null;\n  last_error: string | null;\n  created_at: number;\n  updated_at: number;\n}\n\ninterface ChatQueueRow {\n  id: string;\n  project_id: string;\n  conversation_id: string;\n  principal_id: string;\n  message: string;\n  title: string;\n  system_message: string;\n  status: HermesChatQueueStatus;\n  attempts: number;\n  stream_text: string;\n  activity_json: string;\n  result_json: string | null;\n  last_error: string | null;\n  cancel_requested_at: number | null;\n  created_at: number;\n  started_at: number | null;\n  completed_at: number | null;\n  updated_at: number;\n}\n\nexport interface HermesProjectTurnStreamHandlers {\n  onStarted?: () => void;\n  onDelta?: (delta: string) => void;\n  onActivity?: (activity: {\n    kind: 'reasoning' | 'tool';\n    phase: 'running' | 'completed' | 'failed';\n    toolName: string | null;\n    detail: string | null;\n  }) => void;\n  signal?: AbortSignal;\n}\n\nfunction parseChatActivities(value: unknown): HermesChatActivity[] {\n  if (typeof value !== 'string' || !value.trim()) return [];\n  let parsed: unknown;\n  try { parsed = JSON.parse(value) as unknown; } catch { return []; }\n  if (!Array.isArray(parsed)) return [];\n  return parsed.slice(0, 200).flatMap((item) => {\n    if (!item || typeof item !== 'object' || Array.isArray(item)) return [];\n    const record = item as Record<string, unknown>;\n    const kind = String(record.kind ?? '');\n    const status = String(record.status ?? '');\n    if (!['reasoning', 'tool_call', 'tool_result', 'system'].includes(kind)\n      || !['running', 'completed', 'failed', 'cancelled'].includes(status)) return [];\n    const id = typeof record.id === 'string' ? record.id.trim().slice(0, 320) : '';\n    const title = typeof record.title === 'string' ? record.title.trim().slice(0, 240) : '';\n    if (!id || !title) return [];\n    return [{\n      id,\n      kind: kind as HermesChatActivity['kind'],\n      title,\n      status: status as HermesChatActivity['status'],\n      toolName: typeof record.toolName === 'string' ? record.toolName.trim().slice(0, 160) || null : null,\n      detail: safeHermesActivityDetail(record.detail),\n      startedAt: typeof record.startedAt === 'number' && Number.isFinite(record.startedAt) ? record.startedAt : null,\n      updatedAt: typeof record.updatedAt === 'number' && Number.isFinite(record.updatedAt) ? record.updatedAt : null\n    }];\n  });\n}\n\nfunction safeToolName(value: unknown): string {\n  if (typeof value !== 'string') return '工具';\n  const clean = value.trim().replace(/[\\r\\n\\u0000]/g, '').slice(0, 160);\n  return clean || '工具';\n}\n\nfunction defaultRoot(): string {\n  return join(app.getPath('userData'), 'aibox-data', 'hermes', 'projects');\n}\n\nexport interface HermesRuntimeCandidateOptions {\n  appPath: string;\n  resourcesPath?: string;\n  isPackaged: boolean;\n  platform: NodeJS.Platform;\n  sourceOverride?: string;\n  pythonOverride?: string;\n}\n\nexport function hermesRuntimeLaunchCandidates(options: HermesRuntimeCandidateOptions): HermesRuntimeLaunch[] {\n  const pythonExecutable = options.platform === 'win32' ? 'python.exe' : 'bin/python3';\n  const roots = [\n    options.sourceOverride,\n    options.resourcesPath ? join(options.resourcesPath, 'hermes', 'hermes-agent') : null,\n    join(options.appPath, 'vendor', 'hermes-agent'),\n    !options.isPackaged && process.env.LOCALAPPDATA\n      ? join(process.env.LOCALAPPDATA, 'hermes', 'hermes-agent')\n      : null\n  ].filter((value): value is string => Boolean(value));\n  const results: HermesRuntimeLaunch[] = [];\n  for (const sourcePath of roots) {\n    const pythonPaths = [\n      options.pythonOverride,\n      options.resourcesPath ? join(options.resourcesPath, 'hermes', 'python', pythonExecutable) : null,\n      !options.isPackaged ? join(options.appPath, 'runtime', 'hermes', 'python', pythonExecutable) : null,\n      join(sourcePath, 'venv', options.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python3')\n    ].filter((value): value is string => Boolean(value));\n    for (const pythonPath of pythonPaths) {\n      results.push({ pythonPath, sourcePath, webDistPath: join(sourcePath, 'hermes_cli', 'web_dist') });\n    }\n  }\n  return results;\n}\n\nfunction launchCandidates(): HermesRuntimeLaunch[] {\n  return hermesRuntimeLaunchCandidates({\n    appPath: app.getAppPath(),\n    resourcesPath: typeof process.resourcesPath === 'string' ? process.resourcesPath : undefined,\n    isPackaged: app.isPackaged,\n    platform: process.platform,\n    sourceOverride: process.env.AIBOX_HERMES_SOURCE?.trim(),\n    pythonOverride: process.env.AIBOX_HERMES_PYTHON?.trim()\n  });\n}\n\nexport function resolveHermesRuntimeLaunch(): HermesRuntimeLaunch {\n  const candidate = launchCandidates().find((item) =>\n    existsSync(item.pythonPath)\n    && existsSync(join(item.sourcePath, 'hermes_cli', 'main.py'))\n    && existsSync(join(item.webDistPath, 'index.html'))\n  );\n  if (!candidate) {\n    throw new Error(app.isPackaged\n      ? 'Quest 核心运行时缺失或不完整，请重新安装包含 Hermes Runtime 的完整版本'\n      : 'Quest 核心运行时尚未准备，请在开发目录执行 npm run hermes:prepare 后重试');\n  }\n  return candidate;\n}\n\n/** Owns one real Hermes dashboard process and proxy per active project. */\nexport class HermesServiceManager {\n  private readonly root: string;\n  private readonly now: () => number;\n  private readonly resolveLaunch: () => HermesRuntimeLaunch;\n  private readonly resolveProviderEnvironment: (projectId: string) => Record<string, string>;\n  private resolveProjectWorkspace: (projectId: string) => string | null;\n  private resolveProjectWorkerPool: (projectId: string) => readonly string[];\n  private resolveProjectSkills: (projectId: string) => ReadonlyArray<{\n    id: string;\n    name: string;\n    description: string;\n    content: string;\n  }>;\n  private readonly onUpstreamMessage?: (projectId: string, message: unknown) => void;\n  private readonly onClientMessage?: (projectId: string, message: unknown) => Promise<{ handled: boolean; result?: unknown }>;\n  private readonly onHostRequest?: (projectId: string, operation: string, payload: unknown) => Promise<unknown>;\n  private readonly onProjectRequest?: HermesServiceManagerOptions['onProjectRequest'];\n  private readonly onDiagnostic?: HermesServiceManagerOptions['onDiagnostic'];\n  private readonly onProjectEvent?: HermesServiceManagerOptions['onProjectEvent'];\n  private bindSession?: HermesServiceManagerOptions['bindSession'];\n  private resolveConversationContext?: HermesServiceManagerOptions['resolveConversationContext'];\n  private onProjectHealthy?: (projectId: string) => Promise<void>;\n  private readonly startTimeoutMs: number;\n  private readonly instances = new Map<string, ManagedInstance>();\n  private readonly startOperations = new Map<string, Promise<HermesRuntimeStatus>>();\n  private readonly queueDrains = new Map<string, Promise<void>>();\n  private readonly runningQueueTurns = new Map<string, AbortController>();\n  // A Workbench can be rendered on desktop and mobile at the same time. Keep\n  // one upstream history read per session so refresh timers cannot pile up\n  // several identical Hermes API requests behind the LAN gateway.\n  private readonly projectHistoryReads = new Map<string, Promise<HermesProjectChatHistory>>();\n\n  constructor(private readonly db: Database, options: HermesServiceManagerOptions = {}) {\n    this.root = resolve(options.root ?? defaultRoot());\n    this.now = options.now ?? Date.now;\n    this.resolveLaunch = options.resolveLaunch ?? resolveHermesRuntimeLaunch;\n    this.resolveProviderEnvironment = options.resolveProviderEnvironment ?? (() => ({}));\n    this.resolveProjectWorkspace = options.resolveProjectWorkspace ?? (() => null);\n    this.resolveProjectWorkerPool = () => [];\n    this.resolveProjectSkills = () => [];\n    this.onUpstreamMessage = options.onUpstreamMessage;\n    this.onClientMessage = options.onClientMessage;\n    this.onHostRequest = options.onHostRequest;\n    this.onProjectRequest = options.onProjectRequest;\n    this.onDiagnostic = options.onDiagnostic;\n    this.onProjectEvent = options.onProjectEvent;\n    this.bindSession = options.bindSession;\n    this.resolveConversationContext = options.resolveConversationContext;\n    this.startTimeoutMs = options.startTimeoutMs ?? START_TIMEOUT_MS;\n    for (const statement of HERMES_PROFILE_DDL) this.db.raw.prepare(statement).run();\n    // Older databases predate identity isolation. Keep their rows usable, but\n    // let the first resumed turn rotate them to a clean employee-scoped session.\n    this.ensureSessionBindingIdentityColumn();\n    this.migrateLegacyHermesBindingColumns();\n    this.ensureChatQueueCancellationColumn();\n    this.ensureChatQueueActivityColumn();\n    this.reconcileStaleQueueItems();\n    mkdirSync(this.root, { recursive: true });\n    this.assertDirectoryNotSymlink(this.root);\n    this.reconcileStaleProfiles();\n  }\n\n  projectHome(projectId: string): string {\n    this.assertProject(projectId);\n    const home = resolve(this.root, projectId);\n    const rel = relative(this.root, home);\n    if (!rel || rel.startsWith('..') || rel.includes(':')) throw new Error('Hermes project home escaped its managed root');\n    return home;\n  }\n\n  getStatus(projectId: string): HermesRuntimeStatus {\n    this.assertProject(projectId);\n    const live = this.instances.get(projectId);\n    if (live) return structuredClone(live.status);\n    const row = this.profileRow(projectId);\n    const homePath = row?.home_path ?? this.projectHome(projectId);\n    return {\n      projectId,\n      state: row?.status === 'error' ? 'error' : 'stopped',\n      startupPhase: row?.status === 'error' ? 'error' : 'idle',\n      startupElapsedMs: null,\n      version: row?.runtime_version ?? HERMES_RUNTIME_VERSION,\n      host: HOST,\n      port: null,\n      proxyPort: null,\n      homePath,\n      serviceUrl: null,\n      uiUrl: null,\n      pid: null,\n      lastHealthAt: row?.last_health_at ?? null,\n      lastError: row?.last_error ?? null,\n      startedAt: null\n    };\n  }\n\n  listBindings(): HermesProjectBinding[] {\n    return (this.db.raw.prepare(\n      'SELECT * FROM hermes_project_profiles ORDER BY updated_at DESC'\n    ).all() as unknown as ProfileRow[]).map((row) => ({\n      projectId: row.project_id,\n      homePath: row.home_path,\n      runtimeVersion: row.runtime_version,\n      servicePort: row.service_port,\n      proxyPort: row.proxy_port,\n      status: this.runtimeState(row.status),\n      lastHealthAt: row.last_health_at,\n      lastError: row.last_error,\n      createdAt: row.created_at,\n      updatedAt: row.updated_at\n    }));\n  }\n\n  setProjectWorkspaceResolver(resolveWorkspace: (projectId: string) => string | null): void {\n    this.resolveProjectWorkspace = resolveWorkspace;\n  }\n\n  setProjectWorkerPoolResolver(resolveWorkerPool: (projectId: string) => readonly string[]): void {\n    this.resolveProjectWorkerPool = resolveWorkerPool;\n  }\n\n  setProjectSkillResolver(resolveSkills: HermesServiceManager['resolveProjectSkills']): void {\n    this.resolveProjectSkills = resolveSkills;\n  }\n\n  setSessionBinder(bindSession: NonNullable<HermesServiceManagerOptions['bindSession']>): void {\n    this.bindSession = bindSession;\n  }\n\n  setConversationContextResolver(\n    resolver: NonNullable<HermesServiceManagerOptions['resolveConversationContext']>\n  ): void {\n    this.resolveConversationContext = resolver;\n  }\n\n  setProjectHealthyHandler(handler: (projectId: string) => Promise<void>): void {\n    this.onProjectHealthy = handler;\n  }\n\n  async start(projectId: string): Promise<HermesRuntimeStatus> {\n    this.assertProject(projectId);\n    const live = this.instances.get(projectId);\n    // A stale healthy status must not keep a dead Main-owned proxy alive. This\n    // is especially important after a dashboard/gateway crash, where the\n    // process status can briefly outlive proxy cleanup.\n    if (live && ['healthy', 'degraded'].includes(live.status.state) && this.uiAvailable(live)) {\n      return structuredClone(live.status);\n    }\n    const existing = this.startOperations.get(projectId);\n    if (existing) return structuredClone(await existing);\n\n    let operation!: Promise<HermesRuntimeStatus>;\n    operation = this.startOnce(projectId).finally(() => {\n      if (this.startOperations.get(projectId) === operation) this.startOperations.delete(projectId);\n    });\n    this.startOperations.set(projectId, operation);\n    return structuredClone(await operation);\n  }\n\n  async startForUi(projectId: string): Promise<HermesRuntimeStatus> {\n    const startup = this.start(projectId);\n    // The full startup continues until the API Gateway is healthy. The UI only\n    // needs the authenticated dashboard; keep the rejection observed after\n    // returning so a later Gateway failure becomes runtime state, not an\n    // unhandled rejection.\n    void startup.catch(() => undefined);\n    const deadline = this.now() + this.startTimeoutMs;\n    while (this.now() < deadline) {\n      const instance = this.instances.get(projectId);\n      if (instance && this.uiAvailable(instance)) return structuredClone(instance.status);\n      // During crash recovery the old instance remains in ERROR while\n      // startOnce is still awaiting its cleanup. Do not surface that stale\n      // error before the replacement instance has had a chance to start.\n      if (instance?.status.state === 'error' && !this.startOperations.has(projectId)) {\n        throw new Error(instance.status.lastError ?? 'Hermes dashboard failed to start');\n      }\n      const settled = await Promise.race([\n        startup.then(() => true),\n        new Promise<false>((resolveWait) => setTimeout(() => resolveWait(false), 100))\n      ]);\n      if (settled) {\n        const current = this.instances.get(projectId);\n        if (current && this.uiAvailable(current)) return structuredClone(current.status);\n        throw new Error('Hermes dashboard or proxy did not become available');\n      }\n    }\n    throw new Error('Hermes dashboard startup timed out');\n  }\n\n  private async startOnce(projectId: string): Promise<HermesRuntimeStatus> {\n    this.assertProject(projectId);\n    const existing = this.instances.get(projectId);\n    if (existing && ['healthy', 'degraded'].includes(existing.status.state)) {\n      return structuredClone(existing.status);\n    }\n    if (existing) await this.stop(projectId);\n\n    const operationStartedAt = this.now();\n    this.diagnostic(projectId, 'runtime', 'preparing', operationStartedAt);\n    let workspacePath: string;\n    let launch: HermesRuntimeLaunch;\n    let providerEnvironment: Record<string, string>;\n    try {\n      workspacePath = this.requireProjectWorkspace(projectId);\n      launch = this.resolveLaunch();\n      providerEnvironment = this.resolveProviderEnvironment(projectId);\n      const missingProviderFields = [\n        !providerEnvironment.OPENAI_API_KEY?.trim() ? 'API Key' : null,\n        !providerEnvironment.OPENAI_BASE_URL?.trim() ? 'Base URL' : null,\n        !providerEnvironment.HERMES_INFERENCE_MODEL?.trim() ? '模型' : null\n      ].filter((value): value is string => value !== null);\n      if (missingProviderFields.length > 0) {\n        throw new Error(\n          `Hermes 无法启动：当前 Provider 缺少 ${missingProviderFields.join('、')}。`\n          + '请打开 Quest「连接设置」，保存并测试 Provider 后重试。'\n        );\n      }\n    } catch (error) {\n      throw this.persistStartupFailure(projectId, error, operationStartedAt);\n    }\n    const runtimeModel = providerEnvironment.HERMES_INFERENCE_MODEL.trim();\n    const homePath = this.prepareProjectHome(projectId, workspacePath);\n    const port = await this.reservePort();\n    const gatewayPort = await this.reservePort();\n    const serviceToken = randomBytes(32).toString('base64url');\n    const hostToken = randomBytes(32).toString('base64url');\n    const gatewayToken = randomBytes(32).toString('base64url');\n    const proxy = new HermesProxy({\n      projectId,\n      resolveServiceToken: () => serviceToken,\n      hostToken,\n      onHostRequest: this.onHostRequest\n        ? (operation, payload) => this.onHostRequest!(projectId, operation, payload)\n        : undefined,\n      onProjectRequest: this.onProjectRequest\n        ? (operation, payload, audience) => this.onProjectRequest!(projectId, operation, payload, audience)\n        : undefined,\n      resolveUpstream: () => {\n        const instance = this.instances.get(projectId);\n        return instance && this.dashboardAvailable(instance)\n          ? instance.status.serviceUrl\n          : null;\n      },\n      audit: (event) => this.db.audit({\n        id: randomUUID(), actor: 'system', action: 'hermes.proxy.request',\n        target: projectId,\n        result: `${event.method} ${event.status} ${event.path}${event.detail ? `: ${event.detail}` : ''}`.slice(0, 2_000),\n         source: 'hermes'\n      }),\n      trace: (event) => this.diagnostic(\n        projectId,\n        'proxy',\n        event.phase,\n        operationStartedAt,\n        [event.method, event.pathname, event.detail].filter(Boolean).join(' ')\n      ),\n      onUpstreamMessage: (message) => this.onUpstreamMessage?.(projectId, message),\n      onClientMessage: this.onClientMessage\n        ? (message) => this.onClientMessage!(projectId, message)\n        : undefined\n    });\n    await proxy.start();\n    const proxyStatus = proxy.getStatus();\n    const startedAt = operationStartedAt;\n    this.diagnostic(projectId, 'proxy', 'ready', operationStartedAt, `port=${proxyStatus.port}`);\n    const env = {\n      ...process.env,\n      ...providerEnvironment,\n      HERMES_INFERENCE_PROVIDER: 'custom:opcnexus',\n      HERMES_HOME: homePath,\n      HERMES_DESKTOP: '1',\n      HERMES_DASHBOARD_SESSION_TOKEN: serviceToken,\n      HERMES_NEXUS_HOST_URL: `${proxyStatus.origin}/__opc_nexus/host`,\n      HERMES_NEXUS_HOST_TOKEN: hostToken,\n      HERMES_NEXUS_PROJECT_ID: projectId,\n      HERMES_WEB_DIST: launch.webDistPath,\n      HERMES_CWD: workspacePath,\n      TERMINAL_CWD: workspacePath,\n      PYTHONPATH: [launch.sourcePath, process.env.PYTHONPATH].filter(Boolean).join(delimiter),\n      HERMES_QUIET: '1',\n      API_SERVER_ENABLED: 'true',\n      API_SERVER_KEY: gatewayToken,\n      API_SERVER_HOST: HOST,\n      API_SERVER_PORT: String(gatewayPort),\n      API_SERVER_MODEL_NAME: providerEnvironment.HERMES_INFERENCE_MODEL,\n      PYTHONUTF8: '1',\n      PYTHONUNBUFFERED: '1'\n    };\n    const child = spawn(launch.pythonPath, [\n      '-m', 'hermes_cli.main', 'dashboard',\n      '--host', HOST,\n      '--port', String(port),\n      '--no-open',\n      '--skip-build',\n      '--isolated'\n    ], {\n      cwd: workspacePath,\n      env,\n      windowsHide: true,\n      stdio: ['ignore', 'pipe', 'pipe']\n    });\n    const gatewayChild = spawn(launch.pythonPath, [\n      '-m', 'hermes_cli.main', 'gateway', 'run'\n    ], {\n      cwd: workspacePath,\n      env,\n      windowsHide: true,\n      stdio: ['ignore', 'pipe', 'pipe']\n    });\n    if (!child.stdout || !child.stderr || !gatewayChild.stdout || !gatewayChild.stderr) {\n      child.kill('SIGKILL');\n      gatewayChild.kill('SIGKILL');\n      await proxy.stop();\n      throw new Error('Hermes runtime process streams are unavailable');\n    }\n    const status: HermesRuntimeStatus = {\n      projectId,\n      state: 'starting',\n      startupPhase: 'starting-dashboard',\n      startupElapsedMs: Math.max(0, this.now() - startedAt),\n      version: null,\n      host: HOST,\n      port,\n      proxyPort: proxyStatus.port,\n      homePath,\n      serviceUrl: `http://${HOST}:${port}`,\n      uiUrl: proxyStatus.origin ? `${proxyStatus.origin}/` : null,\n      pid: child.pid ?? null,\n      lastHealthAt: null,\n      lastError: null,\n      startedAt\n    };\n    const instance: ManagedInstance = {\n      projectId,\n      homePath,\n      runtimeModel,\n      process: child,\n      gatewayProcess: gatewayChild,\n      gatewayUrl: `http://${HOST}:${gatewayPort}`,\n      gatewayToken,\n      proxy,\n      status,\n      log: '',\n      dashboardLog: '',\n      gatewayLog: '',\n      dashboardReady: false,\n      gatewayReady: false,\n      healthTimer: null,\n      expectedStop: false,\n      crashCleanup: null\n    };\n    this.instances.set(projectId, instance);\n    this.diagnostic(projectId, 'dashboard', 'spawned', startedAt, `pid=${child.pid ?? 'unknown'};port=${port}`);\n    this.diagnostic(projectId, 'gateway', 'spawned', startedAt, `pid=${gatewayChild.pid ?? 'unknown'};port=${gatewayPort}`);\n    const collect = (component: 'dashboard' | 'gateway', chunk: Buffer) => {\n      const text = chunk.toString('utf8');\n      instance.log = `${instance.log}${text}`.slice(-MAX_LOG_CHARS);\n      if (component === 'dashboard') {\n        instance.dashboardLog = `${instance.dashboardLog}${text}`.slice(-MAX_LOG_CHARS);\n      } else {\n        instance.gatewayLog = `${instance.gatewayLog}${text}`.slice(-MAX_LOG_CHARS);\n      }\n    };\n    child.stdout.on('data', (chunk: Buffer) => collect('dashboard', chunk));\n    child.stderr.on('data', (chunk: Buffer) => collect('dashboard', chunk));\n    gatewayChild.stdout.on('data', (chunk: Buffer) => collect('gateway', chunk));\n    gatewayChild.stderr.on('data', (chunk: Buffer) => collect('gateway', chunk));\n    child.once('exit', (code, signal) => this.onProcessExit(instance, 'dashboard', code, signal));\n    gatewayChild.once('exit', (code, signal) => this.onProcessExit(instance, 'gateway', code, signal));\n    child.once('error', (error) => this.onProcessError(instance, 'dashboard', error));\n    gatewayChild.once('error', (error) => this.onProcessError(instance, 'gateway', error));\n    this.persist(instance.status);\n\n    try {\n      await this.waitUntilHealthy(instance);\n      instance.healthTimer = setInterval(() => void this.refreshHealth(instance), HEALTH_INTERVAL_MS);\n      instance.healthTimer.unref();\n      if (this.onProjectHealthy) {\n        void this.onProjectHealthy(projectId).catch((error: unknown) => {\n          this.audit('hermes.project.resume-pending', projectId, error instanceof Error ? error.message : String(error));\n        });\n      }\n      this.resumeQueuedProjectTurns(projectId);\n      return structuredClone(instance.status);\n    } catch (error) {\n      instance.status = runtimeStatusError(\n        projectId,\n        homePath,\n        this.withComponentLogs(error, instance),\n        instance.status\n      );\n      this.persist(instance.status);\n      this.diagnostic(projectId, 'runtime', 'error', startedAt, instance.status.lastError ?? undefined);\n      if (instance.crashCleanup) await instance.crashCleanup;\n      else {\n        await this.stopProcess(instance);\n        await proxy.stop();\n      }\n      this.instances.delete(projectId);\n      throw new Error(instance.status.lastError ?? 'Hermes failed to start');\n    }\n  }\n\n  async stop(projectId: string): Promise<HermesRuntimeStatus> {\n    this.assertProject(projectId);\n    const instance = this.instances.get(projectId);\n    if (!instance) {\n      const status = this.getStatus(projectId);\n      const stopped = {\n        ...status,\n        state: 'stopped' as const,\n        startupPhase: 'idle' as const,\n        startupElapsedMs: null,\n        port: null,\n        proxyPort: null,\n        serviceUrl: null,\n        uiUrl: null,\n        pid: null\n      };\n      this.persist(stopped);\n      return stopped;\n    }\n    if (instance.crashCleanup) await instance.crashCleanup;\n    instance.expectedStop = true;\n    instance.status = { ...instance.status, state: 'stopping', startupPhase: 'stopping' };\n    this.persist(instance.status);\n    if (instance.healthTimer) clearInterval(instance.healthTimer);\n    instance.healthTimer = null;\n    await instance.proxy.stop();\n    await this.stopProcess(instance);\n    this.instances.delete(projectId);\n    const stopped: HermesRuntimeStatus = {\n      ...instance.status,\n      state: 'stopped',\n      startupPhase: 'idle',\n      startupElapsedMs: null,\n      port: null,\n      proxyPort: null,\n      serviceUrl: null,\n      uiUrl: null,\n      pid: null,\n      lastError: null\n    };\n    this.persist(stopped);\n    this.audit('hermes.project.stop', projectId, 'ok');\n    return stopped;\n  }\n\n  async restart(projectId: string): Promise<HermesRuntimeStatus> {\n    await this.stop(projectId);\n    return this.start(projectId);\n  }\n\n  async emergencyStop(projectId: string): Promise<HermesRuntimeStatus> {\n    const instance = this.instances.get(projectId);\n    if (instance && instance.process.exitCode === null) instance.process.kill('SIGKILL');\n    if (instance && instance.gatewayProcess.exitCode === null) instance.gatewayProcess.kill('SIGKILL');\n    this.audit('hermes.project.emergencyStop', projectId, instance ? 'terminated' : 'not-running');\n    return this.stop(projectId);\n  }\n\n  createUiLease(projectId: string): HermesUiLease {\n    const instance = this.instances.get(projectId);\n    if (!instance || !this.uiAvailable(instance)) throw new Error('Hermes dashboard or proxy is not ready');\n    return instance.proxy.createLease();\n  }\n\n  createMobileLease(projectId: string, role: 'operator'): HermesUiLease {\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy' || !this.uiAvailable(instance)) {\n      throw new Error('Hermes project service or proxy is not healthy');\n    }\n    return instance.proxy.createLease(8 * 60 * 60_000, `mobile-${role}`);\n  }\n\n  /** True only while the project dashboard and its Main-owned proxy are usable. */\n  isUiAvailable(projectId: string): boolean {\n    this.assertProject(projectId);\n    const instance = this.instances.get(projectId);\n    return instance ? this.uiAvailable(instance) : false;\n  }\n\n  cookieForLease(projectId: string, lease: HermesUiLease): { name: string; value: string; url: string } {\n    const instance = this.instances.get(projectId);\n    if (!instance) throw new Error('Hermes project service is not running');\n    return instance.proxy.cookieForLease(lease);\n  }\n\n  revokeUiLease(projectId: string, leaseId: string): void {\n    this.instances.get(projectId)?.proxy.revokeLease(leaseId);\n  }\n\n  enqueueProjectTurn(projectId: string, input: {\n    conversationId: string;\n    principalId: string;\n    message: string;\n    title?: string;\n    systemMessage?: string;\n  }): HermesChatQueueItem {\n    this.assertProject(projectId);\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy') throw new Error('Hermes project service is not healthy');\n    const message = input.message?.trim();\n    if (!message || message.length > 128_000) throw new Error('Hermes project message is invalid');\n    const conversationId = input.conversationId?.trim();\n    const principalId = input.principalId?.trim();\n    const conversation = this.db.raw.prepare(`\n      SELECT c.id, c.principal_id\n      FROM conversations c\n      JOIN projects p ON p.id = c.project_id AND p.status <> 'archived'\n      WHERE c.id = ? AND c.project_id = ? AND c.principal_id = ?\n    `).get(conversationId, projectId, principalId) as { id?: string; principal_id?: string } | undefined;\n    if (conversation?.id !== conversationId || conversation.principal_id !== principalId) {\n      throw new Error('Hermes project conversation is unavailable');\n    }\n    const now = this.nextQueueCreatedAt(projectId, conversationId);\n    const id = `hermes-chat-${randomUUID()}`;\n    this.db.raw.prepare(`\n      INSERT INTO hermes_chat_queue(\n        id, project_id, conversation_id, principal_id, message, title, system_message,\n        status, attempts, stream_text, created_at, updated_at\n      ) VALUES(?, ?, ?, ?, ?, ?, ?, 'QUEUED', 0, '', ?, ?)\n    `).run(\n      id,\n      projectId,\n      conversationId,\n      principalId,\n      message,\n      input.title?.trim().slice(0, 160) ?? '',\n      input.systemMessage?.trim().slice(0, 256_000) ?? '',\n      now,\n      now\n    );\n    const item = this.requireQueueItem(projectId, id);\n    this.audit('hermes.chat.queue.enqueue', projectId, `queue=${id};conversation=${conversationId}`);\n    this.publishQueueEvent(projectId, {\n      type: 'chat.queue.updated', projectId, queueId: id, conversationId,\n      timestamp: now, item\n    });\n    this.scheduleConversationDrain(projectId, conversationId);\n    return item;\n  }\n\n  listProjectChatQueue(projectId: string): HermesChatQueueItem[] {\n    this.assertProject(projectId);\n    const activeRows = this.db.raw.prepare(`\n      SELECT * FROM hermes_chat_queue\n      WHERE project_id = ? AND status IN ('QUEUED', 'RUNNING', 'FAILED')\n      ORDER BY created_at, id\n      LIMIT 500\n    `).all(projectId) as unknown as ChatQueueRow[];\n    const cancelledRows = this.db.raw.prepare(`\n      SELECT * FROM hermes_chat_queue\n      WHERE project_id = ? AND status = 'CANCELLED'\n      ORDER BY completed_at DESC, created_at DESC, id DESC\n      LIMIT 100\n    `).all(projectId) as unknown as ChatQueueRow[];\n    const rows = [...activeRows, ...cancelledRows]\n      .sort((left, right) => left.created_at - right.created_at || left.id.localeCompare(right.id));\n    const positions = new Map<string, number>();\n    return rows.map((row) => {\n      let position: number | null = null;\n      if (row.status === 'QUEUED') {\n        position = (positions.get(row.conversation_id) ?? 0) + 1;\n        positions.set(row.conversation_id, position);\n      }\n      return this.toQueueItem(row, position);\n    });\n  }\n\n  retryProjectTurn(\n    projectId: string,\n    queueId: string,\n    confirmation: 'retry-failed-turn'\n  ): HermesChatQueueItem {\n    this.assertProject(projectId);\n    if (confirmation !== 'retry-failed-turn') {\n      throw new Error('Retry requires explicit owner confirmation');\n    }\n    const id = queueId?.trim();\n    if (!/^hermes-chat-[A-Za-z0-9-]{1,80}$/.test(id)) throw new Error('Hermes queue identity is invalid');\n    const existing = this.requireQueueItem(projectId, id);\n    if (existing.status !== 'FAILED') throw new Error('Only a failed Hermes queue item can be retried');\n    const now = this.nextQueueCreatedAt(projectId, existing.conversationId);\n    const updated = this.db.raw.prepare(`\n      UPDATE hermes_chat_queue\n      SET status = 'QUEUED', stream_text = '', activity_json = '[]', result_json = NULL, last_error = NULL,\n          cancel_requested_at = NULL, created_at = ?, started_at = NULL,\n          completed_at = NULL, updated_at = ?\n      WHERE id = ? AND project_id = ? AND status = 'FAILED'\n    `).run(now, now, id, projectId);\n    if (updated.changes !== 1) throw new Error('Only a failed Hermes queue item can be retried');\n    const item = this.requireQueueItem(projectId, id);\n    this.audit('hermes.chat.queue.retry', projectId, `queue=${id}`);\n    this.publishQueueEvent(projectId, {\n      type: 'chat.queue.updated', projectId, queueId: id,\n      conversationId: item.conversationId, timestamp: now, item\n    });\n    this.scheduleConversationDrain(projectId, item.conversationId);\n    return item;\n  }\n\n  cancelProjectTurn(projectId: string, queueId: string): HermesChatQueueItem {\n    this.assertProject(projectId);\n    const id = queueId?.trim();\n    if (!/^hermes-chat-[A-Za-z0-9-]{1,80}$/.test(id)) throw new Error('Hermes queue identity is invalid');\n    const existing = this.requireQueueItem(projectId, id);\n    if (existing.status !== 'QUEUED' && existing.status !== 'RUNNING') {\n      throw new Error('Only a queued or running Hermes turn can be cancelled');\n    }\n    if (existing.status === 'RUNNING' && existing.cancelRequestedAt !== null) {\n      return existing;\n    }\n    const requestedAt = this.now();\n    const updated = existing.status === 'QUEUED'\n      ? this.db.raw.prepare(`\n          UPDATE hermes_chat_queue\n          SET status = 'CANCELLED', cancel_requested_at = ?, last_error = NULL,\n              completed_at = ?, updated_at = ?\n          WHERE id = ? AND project_id = ? AND status = 'QUEUED'\n        `).run(requestedAt, requestedAt, requestedAt, id, projectId)\n      : this.db.raw.prepare(`\n          UPDATE hermes_chat_queue\n          SET cancel_requested_at = ?, last_error = NULL, updated_at = ?\n          WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n            AND cancel_requested_at IS NULL\n        `).run(requestedAt, requestedAt, id, projectId);\n    if (updated.changes !== 1) throw new Error('Hermes turn is no longer cancellable');\n\n    const item = this.requireQueueItem(projectId, id);\n    this.runningQueueTurns.get(id)?.abort(new Error('Cancelled by the project owner'));\n    this.audit('hermes.chat.queue.cancel', projectId,\n      `queue=${id};conversation=${item.conversationId};previous=${existing.status}`);\n    this.publishQueueEvent(projectId, {\n      type: 'chat.queue.updated', projectId, queueId: id,\n      conversationId: item.conversationId, timestamp: requestedAt, item\n    });\n    this.scheduleConversationDrain(projectId, item.conversationId);\n    return item;\n  }\n\n  async runProjectTurn(projectId: string, input: {\n    conversationId?: string;\n    principalId?: string;\n    message: string;\n    title?: string;\n    systemMessage?: string;\n  }, stream?: HermesProjectTurnStreamHandlers): Promise<HermesProjectTurnResult> {\n    this.assertProject(projectId);\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy') throw new Error('Hermes project service is not healthy');\n    const message = input.message?.trim();\n    if (!message || message.length > 128_000) throw new Error('Hermes project message is invalid');\n    if ((input.conversationId && !input.principalId) || (!input.conversationId && input.principalId)) {\n      throw new Error('Hermes conversation and principal must be supplied together');\n    }\n    let binding = input.conversationId\n      ? this.db.raw.prepare(`\n          SELECT conversation_id, principal_id, hermes_session_id, identity_key\n          FROM hermes_session_bindings WHERE project_id = ? AND conversation_id = ?\n        `).get(projectId, input.conversationId) as {\n          conversation_id?: string;\n          principal_id?: string;\n          hermes_session_id?: string;\n          identity_key?: string | null;\n        } | undefined\n      : undefined;\n    if (binding && binding.principal_id !== input.principalId) throw new Error('Hermes session principal does not match the conversation binding');\n\n    let fixedContext = binding?.conversation_id\n      ? this.resolveConversationContext?.(projectId, binding.conversation_id).trim() ?? ''\n      : '';\n    let identityKey = fixedContext ? this.identityKey(fixedContext) : null;\n    // Upgraded installations can have a Hermes session with a missing\n    // identity_key. A `nexus_` session is already owned by Hermes, so filling\n    // the projection metadata must not rotate it and silently erase the\n    // visible conversation history. Only clearly legacy DSH/Cordis session\n    // ids are rotated when their fixed employee context is first materialized.\n    const legacySession = Boolean(binding?.hermes_session_id && /(?:cordis|dsh)/i.test(binding.hermes_session_id));\n    const identityChanged = Boolean(\n      binding && identityKey && binding.identity_key !== identityKey\n        && (binding.identity_key !== null || legacySession)\n    );\n    let hermesSessionId = !binding || identityChanged\n      ? `nexus_${randomUUID().replace(/-/g, '')}`\n      : binding.hermes_session_id!;\n    const runtimeLock = {\n      model: instance.runtimeModel,\n      provider: 'custom:opcnexus',\n      require_model_lock: true\n    } as const;\n    const requestedMemoryPolicy = input.conversationId\n      ? this.conversationMemoryPolicy(projectId, input.conversationId)\n      : { mode: 'long_term', scope: 'project' } satisfies ConversationMemoryPolicy;\n    if (!binding || identityChanged) {\n      const sessionTitle = `${input.title?.trim() || 'OPC-Nexus project'} · ${hermesSessionId.slice(-8)}`.slice(0, 160);\n      await this.gatewayJson(instance, 'POST', '/api/sessions', {\n        id: hermesSessionId,\n        source: 'nexus',\n        title: sessionTitle,\n        nexus_memory_mode: requestedMemoryPolicy.mode,\n        nexus_memory_scope: requestedMemoryPolicy.scope,\n        ...runtimeLock\n      });\n      if (!binding) {\n        if (!this.bindSession) throw new Error('Hermes project session binder is unavailable');\n        const canonical = this.bindSession(\n          projectId,\n          hermesSessionId,\n          input.conversationId && input.principalId\n            ? { conversationId: input.conversationId, principalId: input.principalId }\n            : undefined\n        );\n        binding = {\n          conversation_id: canonical.conversationId,\n          principal_id: canonical.principalId,\n          hermes_session_id: hermesSessionId,\n          identity_key: null\n        };\n        const canonicalConversationId = binding.conversation_id;\n        if (!canonicalConversationId) throw new Error('Hermes canonical session binding is incomplete');\n        fixedContext = this.resolveConversationContext?.(projectId, canonicalConversationId).trim() ?? '';\n        identityKey = fixedContext ? this.identityKey(fixedContext) : null;\n      } else {\n        // Keep the canonical conversation, principal and UI tab while replacing\n        // only the contaminated Hermes runtime session.\n        const conversationId = binding.conversation_id;\n        if (!conversationId) throw new Error('Hermes canonical session binding is incomplete');\n        this.db.raw.prepare(`\n          UPDATE hermes_session_bindings\n          SET hermes_session_id = ?, identity_key = ?, last_seen_at = ?\n          WHERE project_id = ? AND conversation_id = ?\n        `).run(hermesSessionId, identityKey, this.now(), projectId, conversationId);\n        binding = { ...binding, hermes_session_id: hermesSessionId, identity_key: identityKey };\n      }\n    } else {\n      try {\n        await this.gatewayJson(\n          instance,\n          'POST',\n          `/api/sessions/${encodeURIComponent(hermesSessionId)}/model`,\n          runtimeLock\n        );\n      } catch (error) {\n        // A restored Nexus database can outlive a removed or corrupted Hermes\n        // home. Reusing that stale binding would make the next owner message\n        // fail with an opaque \"Session not found\" response forever.\n        if (!this.isMissingHermesSessionError(error)) throw error;\n        hermesSessionId = await this.recreateBoundProjectSession(\n          instance,\n          projectId,\n          binding,\n          requestedMemoryPolicy,\n          runtimeLock\n        );\n        binding = { ...binding, hermes_session_id: hermesSessionId };\n      }\n    }\n    if (!binding.conversation_id || !binding.principal_id) throw new Error('Hermes canonical session binding is incomplete');\n    const memoryPolicy = this.conversationMemoryPolicy(projectId, binding.conversation_id);\n\n    const chatPath = `/api/sessions/${encodeURIComponent(hermesSessionId)}/chat`;\n    fixedContext = fixedContext || (this.resolveConversationContext?.(projectId, binding.conversation_id).trim() ?? '');\n    identityKey = identityKey || (fixedContext ? this.identityKey(fixedContext) : null);\n    if (identityKey) {\n      this.db.raw.prepare(`\n        UPDATE hermes_session_bindings SET identity_key = ?, last_seen_at = ?\n        WHERE project_id = ? AND conversation_id = ?\n      `).run(identityKey, this.now(), projectId, binding.conversation_id);\n    }\n    const turnContext = input.systemMessage?.trim() ?? '';\n    const systemMessage = [fixedContext, turnContext].filter(Boolean).join('\\n\\n');\n    const chatBody = {\n      message,\n      nexus_memory_mode: memoryPolicy.mode,\n      nexus_memory_scope: memoryPolicy.scope,\n      ...(systemMessage ? { system_message: systemMessage } : {})\n    };\n    const chatHeaders = { 'x-hermes-session-key': `${projectId}:${binding.conversation_id}` };\n    const response = stream\n      ? await this.gatewaySse(\n          instance,\n          `${chatPath}/stream`,\n          chatBody,\n          15 * 60_000,\n          chatHeaders,\n          stream\n        )\n      : await this.gatewayJson(instance, 'POST', chatPath, chatBody, 15 * 60_000, chatHeaders) as Record<string, unknown>;\n    const responseSessionId = typeof response.session_id === 'string' ? response.session_id.trim() : '';\n    const responseMessage = response.message && typeof response.message === 'object' && !Array.isArray(response.message)\n      ? response.message as Record<string, unknown>\n      : null;\n    const content = typeof responseMessage?.content === 'string' ? responseMessage.content.trim() : '';\n    if (!responseSessionId || responseSessionId.length > 256 || !content) {\n      throw new Error('Hermes returned an invalid project turn response');\n    }\n    if (/^(?:API call failed(?: after \\d+ retries)?:|HTTP\\s+[45]\\d\\d\\s*:|Request payload too large\\b)/i.test(content)) {\n      throw new Error(content);\n    }\n    if (responseSessionId !== hermesSessionId) {\n      this.db.raw.prepare(`\n        UPDATE hermes_session_bindings SET hermes_session_id = ?, last_seen_at = ?\n        WHERE project_id = ? AND conversation_id = ? AND hermes_session_id = ?\n      `).run(responseSessionId, this.now(), projectId, binding.conversation_id, hermesSessionId);\n      hermesSessionId = responseSessionId;\n    } else {\n      this.db.raw.prepare(`\n        UPDATE hermes_session_bindings SET last_seen_at = ?\n        WHERE project_id = ? AND conversation_id = ?\n      `).run(this.now(), projectId, binding.conversation_id);\n    }\n    const usage = response.usage && typeof response.usage === 'object' && !Array.isArray(response.usage)\n      ? response.usage as Record<string, unknown>\n      : {};\n    const runtime = response.runtime && typeof response.runtime === 'object' && !Array.isArray(response.runtime)\n      ? response.runtime as Record<string, unknown>\n      : {};\n    const result: HermesProjectTurnResult = {\n      projectId,\n      conversationId: binding.conversation_id,\n      hermesSessionId,\n      content,\n      usage: {\n        inputTokens: this.nonnegativeInteger(usage.input_tokens),\n        outputTokens: this.nonnegativeInteger(usage.output_tokens),\n        totalTokens: this.nonnegativeInteger(usage.total_tokens)\n      },\n      runtime: {\n        provider: typeof runtime.provider === 'string' ? runtime.provider : null,\n        model: typeof runtime.model === 'string' ? runtime.model : null,\n        memoryMode: memoryPolicy.mode,\n        memoryScope: memoryPolicy.scope\n      },\n      createdAt: this.now()\n    };\n    this.db.raw.prepare(`\n      UPDATE conversations\n      SET last_message_at = ?, updated_at = ?, message_count = message_count + 2\n      WHERE id = ? AND project_id = ?\n    `).run(result.createdAt, result.createdAt, result.conversationId, projectId);\n    this.audit('hermes.project.turn', projectId, `conversation=${result.conversationId};session=${result.hermesSessionId}`);\n    return result;\n  }\n\n  async projectChatHistory(projectId: string, conversationId?: string): Promise<HermesProjectChatHistory> {\n    this.assertProject(projectId);\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy') throw new Error('Hermes project service is not healthy');\n    const binding = conversationId\n      ? this.db.raw.prepare(`\n          SELECT conversation_id, hermes_session_id FROM hermes_session_bindings\n          WHERE project_id = ? AND conversation_id = ?\n        `).get(projectId, conversationId) as { conversation_id?: string; hermes_session_id?: string } | undefined\n      : this.db.raw.prepare(`\n          SELECT conversation_id, hermes_session_id FROM hermes_session_bindings\n          WHERE project_id = ? ORDER BY last_seen_at DESC LIMIT 1\n        `).get(projectId) as { conversation_id?: string; hermes_session_id?: string } | undefined;\n    if (!binding?.conversation_id || !binding.hermes_session_id) {\n      return { projectId, conversationId: null, hermesSessionId: null, messages: [] };\n    }\n    const readKey = `${projectId}:${binding.conversation_id}:${binding.hermes_session_id}`;\n    const pending = this.projectHistoryReads.get(readKey);\n    if (pending) return pending;\n    const read = (async (): Promise<HermesProjectChatHistory> => {\n      // History is a read-only UI request. A stalled upstream must become a\n      // visible error before the mobile gateway's request budget expires.\n      let sessionId = binding.hermes_session_id!;\n      let payload: Record<string, unknown>;\n      try {\n        payload = await this.gatewayJson(\n          instance,\n          'GET',\n          `/api/sessions/${encodeURIComponent(sessionId)}/messages`,\n          undefined,\n          10_000\n        ) as Record<string, unknown>;\n      } catch (error) {\n        if (!this.isMissingHermesSessionError(error)) throw error;\n        const memoryPolicy = this.conversationMemoryPolicy(projectId, binding.conversation_id!);\n        sessionId = await this.recreateBoundProjectSession(\n          instance,\n          projectId,\n          binding,\n          memoryPolicy,\n          {\n            model: instance.runtimeModel,\n            provider: 'custom:opcnexus',\n            require_model_lock: true\n          }\n        );\n        return {\n          projectId,\n          conversationId: binding.conversation_id!,\n          hermesSessionId: sessionId,\n          messages: []\n        };\n      }\n      const data = Array.isArray(payload.data) ? payload.data : [];\n      const messages = projectHermesChatMessages(data, sessionId);\n      return {\n        projectId,\n        conversationId: binding.conversation_id!,\n        hermesSessionId: typeof payload.session_id === 'string' ? payload.session_id : sessionId,\n        messages\n      };\n    })();\n    this.projectHistoryReads.set(readKey, read);\n    try {\n      return await read;\n    } finally {\n      if (this.projectHistoryReads.get(readKey) === read) this.projectHistoryReads.delete(readKey);\n    }\n  }\n\n  async answerClarification(projectId: string, clarifyId: string, answer: unknown): Promise<HermesProjectTurnResult> {\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy') throw new Error('Hermes project service is not healthy');\n    const encoded = typeof answer === 'string' ? answer : JSON.stringify(answer);\n    if (typeof encoded !== 'string' || encoded.length > 64_000) throw new Error('Hermes clarification answer is invalid');\n    const request = this.db.raw.prepare(`\n      SELECT conversation_id, prompt FROM hermes_clarify_requests\n      WHERE clarify_id = ? AND project_id = ? AND status = 'ANSWERED'\n    `).get(clarifyId, projectId) as { conversation_id?: string; prompt?: string } | undefined;\n    if (!request?.conversation_id || !request.prompt) throw new Error('Hermes clarification has no resumable project conversation');\n    const binding = this.db.raw.prepare(`\n      SELECT principal_id FROM hermes_session_bindings\n      WHERE project_id = ? AND conversation_id = ?\n    `).get(projectId, request.conversation_id) as { principal_id?: string } | undefined;\n    if (!binding?.principal_id) throw new Error('Hermes clarification has no principal binding');\n    return await this.runProjectTurn(projectId, {\n      conversationId: request.conversation_id,\n      principalId: binding.principal_id,\n      message: [\n        `The owner answered pending clarification ${clarifyId}.`,\n        `Question: ${request.prompt}`,\n        `Answer: ${encoded}`,\n        'Continue the original request with this answer. Do not ask the same question again.'\n      ].join('\\n'),\n      title: 'OPC-Nexus clarification'\n    });\n  }\n\n  memoryIndex(projectId: string): Array<{ name: string; relativePath: string; updatedAt: number }> {\n    const home = this.projectHome(projectId);\n    const names = ['MEMORY.md', 'USER.md', 'SOUL.md', 'AGENTS.md'];\n    const rootEntries = names.flatMap((name) => {\n      const path = join(home, name);\n      if (!existsSync(path)) return [];\n      const stat = lstatSync(path);\n      if (!stat.isFile() || stat.isSymbolicLink()) return [];\n      return [{ name, relativePath: name, updatedAt: stat.mtimeMs }];\n    });\n    const project = this.db.raw.prepare('SELECT organization_id FROM projects WHERE id = ?')\n      .get(projectId) as { organization_id?: string } | undefined;\n    if (!project?.organization_id) return rootEntries;\n    const employees = this.db.raw.prepare(`\n      SELECT id, name FROM agents\n      WHERE organization_id = ? AND archived = 0 AND memory_mode = 'long_term'\n      ORDER BY name, id\n    `).all(project.organization_id) as Array<{ id: string; name: string }>;\n    const employeeEntries = employees.flatMap((employee) => {\n      const scope = this.employeeMemoryScope(employee.id);\n      return ['MEMORY.md', 'USER.md'].flatMap((filename) => {\n        const relativePath = join('memories', 'employees', scope, filename);\n        const path = join(home, relativePath);\n        if (!existsSync(path)) return [];\n        const stat = lstatSync(path);\n        if (!stat.isFile() || stat.isSymbolicLink()) return [];\n        return [{\n          name: `${employee.name} · ${filename}`,\n          relativePath: relativePath.replace(/\\\\/g, '/'),\n          updatedAt: stat.mtimeMs\n        }];\n      });\n    });\n    return [...rootEntries, ...employeeEntries];\n  }\n\n  async shutdown(): Promise<void> {\n    await Promise.all([...this.instances.keys()].map((projectId) => this.stop(projectId).then(() => undefined)));\n  }\n\n  private async waitUntilHealthy(instance: ManagedInstance): Promise<void> {\n    const deadline = this.now() + this.startTimeoutMs;\n    let lastError: unknown = new Error('Hermes health check timed out');\n    while (this.now() < deadline) {\n      if (instance.process.exitCode !== null) throw new Error(`Hermes dashboard exited with code ${instance.process.exitCode}`);\n      if (instance.gatewayProcess.exitCode !== null) throw new Error(`Hermes API gateway exited with code ${instance.gatewayProcess.exitCode}`);\n      try {\n        await this.refreshHealth(instance, true);\n        if (instance.status.state === 'healthy') return;\n      } catch (error) { lastError = error; }\n      await new Promise((resolve) => setTimeout(resolve, 250));\n    }\n    throw lastError;\n  }\n\n  private async refreshHealth(instance: ManagedInstance, throwOnFailure = false): Promise<void> {\n    const runtimeWasReady = instance.status.startupPhase === 'ready';\n    const [dashboard, gateway] = await Promise.allSettled([\n      this.dashboardHealth(instance),\n      this.gatewayHealth(instance)\n    ]);\n    const now = this.now();\n    const dashboardWasReady = instance.dashboardReady;\n    const gatewayWasReady = instance.gatewayReady;\n    instance.dashboardReady = dashboard.status === 'fulfilled';\n    instance.gatewayReady = gateway.status === 'fulfilled';\n\n    if (instance.dashboardReady && !dashboardWasReady) {\n      this.diagnostic(instance.projectId, 'dashboard', 'healthy', instance.status.startedAt ?? now);\n    }\n    if (instance.gatewayReady && !gatewayWasReady) {\n      this.diagnostic(instance.projectId, 'gateway', 'healthy', instance.status.startedAt ?? now);\n    }\n\n    if (dashboard.status === 'fulfilled' && gateway.status === 'fulfilled') {\n      instance.status = {\n        ...instance.status,\n        state: 'healthy',\n        startupPhase: 'ready',\n        startupElapsedMs: instance.status.startedAt === null ? null : Math.max(0, now - instance.status.startedAt),\n        version: dashboard.value,\n        lastHealthAt: now,\n        lastError: null\n      };\n      this.persist(instance.status);\n      if (!runtimeWasReady) {\n        this.diagnostic(instance.projectId, 'runtime', 'ready', instance.status.startedAt ?? now);\n      }\n      return;\n    }\n\n    const failures = [\n      dashboard.status === 'rejected'\n        ? `dashboard: ${dashboard.reason instanceof Error ? dashboard.reason.message : String(dashboard.reason)}`\n        : null,\n      gateway.status === 'rejected'\n        ? `gateway: ${gateway.reason instanceof Error ? gateway.reason.message : String(gateway.reason)}`\n        : null\n    ].filter((value): value is string => value !== null);\n    const message = failures.join('; ') || 'Hermes health check is incomplete';\n    const starting = instance.status.state === 'starting';\n    instance.status = {\n      ...instance.status,\n      state: starting ? 'starting' : 'degraded',\n      startupPhase: instance.dashboardReady ? 'starting-gateway' : 'starting-dashboard',\n      startupElapsedMs: instance.status.startedAt === null ? null : Math.max(0, now - instance.status.startedAt),\n      lastError: starting ? null : message\n    };\n    this.persist(instance.status);\n    if (throwOnFailure) throw new Error(message);\n  }\n\n  private async dashboardHealth(instance: ManagedInstance): Promise<string> {\n    const response = await fetch(`${instance.status.serviceUrl}/api/health`, {\n      signal: AbortSignal.timeout(2_500),\n      headers: { host: `${HOST}:${instance.status.port}` }\n    });\n    const body = await response.json() as { ok?: unknown; version?: unknown };\n    if (!response.ok || body.ok !== true || typeof body.version !== 'string') {\n      throw new Error(`HTTP ${response.status}`);\n    }\n    if (!body.version.startsWith('0.19.')) {\n      throw new Error(`version ${body.version} is not compatible with 0.19.x`);\n    }\n    return body.version;\n  }\n\n  private async gatewayHealth(instance: ManagedInstance): Promise<string> {\n    const response = await fetch(`${instance.gatewayUrl}/health`, { signal: AbortSignal.timeout(2_500) });\n    const body = await response.json() as { status?: unknown; version?: unknown };\n    if (!response.ok || body.status !== 'ok' || typeof body.version !== 'string') {\n      throw new Error(`HTTP ${response.status}`);\n    }\n    if (!body.version.startsWith('0.19.')) {\n      throw new Error(`version ${body.version} is not compatible with 0.19.x`);\n    }\n    return body.version;\n  }\n\n  private onProcessExit(instance: ManagedInstance, component: 'dashboard' | 'gateway', code: number | null, signal: NodeJS.Signals | null): void {\n    this.handleUnexpectedProcessFailure(\n      instance,\n      component,\n      new Error(`Hermes ${component} stopped unexpectedly (code=${code ?? 'null'}, signal=${signal ?? 'none'})`)\n    );\n  }\n\n  private onProcessError(instance: ManagedInstance, component: 'dashboard' | 'gateway', error: Error): void {\n    this.handleUnexpectedProcessFailure(instance, component, new Error(`${component}: ${error.message}`));\n  }\n\n  private handleUnexpectedProcessFailure(\n    instance: ManagedInstance,\n    component: 'dashboard' | 'gateway',\n    error: Error\n  ): void {\n    if (instance.expectedStop || instance.crashCleanup) return;\n    if (instance.healthTimer) clearInterval(instance.healthTimer);\n    instance.healthTimer = null;\n    instance.status = runtimeStatusError(\n      instance.projectId,\n      instance.homePath,\n      this.withComponentLogs(error, instance),\n      instance.status\n    );\n    this.persist(instance.status);\n    this.diagnostic(\n      instance.projectId,\n      component,\n      'error',\n      instance.status.startedAt ?? this.now(),\n      instance.status.lastError ?? undefined\n    );\n    const failure = instance.status.lastError ?? `Hermes ${component} stopped unexpectedly`;\n    this.failProjectRunningQueueTurns(instance.projectId, failure);\n    this.audit(`hermes.project.${component}.crash`, instance.projectId, failure);\n\n    // A dashboard + gateway + proxy is one project runtime lease. Once any\n    // member dies, keeping the siblings alive risks orphaned tools or stale UI.\n    instance.expectedStop = true;\n    instance.crashCleanup = (async () => {\n      await instance.proxy.stop();\n      await this.stopProcess(instance);\n    })().catch((cleanupError: unknown) => {\n      this.audit(\n        'hermes.project.crash-cleanup-error',\n        instance.projectId,\n        cleanupError instanceof Error ? cleanupError.message : String(cleanupError)\n      );\n    });\n  }\n\n  private async stopProcess(instance: ManagedInstance): Promise<void> {\n    await Promise.all([instance.process, instance.gatewayProcess].map(async (child) => {\n      if (child.exitCode !== null) return;\n      child.kill('SIGTERM');\n      const exited = await Promise.race([\n        new Promise<boolean>((resolve) => child.once('exit', () => resolve(true))),\n        new Promise<boolean>((resolve) => setTimeout(() => resolve(false), 5_000))\n      ]);\n      if (!exited && child.exitCode === null) child.kill('SIGKILL');\n    }));\n  }\n\n  private prepareProjectHome(projectId: string, workspacePath: string): string {\n    const home = this.projectHome(projectId);\n    if (existsSync(home)) this.assertDirectoryNotSymlink(home);\n    mkdirSync(home, { recursive: true });\n    this.assertDirectoryNotSymlink(home);\n    for (const directory of ['memories', 'skills', 'sessions']) {\n      const path = join(home, directory);\n      mkdirSync(path, { recursive: true });\n      this.assertDirectoryNotSymlink(path);\n    }\n    const managedSkills = join(home, 'skills', 'opc-nexus');\n    const managedRelative = relative(home, managedSkills);\n    if (!managedRelative || managedRelative.startsWith('..') || managedRelative.includes(':')) {\n      throw new Error('Hermes managed skill directory escaped the project home');\n    }\n    if (existsSync(managedSkills)) {\n      this.assertDirectoryNotSymlink(managedSkills);\n      rmSync(managedSkills, { recursive: true, force: true });\n    }\n    mkdirSync(managedSkills, { recursive: true });\n    this.assertDirectoryNotSymlink(managedSkills);\n    for (const skill of this.resolveProjectSkills(projectId)) {\n      if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(skill.id)) {\n        throw new Error(`Selected project skill ${skill.id} has an invalid identity`);\n      }\n      const directory = join(managedSkills, skill.id);\n      mkdirSync(directory, { recursive: true });\n      this.assertDirectoryNotSymlink(directory);\n      const frontmatterName = skill.name.replace(/[\\r\\n]/g, ' ').slice(0, 120);\n      const description = skill.description.replace(/[\\r\\n]/g, ' ').slice(0, 500);\n      this.atomicWrite(join(directory, 'SKILL.md'), [\n        '---',\n        `name: ${JSON.stringify(frontmatterName)}`,\n        `description: ${JSON.stringify(description)}`,\n        'allowed-tools: []',\n        '---',\n        '',\n        skill.content,\n        ''\n      ].join('\\n'));\n    }\n    const seeds: Record<string, string> = {\n      'MEMORY.md': '# Project Memory\\n',\n      'USER.md': '# Owner Context\\n',\n      'SOUL.md': '# Hermes Project Orchestrator\\n\\nUnderstand the owner request, clarify material ambiguity, and propose bounded work.\\n',\n      'AGENTS.md': [\n        '# OPC-Nexus Governance Contract',\n        '',\n        '- Read NEXUS-CONTEXT.md before selecting any employee, permission, or project path.',\n        '- Answer genuinely simple requests directly without forcing a planning ceremony.',\n        '- For complex or materially ambiguous work, use clarify before proposing a plan.',\n        '- When clarify returns OPC_NEXUS_CLARIFY_PENDING, stop the current turn and tell the owner that the question is waiting for an answer.',\n        '- Never call nexus_submit_plan in the same turn after a clarification becomes pending.',\n        '- After clarification, call nexus_submit_plan and wait for the owner approval.',\n        '- In every complex plan, assign each plan-level expected artifact to exactly one DAG node through that node expectedArtifacts. Never give every worker the whole delivery list.',\n        '- When the owner explicitly @mentions an employee, use nexus_delegate_task with the exact validated employee id.',\n        '- When the owner explicitly asks to create or staff a digital employee, call nexus_create_employee with ownerConfirmed=true and a bounded profile. Never create employees implicitly from a task description.',\n        '- Keep the project worker pool dynamic unless the owner explicitly asks for a fixed pool; do not set addToProjectPool for ordinary staffing.',\n        '- For a simple delegated task, use nexus_delegate_task without forcing a multi-step plan.',\n        '- Classify each employee request as execution, status_inquiry, or validation. A progress/status inquiry must use status_inquiry with no expected artifacts.',\n        '- For independent acceptance, assign a different qualified employee with intent validation and include related task ids when known.',\n        '- A validation task returns a factual verdict in its task result. Require a new file only when the owner explicitly requested a report artifact.',\n        '- After dispatch, use nexus_task_status to obtain the real terminal state and result before summarizing. Accepted, queued, and running are not completion.',\n        '- For real project tools, use the governed nexus_* tools through OPC-Nexus Main: nexus_web_search for a single search, nexus_web_search_aggregate for multi-engine result comparison, and nexus_research_search for bounded page retrieval with S1/S2 citations; nexus_http_request for network access, nexus_browser_* for browser research/interaction, nexus_computer_* only for explicitly requested host control, nexus_audio_synthesize for configured TTS, and nexus_video_* for FFmpeg media operations. If a tool is not shown directly, use tool_search/tool_describe to load its schema; never substitute a made-up result.',\n        '- Research answers must preserve the returned source IDs and URLs. Do not present a claim as verified when every supporting source is failed, skipped, or unavailable; report the search-engine failure instead.',\n        '- Read-only network/browser inspection may run directly when the project capability is available. Browser writes, host control, audio generation, video edits, and image generation require ownerConfirmed=true and must report the real output or the real dependency error.',\n        '- For product images use nexus_image_generate. It supports real text-to-image and image-to-image requests through the project Provider, including GPT Image 2 when that model is available; keep all reference and output paths inside the project workspace and never claim success without the returned artifact hash.',\n        '- Do not use native delegate_task for OPC-Nexus business delegation.',\n        '- OPC-Nexus Main owns approval, task state, execution state, permissions, budget, and audit facts.',\n        '- Never claim approval or completion, create fictional employees, or bypass the approved project workspace.'\n      ].join('\\n')\n    };\n    for (const [name, content] of Object.entries(seeds)) this.seedFile(join(home, name), content);\n    this.prepareEmployeeMemoryScopes(projectId, home);\n    this.atomicWrite(join(home, 'NEXUS-CONTEXT.md'), this.projectContext(projectId, workspacePath));\n    const provider = this.resolveProviderEnvironment(projectId);\n    const model = provider.HERMES_INFERENCE_MODEL ?? provider.OPENAI_MODEL ?? '';\n    const baseUrl = provider.OPENAI_BASE_URL ?? provider.OPENAI_API_BASE ?? '';\n    const config = {\n      model: {\n        default: model,\n        provider: 'custom:opcnexus',\n        base_url: baseUrl,\n        api_mode: 'chat_completions',\n        max_tokens: HERMES_MAX_OUTPUT_TOKENS\n      },\n      providers: {\n        opcnexus: {\n          name: 'OPC-Nexus',\n          base_url: baseUrl,\n          key_env: 'OPENAI_API_KEY',\n          default_model: model,\n          model,\n          api_mode: 'chat_completions',\n          max_tokens: HERMES_MAX_OUTPUT_TOKENS\n        }\n      },\n      dashboard: { host: HOST },\n      platforms: { api_server: { enabled: true } },\n      platform_toolsets: { api_server: ['hermes-api-server', 'planning'] },\n      // Main supplies a fail-closed per-conversation policy on every turn.\n      // Keeping the process default disabled prevents accidental project-wide\n      // memory sharing if a non-Nexus API route is called.\n      memory: { memory_enabled: false, user_profile_enabled: false, provider: '' }\n    };\n    this.atomicWrite(join(home, 'config.yaml'), `${JSON.stringify(config, null, 2)}\\n`);\n    rmSync(join(home, '.env'), { force: true });\n    rmSync(join(home, 'auth.json'), { force: true });\n    return home;\n  }\n\n  private requireProjectWorkspace(projectId: string): string {\n    const configured = this.resolveProjectWorkspace(projectId)?.trim() ?? '';\n    if (!configured) {\n      throw new Error('Hermes requires an approved project working directory. Reopen Workbench and select the delivery directory.');\n    }\n    const workspace = resolve(configured);\n    try { this.assertDirectoryNotSymlink(workspace); }\n    catch { throw new Error('The approved Hermes project working directory is missing or is a symbolic link. Select it again.'); }\n    return workspace;\n  }\n\n  /**\n   * Persist failures that happen before a child process exists. Without this\n   * record the UI only receives a rejected IPC promise and a stale `stopped`\n   * profile, which makes a missing credential indistinguishable from a crash\n   * after restart. The error is intentionally limited to the preflight reason\n   * and never includes the provider environment or secret.\n   */\n  private persistStartupFailure(projectId: string, error: unknown, startedAt: number): Error {\n    const message = error instanceof Error ? error.message : String(error);\n    const previous = this.getStatus(projectId);\n    const failure = runtimeStatusError(projectId, this.projectHome(projectId), message, {\n      ...previous,\n      startedAt\n    });\n    this.persist(failure);\n    this.diagnostic(projectId, 'runtime', 'error', startedAt, failure.lastError ?? undefined);\n    this.audit('hermes.project.start-preflight-failed', projectId, failure.lastError ?? 'unknown error');\n    return new Error(failure.lastError ?? 'Hermes failed its startup checks');\n  }\n\n  private projectContext(projectId: string, workspacePath: string): string {\n    const project = this.db.raw.prepare(`\n      SELECT id, organization_id, name, objective, description, client_name, status, due_at\n      FROM projects WHERE id = ? AND status <> 'archived'\n    `).get(projectId) as Record<string, unknown> | undefined;\n    if (!project || project.id !== projectId || typeof project.organization_id !== 'string') {\n      throw new Error('Hermes project context is unavailable');\n    }\n    const employees = this.db.raw.prepare(`\n      SELECT id, name, role, engine_id, lifecycle, permission_mode, memory_mode, capabilities_json, concurrency_limit\n      FROM agents\n      WHERE organization_id = ? AND archived = 0 AND lifecycle = 'READY'\n      ORDER BY created_at, id\n    `).all(project.organization_id) as Array<Record<string, unknown>>;\n    const configuredWorkerIds = [...new Set(this.resolveProjectWorkerPool(projectId))];\n    const restrictedWorkerIds = new Set(configuredWorkerIds);\n    const eligibleEmployees = configuredWorkerIds.length > 0\n      ? employees.filter((employee) => restrictedWorkerIds.has(String(employee.id)))\n      : employees;\n    const safeEmployees = eligibleEmployees.map((employee) => {\n      let capabilities: unknown = {};\n      try {\n        const parsed = JSON.parse(String(employee.capabilities_json ?? '{}')) as unknown;\n        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) capabilities = parsed;\n      } catch { /* corrupt capabilities remain unavailable */ }\n      return {\n        id: String(employee.id),\n        name: String(employee.name),\n        role: String(employee.role),\n        engineId: String(employee.engine_id),\n        lifecycle: 'READY',\n        permissionMode: String(employee.permission_mode),\n        memoryMode: ['long_term', 'short_term', 'none'].includes(String(employee.memory_mode))\n          ? String(employee.memory_mode)\n          : 'short_term',\n        capabilities,\n        concurrencyLimit: Number(employee.concurrency_limit)\n      };\n    });\n    return [\n      '# OPC-Nexus Project Context',\n      '',\n      'This file is generated by OPC-Nexus Main. Treat it as read-only host policy.',\n      '',\n      '```json',\n      JSON.stringify({\n        project: {\n          id: String(project.id),\n          name: String(project.name),\n          objective: String(project.objective ?? ''),\n          description: String(project.description ?? ''),\n          clientName: String(project.client_name ?? ''),\n          status: String(project.status),\n          dueAt: project.due_at ?? null,\n          workspace: workspacePath\n        },\n        employees: safeEmployees,\n        governance: {\n          planAuthority: 'OPC-Nexus host governance',\n          memoryAuthority: 'Hermes project files',\n          workerSelectionMode: configuredWorkerIds.length > 0 ? 'restricted' : 'dynamic',\n          allowedWorkerIds: safeEmployees.map((employee) => employee.id),\n          nativeDelegationAllowed: false,\n          acceptanceWorkflow: {\n            owner: 'Hermes primary coordinator',\n            validatorMustDifferFromImplementationWorker: true,\n            verdicts: ['PASS', 'FAIL', 'BLOCKED'],\n            completionRequiresPass: true\n          }\n        }\n      }, null, 2),\n      '```',\n      '',\n      '## Mandatory acceptance workflow',\n      '',\n      'After executable project work finishes, the primary Hermes coordinator must:',\n      '1. Read every implementation task to a real terminal state with nexus_task_status.',\n      '2. Select a qualified READY employee who did not implement any related task.',\n      '3. Dispatch that employee with nexus_delegate_task intent validation and the implementation task ids in relatedTaskIds.',\n      '4. Read the validation task to a real terminal state with nexus_task_status.',\n      '5. Report delivery complete only when validationVerdict is PASS. Keep FAIL unaccepted and propose bounded rework; report BLOCKED honestly.',\n      ''\n    ].join('\\n');\n  }\n\n  /** Refresh the generated host context after Main creates or archives an employee. */\n  refreshProjectContext(projectId: string): void {\n    const instance = this.instances.get(projectId);\n    if (!instance || instance.status.state !== 'healthy') return;\n    const workspace = this.requireProjectWorkspace(projectId);\n    this.atomicWrite(join(instance.homePath, 'NEXUS-CONTEXT.md'), this.projectContext(projectId, workspace));\n  }\n\n  private seedFile(path: string, content: string): void {\n    try { writeFileSync(path, content, { encoding: 'utf8', flag: 'wx' }); }\n    catch (error) { if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error; }\n  }\n\n  private atomicWrite(path: string, content: string): void {\n    const temp = `${path}.tmp-${process.pid}-${randomUUID()}`;\n    writeFileSync(temp, content, { encoding: 'utf8', flag: 'wx' });\n    try { renameSync(temp, path); }\n    catch (error) { rmSync(temp, { force: true }); throw error; }\n  }\n\n  private assertProject(projectId: string): void {\n    if (!PROJECT_ID.test(projectId)) throw new Error('Hermes projectId is invalid');\n    const row = this.db.raw.prepare(\n      \"SELECT id FROM projects WHERE id = ? AND status <> 'archived'\"\n    ).get(projectId) as { id?: string } | undefined;\n    if (row?.id !== projectId) throw new Error('Hermes project does not exist or is archived');\n  }\n\n  private ensureSessionBindingIdentityColumn(): void {\n    const columns = this.db.raw.prepare('PRAGMA table_info(hermes_session_bindings)').all() as Array<{ name?: string }>;\n    if (columns.some((column) => column.name === 'identity_key')) return;\n    this.db.raw.prepare('ALTER TABLE hermes_session_bindings ADD COLUMN identity_key TEXT').run();\n  }\n\n  private migrateLegacyHermesBindingColumns(): void {\n    let migrated = false;\n    this.db.transaction(() => {\n      const sessionColumns = new Set(\n        (this.db.raw.prepare('PRAGMA table_info(hermes_session_bindings)').all() as Array<{ name?: string }>)\n          .map((column) => column.name)\n          .filter((name): name is string => typeof name === 'string')\n      );\n      if (sessionColumns.has('dsh_session_id')) {\n        this.db.raw.prepare('ALTER TABLE hermes_session_bindings DROP COLUMN dsh_session_id').run();\n        migrated = true;\n      }\n\n      const runColumns = new Set(\n        (this.db.raw.prepare('PRAGMA table_info(hermes_run_bindings)').all() as Array<{ name?: string }>)\n          .map((column) => column.name)\n          .filter((name): name is string => typeof name === 'string')\n      );\n      if (runColumns.has('dsh_job_id') && !runColumns.has('nexus_task_id')) {\n        this.db.raw.prepare('ALTER TABLE hermes_run_bindings RENAME COLUMN dsh_job_id TO nexus_task_id').run();\n        runColumns.delete('dsh_job_id');\n        runColumns.add('nexus_task_id');\n        migrated = true;\n      }\n      if (runColumns.has('dsh_run_id') && !runColumns.has('worker_run_id')) {\n        this.db.raw.prepare('ALTER TABLE hermes_run_bindings RENAME COLUMN dsh_run_id TO worker_run_id').run();\n        migrated = true;\n      }\n    });\n    if (migrated) {\n      this.db.audit({\n        id: randomUUID(), actor: 'system', action: 'hermes.binding.schema.migrate',\n        target: 'hermes-bindings', result: 'legacy-dsh-columns-removed'\n      });\n    }\n  }\n\n  private ensureChatQueueCancellationColumn(): void {\n    const columns = this.db.raw.prepare('PRAGMA table_info(hermes_chat_queue)').all() as Array<{ name?: string }>;\n    if (columns.some((column) => column.name === 'cancel_requested_at')) return;\n    this.db.raw.prepare('ALTER TABLE hermes_chat_queue ADD COLUMN cancel_requested_at INTEGER').run();\n  }\n\n  private ensureChatQueueActivityColumn(): void {\n    const columns = this.db.raw.prepare('PRAGMA table_info(hermes_chat_queue)').all() as Array<{ name?: string }>;\n    if (columns.some((column) => column.name === 'activity_json')) return;\n    this.db.raw.prepare(\"ALTER TABLE hermes_chat_queue ADD COLUMN activity_json TEXT NOT NULL DEFAULT '[]'\").run();\n  }\n\n  private identityKey(context: string): string {\n    return createHash('sha256').update(`quest-identity-v2-memory\\n${context}`, 'utf8').digest('hex');\n  }\n\n  private employeeMemoryScope(employeeId: string): string {\n    return `employee-${createHash('sha256').update(employeeId, 'utf8').digest('hex').slice(0, 32)}`;\n  }\n\n  private conversationMemoryPolicy(projectId: string, conversationId: string): ConversationMemoryPolicy {\n    const row = this.db.raw.prepare(`\n      SELECT p.employee_id, a.memory_mode\n      FROM conversations c\n      LEFT JOIN hermes_conversation_profiles p\n        ON p.project_id = c.project_id AND p.conversation_id = c.id\n      LEFT JOIN agents a\n        ON a.id = p.employee_id\n       AND a.organization_id = c.organization_id\n       AND a.archived = 0\n       AND a.lifecycle = 'READY'\n      WHERE c.id = ? AND c.project_id = ?\n    `).get(conversationId, projectId) as { employee_id?: string | null; memory_mode?: string | null } | undefined;\n    if (!row) throw new Error('Hermes project conversation is unavailable');\n    if (!row.employee_id) return { mode: 'long_term', scope: 'project' };\n    if (!row.memory_mode) throw new Error('The digital employee memory policy is unavailable');\n    const mode = ['long_term', 'short_term', 'none'].includes(row.memory_mode)\n      ? row.memory_mode as ConversationMemoryPolicy['mode']\n      : 'short_term';\n    return { mode, scope: this.employeeMemoryScope(row.employee_id) };\n  }\n\n  private prepareEmployeeMemoryScopes(projectId: string, home: string): void {\n    const project = this.db.raw.prepare('SELECT organization_id FROM projects WHERE id = ?')\n      .get(projectId) as { organization_id?: string } | undefined;\n    if (!project?.organization_id) throw new Error('Hermes project memory scope is unavailable');\n    const employees = this.db.raw.prepare(`\n      SELECT id FROM agents\n      WHERE organization_id = ? AND archived = 0 AND memory_mode = 'long_term'\n      ORDER BY id\n    `).all(project.organization_id) as Array<{ id: string }>;\n    for (const employee of employees) {\n      const directory = join(home, 'memories', 'employees', this.employeeMemoryScope(employee.id));\n      const child = relative(home, directory);\n      if (!child || child.startsWith('..') || child.includes(':')) {\n        throw new Error('Hermes employee memory directory escaped the project home');\n      }\n      mkdirSync(directory, { recursive: true });\n      this.assertDirectoryNotSymlink(directory);\n      this.seedFile(join(directory, 'MEMORY.md'), '');\n      this.seedFile(join(directory, 'USER.md'), '');\n    }\n  }\n\n  private assertDirectoryNotSymlink(path: string): void {\n    const stat = lstatSync(path);\n    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error('Hermes managed root cannot be a symbolic link');\n  }\n\n  private profileRow(projectId: string): ProfileRow | null {\n    return (this.db.raw.prepare(\n      'SELECT * FROM hermes_project_profiles WHERE project_id = ?'\n    ).get(projectId) as unknown as ProfileRow | undefined) ?? null;\n  }\n\n  private persist(status: HermesRuntimeStatus): void {\n    const project = this.db.raw.prepare('SELECT organization_id FROM projects WHERE id = ?').get(status.projectId) as { organization_id?: string } | undefined;\n    if (!project?.organization_id) return;\n    const existing = this.profileRow(status.projectId);\n    const now = this.now();\n    this.db.raw.prepare(`\n      INSERT INTO hermes_project_profiles(\n        id, organization_id, project_id, home_path, runtime_version, service_port, proxy_port,\n        auth_secret_ref, status, last_health_at, last_error, created_at, updated_at\n      ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n      ON CONFLICT(project_id) DO UPDATE SET\n        home_path = excluded.home_path,\n        runtime_version = excluded.runtime_version,\n        service_port = excluded.service_port,\n        proxy_port = excluded.proxy_port,\n        status = excluded.status,\n        last_health_at = excluded.last_health_at,\n        last_error = excluded.last_error,\n        updated_at = excluded.updated_at\n    `).run(\n      existing ? `hermes-${status.projectId}` : `hermes-${status.projectId}`,\n      project.organization_id,\n      status.projectId,\n      status.homePath,\n      status.version ?? HERMES_RUNTIME_VERSION,\n      status.port,\n      status.proxyPort,\n      `ephemeral:hermes:${status.projectId}`,\n      status.state,\n      status.lastHealthAt,\n      status.lastError,\n      existing?.created_at ?? now,\n      now\n    );\n  }\n\n  private reconcileStaleQueueItems(): void {\n    const now = this.now();\n    this.db.raw.prepare(`\n      UPDATE hermes_chat_queue\n      SET status = 'FAILED',\n          last_error = 'OPC-Nexus restarted while this turn was running. Check the conversation before retrying to avoid duplicate execution.',\n          completed_at = ?, updated_at = ?\n      WHERE status = 'RUNNING'\n    `).run(now, now);\n  }\n\n  private resumeQueuedProjectTurns(projectId: string): void {\n    const conversations = this.db.raw.prepare(`\n      SELECT DISTINCT conversation_id FROM hermes_chat_queue\n      WHERE project_id = ? AND status = 'QUEUED'\n      ORDER BY conversation_id\n    `).all(projectId) as Array<{ conversation_id?: string }>;\n    for (const row of conversations) {\n      if (row.conversation_id) this.scheduleConversationDrain(projectId, row.conversation_id);\n    }\n  }\n\n  private scheduleConversationDrain(projectId: string, conversationId: string): void {\n    const key = `${projectId}\\u0000${conversationId}`;\n    if (this.queueDrains.has(key)) return;\n    const drain = Promise.resolve()\n      .then(() => this.drainConversationQueue(projectId, conversationId))\n      .catch((error: unknown) => {\n        this.audit('hermes.chat.queue.drain-error', projectId, error instanceof Error ? error.message : String(error));\n      })\n      .finally(() => this.queueDrains.delete(key));\n    this.queueDrains.set(key, drain);\n  }\n\n  private async drainConversationQueue(projectId: string, conversationId: string): Promise<void> {\n    while (this.instances.get(projectId)?.status.state === 'healthy') {\n      const row = this.db.raw.prepare(`\n        SELECT * FROM hermes_chat_queue\n        WHERE project_id = ? AND conversation_id = ? AND status = 'QUEUED'\n        ORDER BY created_at, id LIMIT 1\n      `).get(projectId, conversationId) as unknown as ChatQueueRow | undefined;\n      if (!row) return;\n      const startedAt = this.now();\n      const claimed = this.db.raw.prepare(`\n        UPDATE hermes_chat_queue\n        SET status = 'RUNNING', attempts = attempts + 1, stream_text = '', activity_json = '[]',\n            last_error = NULL, cancel_requested_at = NULL, started_at = ?,\n            completed_at = NULL, updated_at = ?\n        WHERE id = ? AND project_id = ? AND status = 'QUEUED'\n      `).run(startedAt, startedAt, row.id, projectId);\n      if (claimed.changes !== 1) continue;\n      let item = this.requireQueueItem(projectId, row.id);\n      const abortController = new AbortController();\n      this.runningQueueTurns.set(row.id, abortController);\n      this.publishQueueEvent(projectId, {\n        type: 'chat.queue.updated', projectId, queueId: row.id, conversationId,\n        timestamp: startedAt, item\n      });\n\n      let partialContent = '';\n      let activities: HermesChatActivity[] = [];\n      let activitySerial = 0;\n      let lastPersistAt = 0;\n      const publishActivities = () => {\n        this.db.raw.prepare(`\n          UPDATE hermes_chat_queue\n          SET stream_text = ?, activity_json = ?, updated_at = ?\n          WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n        `).run(partialContent, JSON.stringify(activities), this.now(), row.id, projectId);\n        const current = this.requireQueueItem(projectId, row.id);\n        this.publishQueueEvent(projectId, {\n          type: 'chat.queue.updated', projectId, queueId: row.id, conversationId,\n          timestamp: this.now(), item: current\n        });\n      };\n      const updateActivity = (event: {\n        kind: 'reasoning' | 'tool';\n        phase: 'running' | 'completed' | 'failed';\n        toolName: string | null;\n        detail: string | null;\n      }) => {\n        const timestamp = this.now();\n        if (event.kind === 'reasoning') {\n          if (activities.some((activity) => activity.kind === 'reasoning' && activity.status === 'running')) return;\n          activities.push({\n            id: `${row.id}:activity:${++activitySerial}`,\n            kind: 'reasoning',\n            title: '正在分析任务与下一步操作',\n            status: 'running',\n            toolName: null,\n            detail: 'Hermes 正在分析任务边界并选择下一步操作。内部私密推理不会直接展示。',\n            startedAt: timestamp,\n            updatedAt: timestamp\n          });\n        } else if (event.phase === 'running') {\n          activities = activities.map((activity) => activity.kind === 'reasoning' && activity.status === 'running'\n            ? { ...activity, title: '分析完成', status: 'completed', updatedAt: timestamp }\n            : activity);\n          const toolName = safeToolName(event.toolName);\n          activities.push({\n            id: `${row.id}:activity:${++activitySerial}`,\n            kind: 'tool_call',\n            title: `正在调用工具 · ${toolName}`,\n            status: 'running',\n            toolName,\n            detail: event.detail,\n            startedAt: timestamp,\n            updatedAt: timestamp\n          });\n        } else {\n          const toolName = safeToolName(event.toolName);\n          let targetIndex = -1;\n          for (let index = activities.length - 1; index >= 0; index -= 1) {\n            const activity = activities[index]!;\n            if (activity.kind === 'tool_call'\n              && activity.status === 'running'\n              && activity.toolName === toolName) {\n              targetIndex = index;\n              break;\n            }\n          }\n          if (targetIndex >= 0) {\n            const current = activities[targetIndex]!;\n            activities[targetIndex] = {\n              ...current,\n              title: `${event.phase === 'failed' ? '工具失败' : '工具完成'} · ${toolName}`,\n              status: event.phase === 'failed' ? 'failed' : 'completed',\n              detail: event.detail ?? current.detail,\n              updatedAt: timestamp\n            };\n          } else {\n            activities.push({\n              id: `${row.id}:activity:${++activitySerial}`,\n              kind: 'tool_result',\n              title: `${event.phase === 'failed' ? '工具失败' : '工具返回'} · ${toolName}`,\n              status: event.phase === 'failed' ? 'failed' : 'completed',\n              toolName,\n              detail: event.detail,\n              startedAt: timestamp,\n              updatedAt: timestamp\n            });\n          }\n        }\n        publishActivities();\n      };\n      try {\n        const result = await this.runProjectTurn(projectId, {\n          conversationId,\n          principalId: row.principal_id,\n          message: row.message,\n          title: row.title || undefined,\n          systemMessage: row.system_message || undefined\n        }, {\n          signal: abortController.signal,\n          onDelta: (delta) => {\n            if (abortController.signal.aborted) return;\n            partialContent += delta;\n            const wallNow = Date.now();\n            if (wallNow - lastPersistAt >= 250) {\n              lastPersistAt = wallNow;\n              this.db.raw.prepare(`\n                UPDATE hermes_chat_queue SET stream_text = ?, updated_at = ?\n                WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n              `).run(partialContent, this.now(), row.id, projectId);\n            }\n            this.publishQueueEvent(projectId, {\n              type: 'chat.queue.delta', projectId, queueId: row.id, conversationId,\n              timestamp: this.now(), delta\n            });\n          },\n          onActivity: updateActivity\n        });\n        const completedAt = this.now();\n        activities = activities.map((activity) => activity.status === 'running'\n          ? { ...activity, title: activity.kind === 'reasoning' ? '分析完成' : activity.title, status: 'completed', updatedAt: completedAt }\n          : activity);\n        const completed = this.db.raw.prepare(`\n          UPDATE hermes_chat_queue\n          SET status = 'COMPLETED', stream_text = ?, activity_json = ?, result_json = ?, last_error = NULL,\n              completed_at = ?, updated_at = ?\n          WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n            AND cancel_requested_at IS NULL\n        `).run(\n          result.content,\n          JSON.stringify(activities),\n          JSON.stringify({\n            hermesSessionId: result.hermesSessionId,\n            usage: result.usage,\n            runtime: result.runtime,\n            createdAt: result.createdAt\n          }),\n          completedAt,\n          completedAt,\n          row.id,\n          projectId\n        );\n        item = this.requireQueueItem(projectId, row.id);\n        if (completed.changes === 1) {\n          this.audit('hermes.chat.queue.complete', projectId, `queue=${row.id};conversation=${conversationId}`);\n          this.publishQueueEvent(projectId, {\n            type: 'chat.queue.updated', projectId, queueId: row.id, conversationId,\n            timestamp: completedAt, item\n          });\n        } else if (item.status === 'RUNNING' && item.cancelRequestedAt !== null) {\n          item = this.settleCancelledQueueTurn(projectId, row.id, conversationId);\n        }\n      } catch (error) {\n        const current = this.requireQueueItem(projectId, row.id);\n        if (current.status === 'CANCELLED') continue;\n        if (current.status === 'RUNNING' && current.cancelRequestedAt !== null) {\n          this.settleCancelledQueueTurn(projectId, row.id, conversationId);\n          continue;\n        }\n        const failedAt = this.now();\n        const message = (error instanceof Error ? error.message : String(error)).slice(0, 4_000);\n        activities = activities.map((activity) => activity.status === 'running'\n          ? { ...activity, status: 'failed', updatedAt: failedAt }\n          : activity);\n        this.db.raw.prepare(`\n          UPDATE hermes_chat_queue\n          SET status = 'FAILED', stream_text = ?, activity_json = ?, last_error = ?, completed_at = ?, updated_at = ?\n          WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n        `).run(partialContent, JSON.stringify(activities), message, failedAt, failedAt, row.id, projectId);\n        item = this.requireQueueItem(projectId, row.id);\n        this.audit('hermes.chat.queue.failed', projectId, `queue=${row.id};error=${message}`);\n        this.publishQueueEvent(projectId, {\n          type: 'chat.queue.updated', projectId, queueId: row.id, conversationId,\n          timestamp: failedAt, item\n        });\n        if (this.instances.get(projectId)?.status.state !== 'healthy') return;\n      } finally {\n        if (this.runningQueueTurns.get(row.id) === abortController) {\n          this.runningQueueTurns.delete(row.id);\n        }\n      }\n    }\n  }\n\n  /** Notify the embedded Quest surface that durable scheduling facts changed. */\n  publishProjectStateEvent(\n    projectId: string,\n    reason: 'task' | 'session' | 'plan' | 'clarification' = 'task'\n  ): void {\n    const event = {\n      type: 'project.state.updated',\n      projectId,\n      timestamp: this.now(),\n      reason\n    } as const;\n    this.instances.get(projectId)?.proxy.publishProjectEvent(event);\n    this.onProjectEvent?.(projectId, event);\n  }\n\n  private publishQueueEvent(projectId: string, event: HermesChatQueueEvent): void {\n    this.instances.get(projectId)?.proxy.publishProjectEvent(event);\n    this.onProjectEvent?.(projectId, event);\n  }\n\n  private nextQueueCreatedAt(projectId: string, conversationId: string): number {\n    const latest = this.db.raw.prepare(`\n      SELECT MAX(created_at) AS created_at FROM hermes_chat_queue\n      WHERE project_id = ? AND conversation_id = ?\n    `).get(projectId, conversationId) as { created_at?: number | null } | undefined;\n    return Math.max(this.now(), Number(latest?.created_at ?? 0) + 1);\n  }\n\n  private settleCancelledQueueTurn(\n    projectId: string,\n    queueId: string,\n    conversationId: string\n  ): HermesChatQueueItem {\n    const settledAt = this.now();\n    const current = this.requireQueueItem(projectId, queueId);\n    const activities = current.activities.map((activity) => activity.status === 'running'\n      ? { ...activity, status: 'cancelled' as const, updatedAt: settledAt }\n      : activity);\n    const updated = this.db.raw.prepare(`\n      UPDATE hermes_chat_queue\n      SET status = 'CANCELLED', activity_json = ?, last_error = NULL, completed_at = ?, updated_at = ?\n      WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n        AND cancel_requested_at IS NOT NULL\n    `).run(JSON.stringify(activities), settledAt, settledAt, queueId, projectId);\n    const item = this.requireQueueItem(projectId, queueId);\n    if (updated.changes === 1) {\n      this.audit(\n        'hermes.chat.queue.cancelled',\n        projectId,\n        `queue=${queueId};conversation=${conversationId};executor=settled`\n      );\n      this.publishQueueEvent(projectId, {\n        type: 'chat.queue.updated', projectId, queueId, conversationId,\n        timestamp: settledAt, item\n      });\n    }\n    return item;\n  }\n\n  private failProjectRunningQueueTurns(projectId: string, failure: string): void {\n    const rows = this.db.raw.prepare(`\n      SELECT id, conversation_id FROM hermes_chat_queue\n      WHERE project_id = ? AND status = 'RUNNING'\n      ORDER BY created_at, id\n    `).all(projectId) as Array<{ id?: string; conversation_id?: string }>;\n    const failedAt = this.now();\n    const message = `Hermes project runtime stopped before this instruction completed: ${failure}`.slice(0, 4_000);\n    for (const row of rows) {\n      if (!row.id || !row.conversation_id) continue;\n      this.runningQueueTurns.get(row.id)?.abort(new Error(message));\n      const updated = this.db.raw.prepare(`\n        UPDATE hermes_chat_queue\n        SET status = 'FAILED', last_error = ?, completed_at = ?, updated_at = ?\n        WHERE id = ? AND project_id = ? AND status = 'RUNNING'\n      `).run(message, failedAt, failedAt, row.id, projectId);\n      if (updated.changes !== 1) continue;\n      const item = this.requireQueueItem(projectId, row.id);\n      this.audit('hermes.chat.queue.failed', projectId, `queue=${row.id};runtime=crashed`);\n      this.publishQueueEvent(projectId, {\n        type: 'chat.queue.updated', projectId, queueId: row.id,\n        conversationId: row.conversation_id, timestamp: failedAt, item\n      });\n    }\n  }\n\n  private requireQueueItem(projectId: string, queueId: string): HermesChatQueueItem {\n    const row = this.db.raw.prepare(`\n      SELECT * FROM hermes_chat_queue WHERE id = ? AND project_id = ?\n    `).get(queueId, projectId) as unknown as ChatQueueRow | undefined;\n    if (!row) throw new Error('Hermes queue item is unavailable');\n    let position: number | null = null;\n    if (row.status === 'QUEUED') {\n      const ahead = this.db.raw.prepare(`\n        SELECT COUNT(*) AS count FROM hermes_chat_queue\n        WHERE project_id = ? AND conversation_id = ? AND status = 'QUEUED'\n          AND (created_at < ? OR (created_at = ? AND id <= ?))\n      `).get(projectId, row.conversation_id, row.created_at, row.created_at, row.id) as { count?: number } | undefined;\n      position = Number(ahead?.count ?? 1);\n    }\n    return this.toQueueItem(row, position);\n  }\n\n  private toQueueItem(row: ChatQueueRow, queuePosition: number | null): HermesChatQueueItem {\n    return {\n      id: row.id,\n      projectId: row.project_id,\n      conversationId: row.conversation_id,\n      message: row.message,\n      status: row.status,\n      queuePosition,\n      attempts: Number(row.attempts),\n      partialContent: row.stream_text ?? '',\n      activities: parseChatActivities(row.activity_json),\n      error: row.last_error ?? null,\n      cancelRequestedAt: row.cancel_requested_at === null ? null : Number(row.cancel_requested_at),\n      createdAt: Number(row.created_at),\n      startedAt: row.started_at === null ? null : Number(row.started_at),\n      completedAt: row.completed_at === null ? null : Number(row.completed_at),\n      updatedAt: Number(row.updated_at)\n    };\n  }\n\n  private reconcileStaleProfiles(): void {\n    this.db.raw.prepare(`\n      UPDATE hermes_project_profiles\n      SET status = 'stopped', service_port = NULL, proxy_port = NULL,\n          last_error = CASE WHEN status IN ('starting', 'healthy', 'degraded', 'stopping')\n            THEN 'OPC-Nexus restarted; the prior Hermes process lease was released' ELSE last_error END,\n          updated_at = ?\n      WHERE status IN ('starting', 'healthy', 'degraded', 'stopping')\n    `).run(this.now());\n  }\n\n  private runtimeState(value: string): HermesProjectBinding['status'] {\n    return ['stopped', 'starting', 'healthy', 'degraded', 'error', 'stopping'].includes(value)\n      ? value as HermesProjectBinding['status']\n      : 'error';\n  }\n\n  private async gatewaySse(\n    instance: ManagedInstance,\n    path: string,\n    body: unknown,\n    timeoutMs: number,\n    extraHeaders: Record<string, string>,\n    handlers: HermesProjectTurnStreamHandlers\n  ): Promise<Record<string, unknown>> {\n    if (!path.startsWith('/') || path.startsWith('//')) throw new Error('Hermes API path is invalid');\n    const timeoutSignal = AbortSignal.timeout(timeoutMs);\n    const signal = handlers.signal\n      ? AbortSignal.any([timeoutSignal, handlers.signal])\n      : timeoutSignal;\n    const response = await fetch(new URL(path, instance.gatewayUrl), {\n      method: 'POST',\n      signal,\n      headers: {\n        authorization: `Bearer ${instance.gatewayToken}`,\n        accept: 'text/event-stream',\n        'content-type': 'application/json',\n        ...extraHeaders\n      },\n      body: JSON.stringify(body)\n    });\n    if (!response.ok) {\n      const raw = await response.text();\n      let message = `Hermes API request failed with HTTP ${response.status}`;\n      try {\n        const payload = JSON.parse(raw) as Record<string, unknown>;\n        const error = payload.error && typeof payload.error === 'object' && !Array.isArray(payload.error)\n          ? payload.error as Record<string, unknown>\n          : {};\n        if (typeof error.message === 'string') message = error.message;\n        else if (typeof payload.message === 'string') message = payload.message;\n      } catch { /* retain the HTTP status without reflecting an arbitrary body */ }\n      throw new Error(message.slice(0, 4_000));\n    }\n    if (!String(response.headers.get('content-type') ?? '').includes('text/event-stream') || !response.body) {\n      throw new Error('Hermes streaming API returned an invalid response');\n    }\n\n    let buffer = '';\n    let responseBytes = 0;\n    let content = '';\n    let responseSessionId = '';\n    let usage: Record<string, unknown> = {};\n    let runtime: Record<string, unknown> = {};\n    let terminalError = '';\n    let runId = String(response.headers.get('x-hermes-run-id') ?? '').trim();\n    const consume = (frame: string) => {\n      let event = 'message';\n      const data: string[] = [];\n      for (const line of frame.split('\\n')) {\n        if (line.startsWith('event:')) event = line.slice(6).trim();\n        else if (line.startsWith('data:')) data.push(line.slice(5).trimStart());\n      }\n      if (data.length === 0) return;\n      let payload: Record<string, unknown>;\n      try {\n        const parsed = JSON.parse(data.join('\\n')) as unknown;\n        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return;\n        payload = parsed as Record<string, unknown>;\n      } catch { return; }\n      if (event === 'run.started') {\n        if (typeof payload.run_id === 'string') runId = payload.run_id.trim();\n        handlers.onStarted?.();\n      }\n      if (event === 'assistant.delta' && typeof payload.delta === 'string' && payload.delta) {\n        content += payload.delta;\n        handlers.onDelta?.(payload.delta);\n      }\n      if (event === 'tool.progress' && payload.tool_name === '_thinking') {\n        handlers.onActivity?.({\n          kind: 'reasoning',\n          phase: 'running',\n          toolName: null,\n          // Do not project raw chain-of-thought. The event itself is useful\n          // as a truthful progress signal; private reasoning remains in Main.\n          detail: null\n        });\n      }\n      if (event === 'tool.started' || event === 'tool.completed' || event === 'tool.failed') {\n        handlers.onActivity?.({\n          kind: 'tool',\n          phase: event === 'tool.started' ? 'running' : event === 'tool.failed' ? 'failed' : 'completed',\n          toolName: typeof payload.tool_name === 'string' ? payload.tool_name : null,\n          detail: safeHermesActivityDetail(payload.args ?? payload.preview)\n        });\n      }\n      if (event === 'assistant.completed') {\n        if (typeof payload.content === 'string') content = payload.content;\n        if (typeof payload.session_id === 'string') responseSessionId = payload.session_id;\n        if (payload.runtime && typeof payload.runtime === 'object' && !Array.isArray(payload.runtime)) {\n          runtime = payload.runtime as Record<string, unknown>;\n        }\n      }\n      if (event === 'run.completed') {\n        if (typeof payload.session_id === 'string') responseSessionId = payload.session_id;\n        if (payload.usage && typeof payload.usage === 'object' && !Array.isArray(payload.usage)) {\n          usage = payload.usage as Record<string, unknown>;\n        }\n        if (payload.runtime && typeof payload.runtime === 'object' && !Array.isArray(payload.runtime)) {\n          runtime = payload.runtime as Record<string, unknown>;\n        }\n      }\n      if (event === 'error') {\n        terminalError = typeof payload.message === 'string' ? payload.message : 'Hermes streaming turn failed';\n      }\n    };\n\n    const reader = response.body.getReader();\n    const decoder = new TextDecoder();\n    try {\n      while (true) {\n        const chunk = await reader.read();\n        if (chunk.done) break;\n        responseBytes += chunk.value.byteLength;\n        if (responseBytes > 32 * 1024 * 1024) {\n          await reader.cancel();\n          throw new Error('Hermes streaming response exceeded 32 MiB');\n        }\n        buffer += decoder.decode(chunk.value, { stream: true });\n        buffer = buffer.replace(/\\r\\n/g, '\\n');\n        let boundary = buffer.indexOf('\\n\\n');\n        while (boundary >= 0) {\n          consume(buffer.slice(0, boundary));\n          buffer = buffer.slice(boundary + 2);\n          boundary = buffer.indexOf('\\n\\n');\n        }\n      }\n    } catch (error) {\n      if (handlers.signal?.aborted && runId) {\n        await this.acknowledgeHermesSessionCancellation(instance, path, runId);\n      }\n      throw error;\n    }\n    buffer += decoder.decode();\n    if (buffer.trim()) consume(buffer);\n    if (terminalError) throw new Error(terminalError.slice(0, 4_000));\n    return {\n      session_id: responseSessionId,\n      message: { role: 'assistant', content },\n      usage,\n      runtime\n    };\n  }\n\n  private async acknowledgeHermesSessionCancellation(\n    instance: ManagedInstance,\n    streamPath: string,\n    runId: string\n  ): Promise<void> {\n    const match = /^\\/api\\/sessions\\/([^/]+)\\/chat\\/stream$/.exec(streamPath);\n    if (!match || !/^run_[A-Za-z0-9]+$/.test(runId)) return;\n    const response = await fetch(\n      new URL(`/api/sessions/${match[1]}/interrupt`, instance.gatewayUrl),\n      {\n        method: 'POST',\n        signal: AbortSignal.timeout(35_000),\n        headers: {\n          authorization: `Bearer ${instance.gatewayToken}`,\n          accept: 'application/json',\n          'content-type': 'application/json'\n        },\n        body: JSON.stringify({ run_id: runId, reason: 'Cancelled by the OPC-Nexus project owner' })\n      }\n    );\n    if (response.ok || response.status === 404 || response.status === 409) return;\n    throw new Error(`Hermes cancellation acknowledgement failed with HTTP ${response.status}`);\n  }\n\n  private async gatewayJson(\n    instance: ManagedInstance,\n    method: 'GET' | 'POST' | 'PATCH' | 'DELETE',\n    path: string,\n    body?: unknown,\n    timeoutMs = 30_000,\n    extraHeaders: Record<string, string> = {}\n  ): Promise<unknown> {\n    if (!path.startsWith('/') || path.startsWith('//')) throw new Error('Hermes API path is invalid');\n    const response = await fetch(new URL(path, instance.gatewayUrl), {\n      method,\n      signal: AbortSignal.timeout(timeoutMs),\n      headers: {\n        authorization: `Bearer ${instance.gatewayToken}`,\n        accept: 'application/json',\n        ...(body === undefined ? {} : { 'content-type': 'application/json' }),\n        ...extraHeaders\n      },\n      body: body === undefined ? undefined : JSON.stringify(body)\n    });\n    const text = await response.text();\n    let payload: unknown = null;\n    if (text) {\n      try { payload = JSON.parse(text) as unknown; }\n      catch { throw new Error(`Hermes API returned non-JSON HTTP ${response.status}`); }\n    }\n    if (!response.ok) {\n      const record = payload && typeof payload === 'object' && !Array.isArray(payload)\n        ? payload as Record<string, unknown>\n        : {};\n      const error = record.error && typeof record.error === 'object' && !Array.isArray(record.error)\n        ? record.error as Record<string, unknown>\n        : {};\n      const message = typeof error.message === 'string'\n        ? error.message\n        : typeof record.message === 'string'\n          ? record.message\n          : `Hermes API request failed with HTTP ${response.status}`;\n      throw new Error(message.slice(0, 4_000));\n    }\n    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {\n      throw new Error('Hermes API returned an invalid JSON response');\n    }\n    return payload;\n  }\n\n  private nonnegativeInteger(value: unknown): number {\n    return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : 0;\n  }\n\n  private isMissingHermesSessionError(error: unknown): boolean {\n    const message = error instanceof Error ? error.message : String(error ?? '');\n    return /(?:session|conversation)\\s+(?:not found|does not exist|unknown)/i.test(message);\n  }\n\n  private async recreateBoundProjectSession(\n    instance: ManagedInstance,\n    projectId: string,\n    binding: { conversation_id?: string; principal_id?: string; hermes_session_id?: string },\n    memoryPolicy: ConversationMemoryPolicy,\n    runtimeLock: { model: string; provider: string; require_model_lock: true }\n  ): Promise<string> {\n    const conversationId = binding.conversation_id?.trim() ?? '';\n    const previousSessionId = binding.hermes_session_id?.trim() ?? '';\n    if (!conversationId || !previousSessionId) throw new Error('Hermes session binding is incomplete');\n    const nextSessionId = `nexus_${randomUUID().replace(/-/g, '')}`;\n    await this.gatewayJson(instance, 'POST', '/api/sessions', {\n      id: nextSessionId,\n      source: 'nexus-recovery',\n      title: 'OPC-Nexus recovered project conversation',\n      nexus_memory_mode: memoryPolicy.mode,\n      nexus_memory_scope: memoryPolicy.scope,\n      ...runtimeLock\n    });\n    const updated = this.db.raw.prepare(`\n      UPDATE hermes_session_bindings\n      SET hermes_session_id = ?, last_seen_at = ?\n      WHERE project_id = ? AND conversation_id = ? AND hermes_session_id = ?\n    `).run(nextSessionId, this.now(), projectId, conversationId, previousSessionId);\n    if (Number(updated.changes ?? 0) !== 1) {\n      const current = this.db.raw.prepare(`\n        SELECT hermes_session_id FROM hermes_session_bindings\n        WHERE project_id = ? AND conversation_id = ?\n      `).get(projectId, conversationId) as { hermes_session_id?: string } | undefined;\n      if (current?.hermes_session_id && current.hermes_session_id !== previousSessionId) {\n        return current.hermes_session_id;\n      }\n      throw new Error('Hermes session binding changed during recovery');\n    }\n    this.audit(\n      'hermes.project.session.recover',\n      projectId,\n      `conversation=${conversationId};previous=${previousSessionId};current=${nextSessionId}`\n    );\n    return nextSessionId;\n  }\n\n  private reservePort(): Promise<number> {\n    return new Promise((resolvePort, reject) => {\n      const server = createServer();\n      server.once('error', reject);\n      server.listen(0, HOST, () => {\n        const address = server.address();\n        if (!address || typeof address === 'string') {\n          server.close();\n          reject(new Error('Could not reserve a Hermes loopback port'));\n          return;\n        }\n        const port = address.port;\n        server.close((error) => error ? reject(error) : resolvePort(port));\n      });\n    });\n  }\n\n  private withComponentLogs(error: unknown, instance: ManagedInstance): Error {\n    const message = error instanceof Error ? error.message : String(error);\n    const dashboard = (instance.dashboardLog ?? '').trim().slice(-2_000);\n    const gateway = (instance.gatewayLog ?? '').trim().slice(-2_000);\n    const details = [\n      dashboard ? `[dashboard]\\n${dashboard}` : '',\n      gateway ? `[gateway]\\n${gateway}` : ''\n    ].filter(Boolean).join('\\n');\n    return new Error(details ? `${message}\\n${details}` : message);\n  }\n\n  private dashboardAvailable(instance: ManagedInstance): boolean {\n    return instance.dashboardReady === true\n      || instance.status.state === 'healthy'\n      || instance.status.state === 'degraded';\n  }\n\n  private uiAvailable(instance: ManagedInstance): boolean {\n    if (!this.dashboardAvailable(instance)) return false;\n    // Keep this fallback for older test doubles and restored instances; every\n    // real HermesProxy exposes getStatus and must report its listener state.\n    const proxyStatus = instance.proxy && typeof instance.proxy.getStatus === 'function'\n      ? instance.proxy.getStatus()\n      : null;\n    return proxyStatus ? proxyStatus.running === true : true;\n  }\n\n  private diagnostic(\n    projectId: string,\n    component: 'runtime' | 'proxy' | 'dashboard' | 'gateway',\n    phase: string,\n    startedAt: number,\n    detail?: string\n  ): void {\n    this.onDiagnostic?.({\n      projectId,\n      component,\n      phase,\n      elapsedMs: Math.max(0, this.now() - startedAt),\n      ...(detail ? { detail } : {})\n    });\n  }\n\n  private audit(action: string, projectId: string, result: string): void {\n    this.db.audit({ id: randomUUID(), actor: 'system', action, target: projectId, result, source: 'hermes' });\n  }\n}\n"
    },
    {
      "path": "src/main/services/kernel/hermesIngressKernel.ts",
      "content": "import type { ControlKernel, DispatchPlanDraft, KernelRequest } from './types.js';\n\n/**\n * Compatibility guard for non-Quest ingress. Real Hermes planning runs inside\n * the project-scoped Hermes service. This kernel exists only so an old caller\n * cannot silently promote an execution adapter into the scheduler slot.\n */\nexport class HermesIngressKernel implements ControlKernel {\n  readonly id = 'hermes' as const;\n\n  isReady(): boolean {\n    return false;\n  }\n\n  async plan(_request: KernelRequest): Promise<DispatchPlanDraft> {\n    throw new Error('HERMES_PROJECT_REQUIRED: complex planning must enter the Quest Hermes project conversation');\n  }\n}\n"
    },
    {
      "path": "src/main/services/kernel/localCliDispatchAdapter.ts",
      "content": "import type { ControlKernel, DispatchPlanDraft, KernelRequest } from './types.js';\n\nconst HIGH_RISK_RE = /(?:删除|清空|覆盖|格式化|付款|转账|采购|下单|发布|部署|安装|卸载|上传|导出|外发|授权|提权|管理员|发信|群发|delete|remove|overwrite|truncate|drop\\s+(?:table|database)|format\\s+(?:disk|drive)|diskpart|pay|transfer|purchase|deploy|publish|install|uninstall|upload|exfiltrat|export|grant|chmod|chown|admin|send\\s+(?:an?\\s+)?(?:email|message))/i;\nconst LOW_RISK_RE = /(?:总结|摘要|分析|解释|翻译|分类|提取|整理|草拟|起草|检查|审查|比较|列出|查询|阅读|summari[sz]e|analy[sz]e|explain|translate|classify|extract|organize|draft|review|compare|list|query|read|inspect)/i;\n\nfunction titleFor(message: string): string {\n  const firstLine = message.split(/\\r?\\n/, 1)[0].trim().replace(/\\s+/g, ' ');\n  return (firstLine || '员工任务').slice(0, 200);\n}\n\n/**\n * Deterministic adapter for a user-selected worker CLI. It does not choose a\n * worker, clarify an objective, split work, or act as a scheduler. Hermes owns\n * those responsibilities; every CLI is treated as an execution adapter.\n */\nexport class LocalCliDispatchAdapter implements ControlKernel {\n  readonly id = 'local-cli' as const;\n\n  isReady(): boolean {\n    return true;\n  }\n\n  async plan(request: KernelRequest): Promise<DispatchPlanDraft> {\n    if (request.routingMode !== 'direct-worker') {\n      throw new Error('Local CLI dispatch requires an explicit direct-worker route');\n    }\n    if (!request.preferredAgentId) {\n      throw new Error('Local CLI dispatch requires an explicitly selected employee');\n    }\n    const worker = request.workers.find((candidate) => candidate.agentId === request.preferredAgentId);\n    if (!worker) throw new Error('The selected Local CLI employee is not eligible');\n    return {\n      workerAgentId: worker.agentId,\n      title: titleFor(request.message),\n      objective: request.message.trim(),\n      rationale: '用户明确选择该员工；治理插件仅执行直达适配，不参与规划或选人。',\n      priority: 0,\n      expectedOutputs: ['所选员工返回的可核验结果'],\n      requiresHumanApproval: HIGH_RISK_RE.test(request.message) || !LOW_RISK_RE.test(request.message),\n      memoryProposals: [],\n      taskScheduleProposals: []\n    };\n  }\n}\n"
    },
    {
      "path": "src/main/services/orchestrator.ts",
      "content": "/**\n * Agent 编排器（PRD 7/8 章）\n * - 分层状态机：Agent 生命周期 / Task / Engine / Channel 互不混用（7.3）\n * - FIFO 队列 + 固定并发（6.2：V1.0 基础调度）\n * - 首页派生状态互斥归类：异常/离线 > 执行中/待审批 > 暂停 > 排队/启动中 > 空闲\n * - 崩溃恢复：启动时扫描 RUNNING 记录，无法恢复的标记 INTERRUPTED（13.2）\n * - 自动补位（replenishTasks）默认关闭：它会生成用户从未派发的任务，\n *   开启后统计口径不再可信，仅供演示环境显式启用\n *\n * @author liyingjie <y@senke.com>\n */\nimport { randomUUID } from 'node:crypto';\nimport { join } from 'node:path';\nimport { existsSync, mkdirSync, readdirSync, rmdirSync } from 'node:fs';\nimport { app } from 'electron';\nimport type { Database } from './database.js';\nimport type { ExecutorRegistry } from './executor/index.js';\nimport type { ExecutionBinding, ExecutorCallbacks } from './executor/types.js';\nimport type { ApprovalBroker, ApprovalRequest } from './approvalBroker.js';\nimport type { ToolHost } from './executor/tools.js';\nimport type { DatabaseKernelState } from './kernel/databaseKernelState.js';\nimport type { DispatchPlan, KernelRequest } from './kernel/types.js';\nimport { notify } from './notifier.js';\nimport { loadUserConfig } from './userConfig.js';\nimport { MAX_TASK_OUTPUT_CHARS } from './textEncoding.js';\nimport { ANDROID_OPERATOR_ENGINE_ID, assertAndroidOperatorEngine } from './mobileEnginePolicy.js';\nimport type {\n  Agent, AgentCardView, Approval, ApprovalScope, CreateAgentInput, DashboardStats, DerivedAgentStatus,\n  EngineStatus, ProjectArtifactManifest, Task, TaskEvent, TaskQuality, TaskStatus, TodoItem\n} from '../../shared/types.js';\nimport { engineDisplayName } from '../../shared/engineVisibility.js';\n\ntype Row = Record<string, unknown>;\n\nexport function ownerFacingEngineName(engineId: string, name: string | undefined): string {\n  return engineDisplayName(engineId, name);\n}\n\nexport interface AgentCreationCheckpoint {\n  existing: Row | null;\n  autoWorkspacePath: string | null;\n  autoWorkspaceExisted: boolean;\n}\n\nexport type CreateTaskResult = Task & { deduplicated?: true };\n\nexport interface TaskFinishedInfo {\n  taskId: string;\n  agentId: string;\n  status: 'COMPLETED' | 'FAILED' | 'INTERRUPTED' | 'CANCELLED';\n  title: string;\n  result: string | null;\n  error: string | null;\n}\n\nexport interface CreateTaskOptions {\n  parentId?: string;\n  /** Durable task prerequisites. A task cannot dispatch until all are COMPLETED. */\n  dependencyTaskIds?: string[];\n  sessionId?: string;\n  workspaceOverride?: string;\n  projectId?: string;\n  engineOverride?: string;\n  sourceKey?: string;\n  conversationId?: string;\n  inputMessageId?: string;\n  content?: string;\n  priority?: number;\n  initialApprovalRequest?: string;\n  /** Same-agent engine handoff is intentional; ordinary A2A delegation may\n   * never target an employee already present in the ancestor chain. */\n  allowAncestorAgentDelegation?: boolean;\n  /** Main-process commit hook. Runs in the task transaction before any Worker starts. */\n  onPersisted?: (taskId: string) => void;\n  /** Project tasks require real file evidence by default; pure conversation tasks opt out explicitly. */\n  requiresArtifacts?: boolean;\n}\n\nexport interface ProjectArtifactCompletionValidator {\n  validateTaskCompletion(input: {\n    taskId: string;\n    projectId: string;\n    startedAt: number;\n    endedAt: number;\n  }): Promise<{ ok: true; manifest: ProjectArtifactManifest } | { ok: false; error: string }>;\n}\n\nconst STAGES = ['理解需求', '规划步骤', '调用工具', '生成产物', '校验结果'];\n\nconst MAX_TASK_OUTPUT_EVENTS = 512;\nconst MAX_TASK_EVENTS_QUERY = 1000;\nconst MAX_TASK_RESULT_CHARS = 16_000;\nconst MAX_TASK_DEPENDENCIES = 128;\nconst OUTPUT_STATE_TTL_MS = 60_000;\nconst DISPATCH_PLAN_APPROVAL_TYPE = 'dispatch_plan';\nconst ACTIVE_TASK_STATUSES = ['QUEUED', 'RUNNING', 'WAITING_APPROVAL', 'PAUSED'] as const;\nconst TERMINAL_TASK_STATUSES = ['COMPLETED', 'FAILED', 'CANCELLED', 'INTERRUPTED'] as const;\nconst MAX_DELEGATION_ANCESTRY = 100;\n\nconst EXPLICIT_AUTH_FAILURE_PATTERNS = [\n  /^(?:error:\\s*)?HTTP\\s+(?:401|403)\\b/i,\n  /^(?:error:\\s*)?(?:api|provider|model)(?:\\s+request)?(?:\\s+failed)?[^\\r\\n]{0,80}\\b(?:401|403)\\b/i,\n  /^(?:error:\\s*)?(?:api\\s+)?request\\s+failed\\s+with\\s+status(?:\\s+code)?\\s+(?:401|403)\\b/i,\n  /^Hermes\\s+(?:\\u6267\\u884c\\u5931\\u8d25|execution failed)\\s*[:\\uff1a]\\s*HTTP\\s+(?:401|403)\\b/i,\n  /^(?:\\u6a21\\u578b)?\\u4f9b\\u5e94\\u5546\\u8fd4\\u56de\\s+HTTP\\s+(?:401|403)\\b/i,\n  /\\bmissing authentication(?:\\s+header)?\\b/i,\n  /\\bno usable credentials\\b/i,\n  /\\b(?:invalid|expired|missing|revoked)\\s+(?:api[ _-]?)?(?:key|token|credential)s?\\b/i,\n  /\\b(?:api[ _-]?key|credential|access token)\\s+(?:is\\s+)?(?:invalid|expired|missing|revoked)\\b/i,\n  /^(?:error:\\s*)?(?:unauthorized|forbidden)\\b/i,\n  /(?:\\u6a21\\u578b\\u4f9b\\u5e94\\u5546|API|Provider).{0,24}(?:\\u9274\\u6743\\u5931\\u8d25|\\u51ed\\u636e\\u65e0\\u6548|\\u51ed\\u636e\\u8fc7\\u671f|\\u672a\\u6388\\u6743)/i\n];\n\n/** Only trusted provider/CLI authentication diagnostics may demote an engine. */\nfunction isExecutorAuthenticationFailure(error: string | undefined): boolean {\n  if (!error) return false;\n  const detail = error.trim();\n  return detail.length > 0 && EXPLICIT_AUTH_FAILURE_PATTERNS.some((pattern) => pattern.test(detail));\n}\n\nfunction approvalScope(type: unknown): ApprovalScope {\n  // `tool` was briefly used for plan approvals before scopes were explicit.\n  return type === DISPATCH_PLAN_APPROVAL_TYPE || type === 'tool' ? 'dispatch_plan' : 'runtime_tool';\n}\n\ninterface TaskOutputState {\n  chars: number;\n  events: number;\n  truncated: boolean;\n  closed: boolean;\n}\n\ninterface CancelledTaskRecord {\n  id: string;\n  agentId: string;\n  title: string;\n  error: string;\n}\n\ninterface TaskDependencyGate {\n  ready: boolean;\n  pending: string[];\n  failed: string[];\n}\n\nexport class Orchestrator {\n  private listeners = new Set<() => void>();\n  /** 任务输出流式订阅（推送到渲染进程逐字显示） */\n  private outputListeners = new Set<(taskId: string, chunk: string) => void>();\n  /** Per-task output budget. Prevents a verbose CLI from filling SQLite and\n   * the renderer with one event per token forever. */\n  private outputStates = new Map<string, TaskOutputState>();\n  /** Resume requests made while an aborted ACP child is still closing. */\n  private resumeAfterRelease = new Set<string>();\n  /** 任务终态订阅（webhook、canonical conversation 等）。 */\n  private finishListeners = new Set<(info: TaskFinishedInfo) => void>();\n  private schedulerTimer: NodeJS.Timeout | null = null;\n  private lastEmit = 0;\n  private emitTimer: NodeJS.Timeout | null = null;\n  /** Prevent recursive cross-agent wakeups from re-entering one FIFO queue. */\n  private schedulingAgents = new Set<string>();\n  /** Executor completion can wait for asynchronous project artifact hashing. */\n  private finalizingTasks = new Set<string>();\n  /** 调度保护门禁（由 main 注入，基于资源监控）：返回非空字符串 = 阻止派发的原因 */\n  private dispatchGuard: () => string | null = () => null;\n  private projectWorkspaceResolver: ((projectId: string) => string | null) | null = null;\n  private projectArtifactCompletionValidator: ProjectArtifactCompletionValidator | null = null;\n  private mobileDispatchPolicy: {\n    canDispatch(agentId: string): { bound: boolean; ready: boolean; reason: string };\n    releaseAgent?(agentId: string): void;\n  } | null = null;\n\n  constructor(private db: Database, private executors: ExecutorRegistry, private broker: ApprovalBroker) {\n    this.broker.setStateController?.({\n      request: (request, approvalId, now) => this.requestRuntimeApproval(request, approvalId, now),\n      abandon: (taskId, approvalId, now) => this.abandonRuntimeApproval(taskId, approvalId, now)\n    });\n  }\n\n  /** Production injects the Main-approved project directory resolver. */\n  setProjectWorkspaceResolver(resolver: (projectId: string) => string | null): void {\n    this.projectWorkspaceResolver = resolver;\n  }\n\n  setProjectArtifactCompletionValidator(validator: ProjectArtifactCompletionValidator): void {\n    this.projectArtifactCompletionValidator = validator;\n  }\n\n  private resolveProjectWorkspace(projectId: string | null, requested?: string): string | null {\n    if (!projectId) return requested?.trim() || null;\n    if (!this.projectWorkspaceResolver) return requested?.trim() || null;\n    const workspace = this.projectWorkspaceResolver(projectId)?.trim() ?? '';\n    if (!workspace) throw new Error('请先为项目选择工作目录，再开始执行');\n    return workspace;\n  }\n\n  private requestRuntimeApproval(req: ApprovalRequest, approvalId: string, now: number): void {\n    this.db.transaction(() => {\n      const task = this.db.raw.prepare('SELECT agent_id, status FROM tasks WHERE id = ?').get(req.taskId) as\n        | { agent_id: string; status: TaskStatus }\n        | undefined;\n      if (!task || task.agent_id !== req.agentId || task.status !== 'RUNNING') {\n        throw new Error('runtime approval requires a running task owned by the requesting agent');\n      }\n      this.db.raw.prepare(\n        'INSERT INTO approvals(id, task_id, agent_id, type, request, risk, status, created_at, decided_at) VALUES(?, ?, ?, ?, ?, ?, ?, ?, NULL)'\n      ).run(approvalId, req.taskId, req.agentId, req.type, req.request, req.risk, 'pending', now);\n      const changed = this.db.raw.prepare(\n        \"UPDATE tasks SET status = 'WAITING_APPROVAL' WHERE id = ? AND status = 'RUNNING'\"\n      ).run(req.taskId).changes;\n      if (changed !== 1) throw new Error('runtime approval task transition conflicted');\n      this.recordEvent(req.taskId, 'approval_required', {\n        approvalId,\n        scope: 'runtime_tool',\n        request: req.request,\n        risk: req.risk\n      }, now);\n    });\n  }\n\n  private abandonRuntimeApproval(taskId: string, approvalId: string, now: number): void {\n    this.db.transaction(() => {\n      const changed = this.db.raw.prepare(\n        \"UPDATE approvals SET status = 'rejected', decided_at = ? WHERE id = ? AND task_id = ? AND status = 'pending'\"\n      ).run(now, approvalId, taskId).changes;\n      if (changed > 0) {\n        this.recordEvent(taskId, 'approval_decided', {\n          approvalId,\n          scope: 'runtime_tool',\n          approved: false,\n          reason: 'task_abandoned'\n        }, now);\n      }\n    });\n  }\n\n  setDispatchGuard(fn: () => string | null) {\n    this.dispatchGuard = fn;\n  }\n\n  setMobileDispatchPolicy(policy: {\n    canDispatch(agentId: string): { bound: boolean; ready: boolean; reason: string };\n    releaseAgent?(agentId: string): void;\n  }) {\n    this.mobileDispatchPolicy = policy;\n  }\n\n  private delegationOrganization(parentTaskId: string): string | null {\n    const parent = this.db.raw.prepare(\n      'SELECT agent_id FROM tasks WHERE id = ? AND deleted_at IS NULL'\n    ).get(parentTaskId) as { agent_id: string } | undefined;\n    if (!parent) return null;\n    const owner = this.db.raw.prepare(\n      'SELECT organization_id, archived FROM agents WHERE id = ?'\n    ).get(parent.agent_id) as { organization_id: string | null; archived: number } | undefined;\n    if (!owner || owner.archived !== 0) return null;\n    const organizationId = owner?.organization_id?.trim() ?? '';\n    return organizationId || null;\n  }\n\n  private agentOrganization(agentId: string): string | null {\n    const row = this.db.raw.prepare(\n      'SELECT organization_id FROM agents WHERE id = ?'\n    ).get(agentId) as { organization_id: string | null } | undefined;\n    const organizationId = row?.organization_id?.trim() ?? '';\n    return organizationId || null;\n  }\n\n  private parentTaskAssociation(parentTaskId: string): { organizationId: string; projectId: string | null } | null {\n    const parent = this.db.raw.prepare(\n      'SELECT agent_id, project_id FROM tasks WHERE id = ? AND deleted_at IS NULL'\n    ).get(parentTaskId) as { agent_id: string; project_id: string | null } | undefined;\n    if (!parent) return null;\n    const organizationId = this.agentOrganization(parent.agent_id);\n    return organizationId ? { organizationId, projectId: parent.project_id ?? null } : null;\n  }\n\n  /** Resolve inherited project ownership and enforce the task tenant boundary. */\n  private resolveTaskProject(agentId: string, parentTaskId?: string, requestedProjectId?: string): string | null {\n    const organizationId = this.agentOrganization(agentId);\n    if (!organizationId) throw new Error('\\u5458\\u5de5\\u4e0d\\u5b58\\u5728');\n\n    const parent = parentTaskId ? this.parentTaskAssociation(parentTaskId) : null;\n    if (parentTaskId && (!parent || parent.organizationId !== organizationId)) {\n      throw new Error('\\u7236\\u4efb\\u52a1\\u4e0d\\u5b58\\u5728\\u6216\\u4e0d\\u53ef\\u5173\\u8054');\n    }\n\n    const projectId = requestedProjectId ?? parent?.projectId ?? null;\n    if (!projectId) return null;\n    const project = this.db.raw.prepare(\n      \"SELECT id, organization_id FROM projects WHERE id = ? AND status != 'archived'\"\n    ).get(projectId) as { id: string; organization_id: string | null } | undefined;\n    if (!project || project.organization_id?.trim() !== organizationId) {\n      throw new Error('\\u9879\\u76ee\\u4e0d\\u5b58\\u5728\\u6216\\u5df2\\u5f52\\u6863');\n    }\n    return projectId;\n  }\n\n  private assertDelegationTarget(parentTaskId: string, targetAgentId: string, allowCurrentAgent = false): void {\n    const parent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentTaskId) as Row | undefined;\n    if (!parent) throw new Error('父任务不存在，或目标员工不可委派');\n\n    // A task that has already left the live state machine cannot create new\n    // work. This closes the race where cancellation wins after lookup but\n    // before the delegated INSERT transaction.\n    if (!ACTIVE_TASK_STATUSES.includes(parent.status as typeof ACTIVE_TASK_STATUSES[number])) {\n      throw new Error('父任务已经结束，不能继续委派');\n    }\n    // Validate the existing parent chain before accepting another edge. The\n    // normal INSERT path always creates a fresh UUID, but this guard protects\n    // against imported/corrupted rows and makes cycle failures explicit.\n    const seen = new Set<string>();\n    let current: Row | undefined = parent;\n    let depth = 0;\n    while (current) {\n      const currentId = String(current.id ?? '');\n      if (!currentId || seen.has(currentId)) {\n        throw new Error('父任务祖先链存在循环，无法委派');\n      }\n      seen.add(currentId);\n      const isImmediateParent = currentId === parentTaskId;\n      if (current.agent_id === targetAgentId && !(allowCurrentAgent && isImmediateParent)) {\n        throw new Error('委派目标已出现在祖先任务链中，不能形成员工循环委派');\n      }\n      depth += 1;\n      if (depth > MAX_DELEGATION_ANCESTRY) {\n        throw new Error('父任务祖先链过深或存在循环，无法委派');\n      }\n      // parent_id also links independent desktop follow-ups/retries. Only a\n      // consecutive delegated edge represents an active wait relationship.\n      if (current.source !== 'delegated') break;\n      const ancestorId = typeof current.parent_id === 'string' && current.parent_id.length > 0\n        ? current.parent_id\n        : null;\n      if (!ancestorId) break;\n      current = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(ancestorId) as Row | undefined;\n      if (!current) throw new Error('父任务祖先链无效，无法委派');\n    }\n    if (!this.delegationChainIsLive(parent)) {\n      throw new Error('父任务的委派祖先已经结束，不能继续委派');\n    }\n\n    const organizationId = this.delegationOrganization(parentTaskId);\n    const target = organizationId\n      ? this.db.raw.prepare(\n          \"SELECT id FROM agents WHERE id = ? AND organization_id = ? AND archived = 0 AND lifecycle = 'READY'\"\n        ).get(targetAgentId, organizationId) as { id: string } | undefined\n      : undefined;\n    if (!target) throw new Error('父任务不存在，或目标员工不可委派');\n  }\n\n  /** A delegated task is runnable only while every delegated parent edge\n   * leads to a live task. Desktop follow-ups deliberately terminate the walk. */\n  private delegationChainIsLive(task: Row): boolean {\n    const seen = new Set<string>();\n    let current: Row | undefined = task;\n    while (current?.source === 'delegated') {\n      const currentId = String(current.id ?? '');\n      const parentId = typeof current.parent_id === 'string' && current.parent_id.length > 0\n        ? current.parent_id\n        : null;\n      if (!currentId || !parentId || seen.has(currentId) || seen.has(parentId)) return false;\n      seen.add(currentId);\n      const parent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentId) as Row | undefined;\n      if (!parent || !ACTIVE_TASK_STATUSES.includes(parent.status as typeof ACTIVE_TASK_STATUSES[number])) return false;\n      current = parent;\n    }\n    return true;\n  }\n\n  private queuedDelegations(): { id: string; parent_id: string; agent_id: string }[] {\n    return this.db.raw.prepare(\n      \"SELECT id, parent_id, agent_id FROM tasks WHERE source = 'delegated' AND status = 'QUEUED' AND deleted_at IS NULL\"\n    ).all() as { id: string; parent_id: string; agent_id: string }[];\n  }\n\n  private activeDelegations(): Row[] {\n    return this.db.raw.prepare(\n      \"SELECT * FROM tasks WHERE source = 'delegated' AND status IN ('QUEUED','RUNNING','WAITING_APPROVAL','PAUSED') AND deleted_at IS NULL\"\n    ).all() as Row[];\n  }\n\n  /** Find delegated work that must be abandoned when its parent tree is being\n   * interrupted. This includes running/approval/paused children, not only the\n   * queued rows that the FIFO scheduler could otherwise start later. */\n  private recoveryDelegationIds(interruptedIds: ReadonlySet<string>): Set<string> {\n    const result = new Set<string>();\n    for (const child of this.activeDelegations()) {\n      const seen = new Set<string>();\n      let parentId = typeof child.parent_id === 'string' && child.parent_id.length > 0 ? child.parent_id : null;\n      while (parentId) {\n        if (interruptedIds.has(parentId)) {\n          result.add(String(child.id));\n          break;\n        }\n        if (seen.has(parentId)) {\n          result.add(String(child.id));\n          break;\n        }\n        seen.add(parentId);\n        const parent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentId) as Row | undefined;\n        if (!parent || !ACTIVE_TASK_STATUSES.includes(parent.status as typeof ACTIVE_TASK_STATUSES[number])) {\n          result.add(String(child.id));\n          break;\n        }\n        if (parent.source !== 'delegated') break;\n        parentId = typeof parent.parent_id === 'string' && parent.parent_id.length > 0 ? parent.parent_id : null;\n      }\n    }\n    return result;\n  }\n\n  private activeTaskOccupants(): { id: string; agent_id: string; status: TaskStatus }[] {\n    return this.db.raw.prepare(\n      \"SELECT id, agent_id, status FROM tasks WHERE status IN ('RUNNING','PAUSED') AND deleted_at IS NULL\"\n    ).all() as { id: string; agent_id: string; status: TaskStatus }[];\n  }\n\n  /**\n   * Reject a newly queued delegation only when the wait cycle is a hard\n   * deadlock. An employee-level cycle is not sufficient with concurrency > 1:\n   * another active task may finish and release a slot. Every slot on every\n   * employee in the cycle must be occupied by a task whose queued children all\n   * remain inside that same cycle.\n   */\n  private assertNoDelegationWaitCycle(parentTaskId: string, targetAgentId: string): void {\n    const parent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentTaskId) as Row | undefined;\n    if (!parent) throw new Error('父任务不存在，无法检查委派等待关系');\n    const parentAgentId = String(parent.agent_id ?? '');\n    const graph = new Map<string, Set<string>>();\n    const queuedByParent = new Map<string, Set<string>>();\n    for (const edge of this.queuedDelegations()) {\n      const edgeParent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(edge.parent_id) as Row | undefined;\n      if (!edgeParent\n        || !ACTIVE_TASK_STATUSES.includes(edgeParent.status as typeof ACTIVE_TASK_STATUSES[number])\n        || !this.delegationChainIsLive(edgeParent)) continue;\n      const from = String(edgeParent.agent_id ?? '');\n      const to = String(edge.agent_id ?? '');\n      if (!from || !to) continue;\n      const outgoing = queuedByParent.get(edge.parent_id) ?? new Set<string>();\n      outgoing.add(to);\n      queuedByParent.set(edge.parent_id, outgoing);\n      const targets = graph.get(from) ?? new Set<string>();\n      targets.add(to);\n      graph.set(from, targets);\n    }\n\n    // The edge being inserted is not visible in queuedDelegations() yet.\n    const pendingOutgoing = queuedByParent.get(parentTaskId) ?? new Set<string>();\n    pendingOutgoing.add(targetAgentId);\n    queuedByParent.set(parentTaskId, pendingOutgoing);\n    const parentTargets = graph.get(parentAgentId) ?? new Set<string>();\n    parentTargets.add(targetAgentId);\n    graph.set(parentAgentId, parentTargets);\n\n    const findPath = (current: string, target: string, visited: Set<string>): string[] | null => {\n      if (current === target) return [current];\n      if (visited.has(current)) return null;\n      visited.add(current);\n      for (const next of graph.get(current) ?? []) {\n        const tail = findPath(next, target, visited);\n        if (tail) return [current, ...tail];\n      }\n      return null;\n    };\n    const cyclePath = findPath(targetAgentId, parentAgentId, new Set<string>());\n    if (!cyclePath) return;\n    const cycleAgents = new Set(cyclePath);\n    const occupants = this.activeTaskOccupants();\n    const occupantsByAgent = new Map<string, typeof occupants>();\n    for (const task of occupants) {\n      const list = occupantsByAgent.get(task.agent_id) ?? [];\n      list.push(task);\n      occupantsByAgent.set(task.agent_id, list);\n    }\n    for (const agentId of cycleAgents) {\n      const agent = this.getAgent(agentId);\n      const limit = Math.max(1, agent?.concurrencyLimit ?? 1);\n      if (this.agentOccupancy(agentId) < limit) return;\n      const blocked = (occupantsByAgent.get(agentId) ?? []).filter((task) => {\n        const targets = queuedByParent.get(task.id);\n        return Boolean(targets && targets.size > 0 && [...targets].every((target) => cycleAgents.has(target)));\n      }).length;\n      if (blocked < limit) return;\n    }\n    throw new Error('委派等待关系会形成员工循环，子任务无法取得执行槽');\n  }\n\n  /**\n   * Check whether a child assigned to an employee can acquire a slot while\n   * its parent is still executing. In particular, coding delegation keeps the\n   * same employee and otherwise self-deadlocks at concurrency=1.\n   */\n  private delegationCapacity(agentId: string, parentTaskId: string): {\n    available: boolean;\n    active: number;\n    limit: number;\n    reason?: string;\n  } {\n    const parent = this.db.raw.prepare('SELECT agent_id, status FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentTaskId) as\n      { agent_id: string; status: TaskStatus } | undefined;\n    const agent = this.getAgent(agentId);\n    if (!parent) {\n      return { available: false, active: 0, limit: 0, reason: '父任务不存在，无法创建编码委派' };\n    }\n    if (parent.agent_id !== agentId) {\n      return { available: false, active: 0, limit: 0, reason: '编码委派必须保留父任务的员工归属，只能覆盖执行引擎' };\n    }\n    if (!ACTIVE_TASK_STATUSES.includes(parent.status as typeof ACTIVE_TASK_STATUSES[number])) {\n      return { available: false, active: 0, limit: 0, reason: '父任务已经结束，不能创建编码委派' };\n    }\n    if (!agent || agent.archived || agent.lifecycle !== 'READY') {\n      return { available: false, active: 0, limit: 0, reason: '父任务员工当前不可用，无法创建编码委派' };\n    }\n    const limit = Math.max(1, agent.concurrencyLimit);\n    const active = this.agentOccupancy(agentId);\n    if (active >= limit) {\n      return {\n        available: false,\n        active,\n        limit,\n        reason: `当前员工「${agent.name}」并发槽已占满（${active}/${limit}），编码委派会等待父任务释放自身槽位而自锁；请提高并发上限，或改用 delegate_task 委派给其他员工`\n      };\n    }\n    return { available: true, active, limit };\n  }\n\n  /** delegate_task 工具的编排能力（P3b A2A 内部委派） */\n  toolHost(): ToolHost {\n    return {\n      findAgentIdByName: (name, parentTaskId) => {\n        // 名称解析与父任务同租户；创建时还会在写事务内二次校验。\n        const organizationId = this.delegationOrganization(parentTaskId);\n        if (!organizationId) return null;\n        const r = this.db.raw.prepare(\n          \"SELECT id FROM agents WHERE name = ? AND organization_id = ? AND archived = 0 AND lifecycle = 'READY'\"\n        ).get(name, organizationId) as { id: string } | undefined;\n        return r?.id ?? null;\n      },\n      createDelegatedTask: (agentId, title, parentTaskId) => this.createTask(agentId, title, 'delegated', { parentId: parentTaskId }),\n      // E-2 编码委派：员工归属不变，仅把执行引擎覆盖为编码引擎\n      createEngineDelegatedTask: (agentId, title, parentTaskId, engineId) => {\n        const capacity = this.delegationCapacity(agentId, parentTaskId);\n        if (!capacity.available) throw new Error(capacity.reason ?? '当前无法创建编码委派');\n        // codingEngineReady is a UI/tool-registration hint; the durable\n        // creation boundary must recheck because engine state can change\n        // between discovery and invocation.\n        const engine = this.db.raw.prepare('SELECT status FROM engines WHERE id = ?').get(engineId) as { status: string } | undefined;\n        if (engine?.status !== 'HEALTHY') throw new Error('编码委派目标引擎不存在或当前不可用');\n        return this.createTask(agentId, title, 'delegated', {\n          parentId: parentTaskId,\n          engineOverride: engineId,\n          allowAncestorAgentDelegation: true\n        });\n      },\n      delegationCapacity: (agentId, parentTaskId) => this.delegationCapacity(agentId, parentTaskId),\n      codingEngineReady: () => {\n        const engineId = 'eng-opencode';\n        const row = this.db.raw.prepare('SELECT name, status FROM engines WHERE id = ?').get(engineId) as { name: string; status: string } | undefined;\n        return { ready: row?.status === 'HEALTHY', engineId, name: row?.name ?? 'OpenCode' };\n      },\n      cancelTask: (taskId, reason) => this.cancelTask(taskId, reason),\n      waitForTask: (taskId, timeoutMs, parentTaskId) => this.waitForTask(taskId, timeoutMs, parentTaskId),\n      delegationDepth: (taskId) => {\n        let depth = 0;\n        let cur: string | null = taskId;\n        const seen = new Set<string>();\n        while (cur) {\n          if (seen.has(cur)) throw new Error('父任务祖先链存在循环，无法委派');\n          seen.add(cur);\n          const r = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(cur) as Row | undefined;\n          if (!r || r.source !== 'delegated' || typeof r.parent_id !== 'string' || !r.parent_id) break;\n          depth++;\n          if (depth > MAX_DELEGATION_ANCESTRY) throw new Error('父任务祖先链过深或存在循环，无法委派');\n          cur = r.parent_id;\n        }\n        return depth;\n      }\n    };\n  }\n\n  onChange(fn: () => void): () => void {\n    this.listeners.add(fn);\n    return () => this.listeners.delete(fn);\n  }\n\n  /** 订阅任务输出流（用于流式推送到渲染进程） */\n  onOutput(fn: (taskId: string, chunk: string) => void): () => void {\n    this.outputListeners.add(fn);\n    return () => this.outputListeners.delete(fn);\n  }\n\n  /** 订阅任务终态（执行器回调驱动；用于对外通知渠道） */\n  onTaskFinished(fn: (info: TaskFinishedInfo) => void): () => void {\n    this.finishListeners.add(fn);\n    return () => this.finishListeners.delete(fn);\n  }\n\n  /** 快照推送节流（300ms）：执行器高频进度回调下避免全量快照洪泛，并保证尾随一次 */\n  private emit() {\n    const now = Date.now();\n    const elapsed = now - this.lastEmit;\n    if (elapsed >= 300 && !this.emitTimer) {\n      this.lastEmit = now;\n      for (const fn of this.listeners) fn();\n      return;\n    }\n    if (!this.emitTimer) {\n      this.emitTimer = setTimeout(() => {\n        this.emitTimer = null;\n        this.lastEmit = Date.now();\n        for (const fn of this.listeners) fn();\n      }, 300 - elapsed);\n    }\n  }\n\n  /** 崩溃恢复：保留尚未执行的计划审批；其余无主运行态中断并关闭运行时审批。 */\n  recoverAfterRestart() {\n    const active = this.db.raw.prepare(\"SELECT id, status FROM tasks WHERE status IN ('RUNNING','WAITING_APPROVAL','PAUSED')\").all() as { id: string; status: TaskStatus }[];\n    const pendingApprovals = active.length > 0\n      ? this.db.raw.prepare(\"SELECT * FROM approvals WHERE status = 'pending'\").all() as Row[]\n      : [];\n    const durablePlanTasks = new Set(\n      pendingApprovals\n        .filter((approval) => approvalScope(approval.type) === 'dispatch_plan')\n        .map((approval) => approval.task_id as string)\n    );\n    const interruptedCandidates = active.filter((task) =>\n      task.status !== 'WAITING_APPROVAL' || !durablePlanTasks.has(task.id)\n    );\n    const recoveryDelegationIds = this.recoveryDelegationIds(new Set(interruptedCandidates.map((task) => task.id)));\n    // Delegated descendants are abandoned as CANCELLED. A delegated row may\n    // itself appear in the active scan; remove it from the INTERRUPTED set so\n    // one task receives one terminal transition and one finish notification.\n    const interrupted = interruptedCandidates.filter((task) => !recoveryDelegationIds.has(task.id));\n    const now = Date.now();\n    const cancelled: CancelledTaskRecord[] = [];\n    if (interrupted.length > 0 || recoveryDelegationIds.size > 0) {\n      this.db.transaction(() => {\n        for (const t of interrupted) {\n          this.db.raw.prepare(\"UPDATE tasks SET status = 'INTERRUPTED', ended_at = ?, error = '客户端异常退出，任务中断' WHERE id = ?\").run(now, t.id);\n          this.db.raw.prepare(\"UPDATE agent_runs SET ended_at = ?, status = 'INTERRUPTED' WHERE task_id = ? AND ended_at IS NULL\").run(now, t.id);\n          // Mobile leases live in SQLite, while the gateway's in-memory token\n          // map cannot survive a process restart. Close the lease together with\n          // the interrupted task so a reconnect is not blocked by stale state.\n          this.db.raw.prepare(\n            \"UPDATE mobile_control_sessions SET status = 'disconnected', ended_at = COALESCE(ended_at, ?) WHERE task_id = ? AND status = 'active'\"\n          ).run(now, t.id);\n          this.recordEvent(t.id, 'interrupted', { reason: 'app-restart' }, now);\n          for (const approval of pendingApprovals.filter((item) => item.task_id === t.id)) {\n            this.db.raw.prepare(\"UPDATE approvals SET status = ?, decided_at = ? WHERE id = ? AND status = 'pending'\").run('rejected', now, approval.id as string);\n            this.recordEvent(t.id, 'approval_decided', {\n              approvalId: approval.id,\n              scope: approvalScope(approval.type),\n              approved: false,\n              reason: 'runtime_interrupted_on_restart'\n            }, now);\n          }\n        }\n        for (const taskId of recoveryDelegationIds) {\n          const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as Row | undefined;\n          if (!row || !ACTIVE_TASK_STATUSES.includes(row.status as typeof ACTIVE_TASK_STATUSES[number])) continue;\n          const error = '上级委派在应用重启前已结束，委派已取消';\n          if (!this.cancelTaskInternal(taskId, now, error)) continue;\n          this.db.raw.prepare(\n            \"UPDATE mobile_control_sessions SET status = 'disconnected', ended_at = COALESCE(ended_at, ?) WHERE task_id = ? AND status = 'active'\"\n          ).run(now, taskId);\n          cancelled.push({\n            id: taskId,\n            agentId: String(row.agent_id),\n            title: String(row.title ?? taskId),\n            error\n          });\n        }\n      });\n      this.releaseCancelledTasks(cancelled);\n    }\n\n    for (const task of interrupted) this.settleTaskDependents(task.id, 'INTERRUPTED', '前置任务在应用重启时中断');\n    for (const task of cancelled) this.settleTaskDependents(task.id, 'CANCELLED', task.error);\n\n    if (interrupted.length === 0 && cancelled.length === 0) return;\n    this.notifyCancelledTasks(cancelled);\n    for (const task of interrupted) {\n      const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(task.id) as Row | undefined;\n      if (!row) continue;\n      for (const fn of this.finishListeners) {\n        try {\n          fn({\n            taskId: task.id,\n            agentId: String(row.agent_id),\n            status: 'INTERRUPTED',\n            title: String(row.title ?? task.id),\n            result: null,\n            error: String(row.error ?? '客户端异常退出，任务中断')\n          });\n        } catch { /* 通知失败不影响恢复 */ }\n      }\n    }\n    if (interrupted.length > 0) {\n      this.db.audit({ id: randomUUID(), actor: 'system', action: 'recovery.markInterrupted', target: `${interrupted.length} tasks`, result: 'ok' });\n    }\n    if (cancelled.length > 0) {\n      this.db.audit({ id: randomUUID(), actor: 'system', action: 'recovery.cancelOrphanedDelegations', target: `${cancelled.length} tasks`, result: 'ok' });\n    }\n    this.emit();\n  }\n\n  /** 执行调度器：接管数据库中 RUNNING 但无执行器在跑的任务，并执行长任务看门狗。 */\n  startScheduler() {\n    this.adoptRunningTasks();\n    if (this.schedulerTimer) return;\n    this.schedulerTimer = setInterval(() => {\n      this.watchdogSweep();\n      this.emit();\n    }, 2000);\n  }\n\n  /** 长任务看门狗（P4 防卡死/死循环）：RUNNING 超过 config.yaml task.maxRunMinutes 的任务\n   *  强制中断（abort 执行器 + INTERRUPTED），如实告知超时原因；0 = 不限制。\n   *  WAITING_APPROVAL/PAUSED 属人工等待，不计入看门狗。 */\n  private watchdogSweep() {\n    const maxMinutes = loadUserConfig().task.maxRunMinutes;\n    if (!maxMinutes || maxMinutes <= 0) return;\n    const deadline = Date.now() - maxMinutes * 60_000;\n    const rows = this.db.raw\n      .prepare(\"SELECT id, agent_id, title, started_at FROM tasks WHERE status = 'RUNNING' AND started_at IS NOT NULL AND started_at < ?\")\n      .all(deadline) as { id: string; agent_id: string; title: string; started_at: number }[];\n    for (const t of rows) {\n      const now = Date.now();\n      this.broker.abandonTask(t.id);\n      this.executors.abort(t.id);\n      this.db.transaction(() => {\n        this.db.raw.prepare(\"UPDATE tasks SET status = 'INTERRUPTED', ended_at = ?, error = ? WHERE id = ? AND status = 'RUNNING'\")\n          .run(now, `看门狗超时：运行超过 ${maxMinutes} 分钟已强制中断（user/config.yaml task.maxRunMinutes 可调）`, t.id);\n        this.db.raw.prepare(\"UPDATE agent_runs SET ended_at = ?, status = 'INTERRUPTED' WHERE task_id = ? AND ended_at IS NULL\").run(now, t.id);\n        this.recordEvent(t.id, 'interrupted', { reason: 'watchdog-timeout', maxMinutes }, now);\n      });\n      this.db.audit({ id: randomUUID(), actor: 'system', action: 'task.watchdogInterrupt', target: t.id, result: `${maxMinutes}min` });\n      notify(this.db, '任务看门狗中断', `「${t.title.slice(0, 60)}」运行超过 ${maxMinutes} 分钟，已强制中断`);\n      for (const fn of this.finishListeners) {\n        try {\n          fn({ taskId: t.id, agentId: t.agent_id, status: 'INTERRUPTED', title: t.title, result: null, error: `看门狗超时（${maxMinutes} 分钟）` });\n        } catch { /* 通知失败不影响调度 */ }\n      }\n      this.settleTaskDependents(t.id, 'INTERRUPTED', `前置任务 ${t.id} 看门狗中断`);\n      this.scheduleNext(t.agent_id);\n    }\n  }\n\n  /** 启动接管：把无主 RUNNING 任务交给真实执行器。 */\n  private adoptRunningTasks() {\n    const rows = this.db.raw.prepare(\"SELECT * FROM tasks WHERE status = 'RUNNING' ORDER BY created_at\").all() as Row[];\n    for (const r of rows) {\n      const task = this.mapTask(r);\n      if (this.executors.isExecuting(task.id)) continue;\n      const agent = this.getAgent(task.agentId);\n      if (agent && agent.lifecycle === 'READY') this.dispatchTask(task, agent);\n    }\n  }\n\n  // ---------- 查询 ----------\n\n  private mapAgent(r: Row): Agent {\n    let capabilities = { network: false, shell: false, install: false, browser: false, computer: false, mobile: false };\n    try {\n      const raw = r.capabilities_json as string | undefined;\n      if (raw) capabilities = { ...capabilities, ...(JSON.parse(raw) as Partial<typeof capabilities>) };\n    } catch { /* 解析失败用默认值 */ }\n    let tags: string[] = [];\n    try { const raw = r.tags_json as string | undefined; if (raw) tags = JSON.parse(raw) as string[]; } catch { /* empty */ }\n    let modelOverrides: { temperature?: number; topP?: number; maxTokens?: number } | undefined;\n    try { const raw = r.model_overrides_json as string | undefined; if (raw) modelOverrides = JSON.parse(raw); } catch { /* empty */ }\n    return {\n      id: r.id as string, name: r.name as string, role: r.role as string,\n      kind: ((r.agent_kind as string) || 'general') as Agent['kind'],\n      systemPrompt: r.system_prompt as string,\n      soulMd: (r.soul_md as string) ?? '', agentsMd: (r.agents_md as string) ?? '', userMd: (r.user_md as string) ?? '',\n      lifecycle: r.lifecycle as Agent['lifecycle'],\n      engineId: r.engine_id as string, workspace: r.workspace as string,\n      permissionMode: r.permission_mode as Agent['permissionMode'],\n      memoryMode: (['long_term', 'short_term', 'none'].includes(String(r.memory_mode))\n        ? r.memory_mode\n        : 'short_term') as Agent['memoryMode'],\n      capabilities, tags, modelOverrides,\n      modelOverride: (r.model_override as string) || undefined,\n      concurrencyLimit: r.concurrency_limit as number, archived: (r.archived as number) === 1,\n      avatarColor: r.avatar_color as string, createdAt: r.created_at as number, updatedAt: r.updated_at as number\n    };\n  }\n\n  private mapTask(r: Row): Task {\n    return {\n      id: r.id as string, agentId: r.agent_id as string, title: r.title as string,\n      projectId: (r.project_id as string | null) ?? null,\n      conversationId: (r.conversation_id as string | null) ?? null,\n      inputMessageId: (r.input_message_id as string | null) ?? null,\n      content: ((r.content as string | null) || (r.title as string)),\n      source: r.source as Task['source'], parentId: r.parent_id as string | null,\n      status: r.status as TaskStatus, priority: r.priority as number, progress: r.progress as number,\n      stage: r.stage as string, error: r.error as string | null, result: (r.result as string | null) ?? null,\n      hasResult: typeof r.has_result === 'number'\n        ? (r.has_result as number) === 1\n        : Boolean((r.result as string | null | undefined)?.trim()),\n      quality: (r.quality as TaskQuality) ?? null,\n      sessionId: (r.session_id as string | null) ?? null,\n      workspaceOverride: (r.workspace_override as string | null) ?? null,\n      requiresArtifacts: Number(r.artifacts_required ?? 0) === 1,\n      engineOverride: (r.engine_override as string | null) ?? null,\n      createdAt: r.created_at as number, startedAt: r.started_at as number | null, endedAt: r.ended_at as number | null\n    };\n  }\n\n  /** 设置任务产出的人工质量标记（成果管理：采纳/驳回/返工） */\n  setTaskQuality(taskId: string, quality: TaskQuality): Task | null {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n    if (!row) return null;\n    this.db.raw.prepare('UPDATE tasks SET quality = ? WHERE id = ?').run(quality, taskId);\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'task.quality', target: taskId, result: quality ?? 'cleared' });\n    this.emit();\n    return this.mapTask({ ...row, quality });\n  }\n\n  private getAgent(id: string): Agent | null {\n    const r = this.db.raw.prepare('SELECT * FROM agents WHERE id = ?').get(id) as Row | undefined;\n    return r ? this.mapAgent(r) : null;\n  }\n\n  /** 任务事件时间线（详情弹窗实时流；output 为增量文本事件） */\n  taskEvents(taskId: string): TaskEvent[] {\n    // Read the newest bounded window and restore chronological order. A task\n    // can legitimately have many tool/progress events, but the UI must never\n    // receive an unbounded history in one IPC response.\n    const rows = this.db.raw\n      .prepare(`SELECT id, task_id, event_type,\n        CASE WHEN event_type = 'result' THEN '{}' ELSE payload END AS payload,\n        created_at\n        FROM task_events WHERE task_id = ? ORDER BY created_at DESC, rowid DESC LIMIT ?`)\n      .all(taskId, MAX_TASK_EVENTS_QUERY) as Row[];\n    return rows.reverse().map((r) => ({\n      id: r.id as string,\n      taskId: r.task_id as string,\n      eventType: r.event_type as string,\n      payload: (() => {\n        try { return JSON.parse((r.payload as string) || '{}') as Record<string, unknown>; }\n        catch { return { error: '事件数据损坏' }; }\n      })(),\n      createdAt: r.created_at as number\n    }));\n  }\n\n  /** 任务产物全文（tasks.result，截断 16KB） */\n  taskResult(taskId: string): string | null {\n    const r = this.db.raw.prepare('SELECT result FROM tasks WHERE id = ?').get(taskId) as { result: string | null } | undefined;\n    return typeof r?.result === 'string' ? r.result.slice(0, MAX_TASK_RESULT_CHARS) : null;\n  }\n\n  /** 解析任务产物目录：task.workspaceOverride > agent.workspace > userData/workspaces/agentId */\n  resolveTaskWorkspace(taskId: string): string | null {\n    const row = this.db.raw.prepare('SELECT agent_id, workspace_override FROM tasks WHERE id = ?').get(taskId) as { agent_id: string; workspace_override: string | null } | undefined;\n    if (!row) return null;\n    if (row.workspace_override) return row.workspace_override;\n    const agent = this.getAgent(row.agent_id);\n    if (!agent) return null;\n    return agent.workspace || join(app.getPath('userData'), 'workspaces', agent.id);\n  }\n\n  /** 解析员工工作目录 */\n  resolveAgentWorkspace(agentId: string): string | null {\n    const agent = this.getAgent(agentId);\n    if (!agent) return null;\n    return agent.workspace || join(app.getPath('userData'), 'workspaces', agent.id);\n  }\n\n  listAgents(): Agent[] {\n    return (this.db.raw.prepare('SELECT * FROM agents WHERE archived = 0 ORDER BY created_at').all() as Row[]).map((r) => this.mapAgent(r));\n  }\n\n  /** 归档（软删除）助手 */\n  archiveAgent(id: string) {\n    this.db.raw.prepare('UPDATE agents SET archived = 1, updated_at = ? WHERE id = ?').run(Date.now(), id);\n    this.emit();\n  }\n\n  checkpointAgentCreation(input: CreateAgentInput): AgentCreationCheckpoint {\n    const existing = this.db.raw.prepare('SELECT * FROM agents WHERE name = ?').get(input.name) as Row | undefined;\n    const safeName = input.name.replace(/[<>:\"/\\\\|?*]/g, '_').slice(0, 30);\n    const autoWorkspacePath = !existing && !input.workspace\n      ? join(app.getPath('userData'), 'aibox-data', 'workspaces', safeName)\n      : null;\n    return {\n      existing: existing ? { ...existing } : null,\n      autoWorkspacePath,\n      autoWorkspaceExisted: autoWorkspacePath ? existsSync(autoWorkspacePath) : false\n    };\n  }\n\n  rollbackAgentCreation(checkpoint: AgentCreationCheckpoint, agentId: string): void {\n    if (checkpoint.existing) {\n      const columns = Object.keys(checkpoint.existing).filter((column) => column !== 'id');\n      const assignments = columns.map((column) => `${column} = ?`).join(', ');\n      this.db.raw.prepare(`UPDATE agents SET ${assignments} WHERE id = ?`)\n        .run(...columns.map((column) => checkpoint.existing![column] as string | number | null), checkpoint.existing.id as string);\n      this.db.audit({ id: randomUUID(), actor: 'system', action: 'agent.create.rollback', target: agentId, result: 'restored-existing' });\n      this.emit();\n      return;\n    }\n    this.discardNewAgent(agentId);\n    const workspace = checkpoint.autoWorkspacePath;\n    if (workspace && !checkpoint.autoWorkspaceExisted && existsSync(workspace) && readdirSync(workspace).length === 0) {\n      rmdirSync(workspace);\n    }\n  }\n\n  discardNewAgent(id: string): void {\n    const activeTasks = (this.db.raw.prepare('SELECT COUNT(*) AS count FROM tasks WHERE agent_id = ?').get(id) as { count: number } | undefined)?.count ?? 0;\n    if (activeTasks > 0) throw new Error('Cannot discard an agent after tasks have been created');\n    this.db.transaction(() => {\n      this.db.raw.prepare('DELETE FROM channel_routes WHERE agent_id = ?').run(id);\n      this.db.raw.prepare('DELETE FROM agent_skills WHERE agent_id = ?').run(id);\n      this.db.raw.prepare('DELETE FROM mobile_agent_configs WHERE agent_id = ?').run(id);\n      this.db.raw.prepare('DELETE FROM agents WHERE id = ?').run(id);\n    });\n    this.db.audit({ id: randomUUID(), actor: 'system', action: 'agent.create.rollback', target: id, result: 'profile-failed' });\n    this.emit();\n  }\n\n  /** 更新助手人设（soul.md / agents.md / user.md / 基础 prompt / 权限模式） */\n  updateAgentPersona(id: string, patch: import('../../shared/types.js').AgentPersonaPatch): Agent {\n    const agent = this.getAgent(id);\n    if (!agent) throw new Error('助手不存在');\n    const fields: string[] = [];\n    const values: (string | number)[] = [];\n    if (patch.name !== undefined) { fields.push('name = ?'); values.push(patch.name); }\n    if (patch.role !== undefined) { fields.push('role = ?'); values.push(patch.role); }\n    if (patch.systemPrompt !== undefined) { fields.push('system_prompt = ?'); values.push(patch.systemPrompt); }\n    if (patch.soulMd !== undefined) { fields.push('soul_md = ?'); values.push(patch.soulMd); }\n    if (patch.agentsMd !== undefined) { fields.push('agents_md = ?'); values.push(patch.agentsMd); }\n    if (patch.userMd !== undefined) { fields.push('user_md = ?'); values.push(patch.userMd); }\n    if (patch.permissionMode !== undefined) { fields.push('permission_mode = ?'); values.push(patch.permissionMode); }\n    if (patch.memoryMode !== undefined) {\n      if (!['long_term', 'short_term', 'none'].includes(patch.memoryMode)) throw new Error('员工记忆策略无效');\n      fields.push('memory_mode = ?'); values.push(patch.memoryMode);\n    }\n    const nextKind = patch.kind ?? agent.kind;\n    const nextEngineId = patch.kind === 'android_operator'\n      ? ANDROID_OPERATOR_ENGINE_ID\n      : patch.engineId ?? agent.engineId;\n    assertAndroidOperatorEngine(nextKind, nextEngineId);\n    if (patch.kind !== undefined) {\n      fields.push('agent_kind = ?'); values.push(patch.kind);\n      fields.push('engine_id = ?'); values.push(nextEngineId);\n      fields.push('concurrency_limit = ?'); values.push(patch.kind === 'android_operator' ? 1 : agent.concurrencyLimit);\n    }\n    if (patch.capabilities !== undefined || patch.kind !== undefined) {\n      const merged = { ...agent.capabilities, ...patch.capabilities };\n      if (nextKind === 'android_operator') Object.assign(merged, { network: false, shell: false, install: false, browser: false, computer: false, mobile: true });\n      else merged.mobile = false;\n      fields.push('capabilities_json = ?'); values.push(JSON.stringify(merged));\n    }\n    if (patch.tags !== undefined) { fields.push('tags_json = ?'); values.push(JSON.stringify(patch.tags)); }\n    if (patch.modelOverrides !== undefined) { fields.push('model_overrides_json = ?'); values.push(JSON.stringify(patch.modelOverrides)); }\n    if (patch.engineId !== undefined && patch.kind === undefined) {\n      fields.push('engine_id = ?'); values.push(patch.engineId);\n    }\n    if (patch.modelOverride !== undefined) { fields.push('model_override = ?'); values.push(patch.modelOverride || ''); }\n    if (fields.length === 0) return agent;\n    fields.push('updated_at = ?'); values.push(Date.now());\n    values.push(id);\n    this.db.raw.prepare(`UPDATE agents SET ${fields.join(', ')} WHERE id = ?`).run(...values);\n    if (agent.kind === 'android_operator' && nextKind === 'general') {\n      this.mobileDispatchPolicy?.releaseAgent?.(id);\n    }\n    this.emit();\n    return this.getAgent(id)!;\n  }\n\n  // ---------- 会话（持续多轮对话） ----------\n\n  listConversations(agentId: string): import('../../shared/types.js').Conversation[] {\n    return (this.db.raw.prepare('SELECT * FROM conversations WHERE agent_id = ? AND channel_id IS NULL ORDER BY last_message_at DESC LIMIT 50').all(agentId) as Row[]).map((r) => ({\n      id: r.id as string, agentId: r.agent_id as string, title: r.title as string,\n      projectId: (r.project_id as string | null) ?? null,\n      organizationId: (r.organization_id as string | null) ?? null,\n      principalId: (r.principal_id as string | null) ?? null,\n      channelId: (r.channel_id as string | null) ?? null,\n      channelIdentityId: (r.channel_identity_id as string | null) ?? null,\n      externalConversationKey: (r.external_conversation_key as string | null) ?? null,\n      lastMessageAt: r.last_message_at as number, messageCount: r.message_count as number,\n      createdAt: (r.created_at as number | null) ?? null,\n      updatedAt: (r.updated_at as number | null) ?? null\n    }));\n  }\n\n  // ---------- 用量统计 ----------\n\n  usageStats(): { total: { input: number; output: number; total: number }; byModel: { model: string; input: number; output: number; total: number; count: number }[]; recent: { id: string; agentId: string; model: string; input: number; output: number; total: number; createdAt: number }[] } {\n    const total = this.db.raw.prepare('SELECT COALESCE(SUM(input_tokens),0) i, COALESCE(SUM(output_tokens),0) o, COALESCE(SUM(total_tokens),0) t FROM usage_records').get() as { i: number; o: number; t: number };\n    const byModel = (this.db.raw.prepare('SELECT model, SUM(input_tokens) input, SUM(output_tokens) output, SUM(total_tokens) total, COUNT(*) count FROM usage_records GROUP BY model ORDER BY total DESC').all() as Row[]).map((r) => ({\n      model: r.model as string, input: r.input as number, output: r.output as number, total: r.total as number, count: r.count as number\n    }));\n    const recent = (this.db.raw.prepare('SELECT * FROM usage_records ORDER BY created_at DESC LIMIT 50').all() as Row[]).map((r) => ({\n      id: r.id as string, agentId: r.agent_id as string, model: r.model as string,\n      input: r.input_tokens as number, output: r.output_tokens as number, total: r.total_tokens as number, createdAt: r.created_at as number\n    }));\n    return { total: { input: total.i, output: total.o, total: total.t }, byModel, recent };\n  }\n\n  listTasks(options: { includeResult?: boolean } = {}): Task[] {\n    const select = options.includeResult === false\n      ? `id, agent_id, project_id, conversation_id, input_message_id, title, content,\n         source, parent_id, status, priority, progress, stage, error,\n         NULL AS result, CASE WHEN result IS NOT NULL AND LENGTH(TRIM(result)) > 0 THEN 1 ELSE 0 END AS has_result,\n         quality, session_id, workspace_override, engine_override, artifacts_required, created_at, started_at, ended_at`\n      : '*';\n    return (this.db.raw.prepare(`SELECT ${select} FROM tasks WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT 200`).all() as Row[])\n      .map((r) => this.mapTask(r));\n  }\n\n  listApprovals(): Approval[] {\n    const rows = this.db.raw.prepare(\"SELECT * FROM approvals WHERE status = 'pending' ORDER BY created_at DESC\").all() as Row[];\n    return rows.map((r) => ({\n      id: r.id as string, taskId: r.task_id as string, agentId: r.agent_id as string,\n      scope: approvalScope(r.type),\n      type: (r.type === 'tool' ? DISPATCH_PLAN_APPROVAL_TYPE : r.type) as Approval['type'],\n      request: r.request as string, risk: r.risk as Approval['risk'],\n      status: 'pending', createdAt: r.created_at as number, decidedAt: null\n    }));\n  }\n\n  /** 6.2 派生状态：互斥归类，同一数字员工只计入一类 */\n  private deriveStatus(agent: Agent, activeTask: Task | null): DerivedAgentStatus {\n    if (agent.lifecycle === 'ERROR') return 'error';\n    if (activeTask && (activeTask.status === 'RUNNING' || activeTask.status === 'WAITING_APPROVAL')) return 'running';\n    if (activeTask && activeTask.status === 'PAUSED') return 'paused';\n    if (agent.lifecycle === 'STARTING' || agent.lifecycle === 'STOPPING' || (activeTask && activeTask.status === 'QUEUED')) return 'starting';\n    return 'idle';\n  }\n\n  agentCards(): AgentCardView[] {\n    const agents = this.listAgents();\n    const activeTasks = this.db.raw\n      .prepare(\"SELECT * FROM tasks WHERE status IN ('RUNNING','QUEUED','WAITING_APPROVAL','PAUSED') ORDER BY created_at DESC\")\n      .all() as Row[];\n    const taskByAgent = new Map<string, Task>();\n    for (const r of activeTasks) {\n      const t = this.mapTask(r);\n      if (!taskByAgent.has(t.agentId)) taskByAgent.set(t.agentId, t);\n    }\n    const engineRows = this.db.raw.prepare('SELECT id, name, status FROM engines').all() as {\n      id: string; name: string; status: EngineStatus;\n    }[];\n    const engineNames = new Map(engineRows.map((engine) => [engine.id, engine.name]));\n    const engineStatuses = new Map(engineRows.map((engine) => [engine.id, engine.status]));\n    const channelRows = this.db.raw\n      .prepare(\"SELECT c.type, cr.agent_id FROM channel_routes cr JOIN channels c ON c.id = cr.channel_id WHERE c.status != 'DISABLED'\")\n      .all() as { type: string; agent_id: string }[];\n    const channelsByAgent = new Map<string, Set<string>>();\n    for (const r of channelRows) {\n      if (!channelsByAgent.has(r.agent_id)) channelsByAgent.set(r.agent_id, new Set());\n      channelsByAgent.get(r.agent_id)!.add(r.type);\n    }\n    const runs = this.db.raw\n      .prepare('SELECT agent_id, MIN(started_at) AS since FROM agent_runs WHERE ended_at IS NULL GROUP BY agent_id')\n      .all() as { agent_id: string; since: number }[];\n    const runSince = new Map(runs.map((r) => [r.agent_id, r.since]));\n\n    // 助手绑定的 Skills（agent_skills 关联表）\n    const skillRows = this.db.raw\n      .prepare('SELECT as2.agent_id, s.name FROM agent_skills as2 JOIN skills s ON s.id = as2.skill_id WHERE s.enabled = 1')\n      .all() as { agent_id: string; name: string }[];\n    const skillsByAgent = new Map<string, string[]>();\n    for (const r of skillRows) {\n      if (!skillsByAgent.has(r.agent_id)) skillsByAgent.set(r.agent_id, []);\n      skillsByAgent.get(r.agent_id)!.push(r.name);\n    }\n\n    // MCP 服务器（scope='global' 对所有助手可见，scope=agentId 为专属）\n    const mcpRows = this.db.raw\n      .prepare('SELECT id, name, scope FROM mcp_servers WHERE enabled = 1')\n      .all() as { id: string; name: string; scope: string }[];\n    const globalMcp = mcpRows.filter((m) => m.scope === 'global').map((m) => m.name);\n\n    // 助手模型解析：provider_id + model_override → 实际模型名\n    const agentProviderRows = this.db.raw\n      .prepare('SELECT id, provider_id, model_override FROM agents WHERE archived = 0')\n      .all() as { id: string; provider_id: string | null; model_override: string | null }[];\n    const providerRows = this.db.raw\n      .prepare('SELECT id, model, is_default FROM providers')\n      .all() as { id: string; model: string; is_default: number }[];\n    const defaultProvider = providerRows.find((p) => p.is_default === 1);\n    const providerModelMap = new Map(providerRows.map((p) => [p.id, p.model]));\n    const modelByAgent = new Map<string, string>();\n    for (const ar of agentProviderRows) {\n      if (ar.model_override) { modelByAgent.set(ar.id, ar.model_override); }\n      else if (ar.provider_id && providerModelMap.has(ar.provider_id)) { modelByAgent.set(ar.id, providerModelMap.get(ar.provider_id)!); }\n      else if (defaultProvider) { modelByAgent.set(ar.id, defaultProvider.model); }\n    }\n\n    return agents.map((agent) => {\n      const task = taskByAgent.get(agent.id) ?? null;\n      const derived = this.deriveStatus(agent, task);\n      const engineStatus = engineStatuses.get(agent.engineId) ?? 'NOT_INSTALLED';\n      const since = runSince.get(agent.id);\n      const agentMcp = mcpRows.filter((m) => m.scope === agent.id).map((m) => m.name);\n      return {\n        agent,\n        derivedStatus: derived,\n        engineStatus,\n        currentTask: task\n          ? { id: task.id, title: task.title, progress: task.progress, stage: task.stage, executor: this.executors.kindFor(agent.engineId) }\n          : null,\n        uptimeText: since ? formatDuration(Date.now() - since) : '',\n        channels: [...(channelsByAgent.get(agent.id) ?? [])] as AgentCardView['channels'],\n        engineName: ownerFacingEngineName(agent.engineId, engineNames.get(agent.engineId)),\n        modelName: modelByAgent.get(agent.id) ?? '',\n        needsAttention: derived === 'error' || engineStatus !== 'HEALTHY' || task?.status === 'WAITING_APPROVAL',\n        skills: skillsByAgent.get(agent.id) ?? [],\n        mcpServers: [...globalMcp, ...agentMcp]\n      };\n    });\n  }\n\n  /** 6.2 首页统计口径：总数 = 执行中 + 空闲/待命 + 暂停/启动中 + 异常/离线 */\n  stats(): DashboardStats {\n    const cards = this.agentCards().filter((c) => c.agent.lifecycle !== 'DISABLED');\n    const s: DashboardStats = {\n      totalAgents: cards.length, running: 0, idle: 0, pausedOrStarting: 0, errorOrOffline: 0,\n      activeTasks: 0, pendingTodos: 0, todayCompleted: 0\n    };\n    for (const c of cards) {\n      if (c.derivedStatus === 'running') s.running++;\n      else if (c.derivedStatus === 'idle') s.idle++;\n      else if (c.derivedStatus === 'error') s.errorOrOffline++;\n      else s.pausedOrStarting++;\n    }\n    s.activeTasks = (this.db.raw.prepare(\"SELECT COUNT(*) c FROM tasks WHERE is_demo = 0 AND status IN ('RUNNING','QUEUED','WAITING_APPROVAL','PAUSED')\").get() as { c: number }).c;\n    s.pendingTodos = (this.db.raw.prepare(\"SELECT COUNT(*) c FROM approvals WHERE status = 'pending' AND agent_id NOT IN (SELECT id FROM agents WHERE is_demo = 1)\").get() as { c: number }).c;\n    const dayStart = new Date(); dayStart.setHours(0, 0, 0, 0);\n    s.todayCompleted = (this.db.raw.prepare(\"SELECT COUNT(*) c FROM tasks WHERE is_demo = 0 AND status = 'COMPLETED' AND deleted_at IS NULL AND ended_at >= ?\").get(dayStart.getTime()) as { c: number }).c;\n    return s;\n  }\n\n  /** 待办 = 待审批 + 渠道异常 + 系统提醒（6.2 待处理事项） */\n  todos(): TodoItem[] {\n    const items: TodoItem[] = [];\n    for (const a of this.listApprovals()) {\n      const agent = this.db.raw.prepare('SELECT name FROM agents WHERE id = ?').get(a.agentId) as { name: string } | undefined;\n      items.push({\n        id: a.id, title: a.request, owner: agent?.name ?? '未知员工',\n        dueText: '等待审批', severity: a.risk === 'high' ? 'high' : 'medium', kind: 'approval'\n      });\n    }\n    const errChannels = this.db.raw.prepare(\"SELECT * FROM channels WHERE status IN ('ERROR','AUTH_EXPIRED')\").all() as Row[];\n    for (const c of errChannels) {\n      items.push({\n        id: `ch-${c.id}`, title: `渠道「${c.account_name || c.type}」连接异常，需要重新鉴权`, owner: '连接中心',\n        dueText: '尽快处理', severity: 'high', kind: 'channel'\n      });\n    }\n    return items.slice(0, 12);\n  }\n\n  // ---------- 命令 ----------\n\n  createAgent(input: CreateAgentInput): Agent {\n    if (input.name.length < 2 || input.name.length > 30) throw new Error('名称需为 2—30 字');\n    if (input.role.length < 2 || input.role.length > 500) throw new Error('职责描述需为 2—500 字');\n    const kind = input.kind ?? 'general';\n    const memoryMode = input.memoryMode ?? 'short_term';\n    if (!['long_term', 'short_term', 'none'].includes(memoryMode)) throw new Error('员工记忆策略无效');\n    const engineId = kind === 'android_operator' ? ANDROID_OPERATOR_ENGINE_ID : input.engineId;\n    if (kind === 'android_operator' && input.concurrencyLimit !== 1) throw new Error('Android 手机操作员并发数必须为 1');\n    const engine = this.db.raw.prepare(\"SELECT status FROM engines WHERE id = ?\").get(engineId) as { status: string } | undefined;\n    if (!engine || !['HEALTHY', 'SETUP_REQUIRED', 'AUTH_REQUIRED'].includes(engine.status)) {\n      throw new Error('只能选择已安装或待配置的引擎（引擎就绪前不会执行任务）');\n    }\n    // 同名员工已存在（含已归档）：复用而非重复插入（agents.name 有 UNIQUE 约束）\n    const existing = this.db.raw.prepare('SELECT id, archived FROM agents WHERE name = ?').get(input.name) as { id: string; archived: number } | undefined;\n    if (existing) {\n      if (existing.archived === 1) {\n        // 已归档的同名员工：重新激活并更新配置\n        this.db.raw.prepare(\n          `UPDATE agents SET archived = 0, role = ?, system_prompt = ?, soul_md = ?, agents_md = ?, user_md = ?, engine_id = ?, permission_mode = ?, memory_mode = ?, agent_kind = ?, concurrency_limit = ?, lifecycle = 'READY', updated_at = ? WHERE id = ?`\n        ).run(input.role, input.systemPrompt, input.soulMd ?? '', input.agentsMd ?? '', input.userMd ?? '', engineId, input.permissionMode, memoryMode, kind, kind === 'android_operator' ? 1 : input.concurrencyLimit, Date.now(), existing.id);\n        this.emit();\n        return this.listAgents().find((a) => a.id === existing.id)!;\n      }\n      // 未归档的同名员工：直接返回已有的\n      return this.listAgents().find((a) => a.id === existing.id)!;\n    }\n    const now = Date.now();\n    const id = randomUUID();\n    const colors = ['#4d6bfe', '#22c1a3', '#8a5cf6', '#f59e0b', '#3aa7ff', '#ef6a6a'];\n    const color = colors[Math.floor(Math.random() * colors.length)];\n    // 独立工作区：未指定时自动创建 userData/aibox-data/workspaces/{name}/\n    let workspace = input.workspace;\n    if (!workspace) {\n      const safeName = input.name.replace(/[<>:\"/\\\\|?*]/g, '_').slice(0, 30);\n      workspace = join(app.getPath('userData'), 'aibox-data', 'workspaces', safeName);\n      mkdirSync(workspace, { recursive: true });\n    }\n    this.db.transaction(() => {\n      this.db.raw.prepare(\n        `INSERT INTO agents(id, name, role, system_prompt, soul_md, agents_md, user_md, lifecycle, engine_id, workspace, permission_mode, memory_mode, concurrency_limit, archived, avatar_color, agent_kind, capabilities_json, created_at, updated_at)\n         VALUES(?, ?, ?, ?, ?, ?, ?, 'READY', ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?)`\n      ).run(\n        id, input.name, input.role, input.systemPrompt, input.soulMd ?? '', input.agentsMd ?? '', input.userMd ?? '',\n        engineId, workspace, input.permissionMode, memoryMode, kind === 'android_operator' ? 1 : input.concurrencyLimit, color, kind,\n        JSON.stringify(kind === 'android_operator'\n          ? { network: false, shell: false, install: false, browser: false, computer: false, mobile: true }\n          : { network: false, shell: false, install: false, browser: false, computer: false, mobile: false }),\n        now, now\n      );\n      for (const chId of input.channelIds) {\n        this.db.raw.prepare('INSERT INTO channel_routes(id, channel_id, conversation_key, agent_id, policy) VALUES(?, ?, ?, ?, ?)')\n          .run(randomUUID(), chId, '*', id, '{}');\n      }\n    });\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'agent.create', target: input.name, result: 'ok' });\n    this.emit();\n    return this.listAgents().find((a) => a.id === id)!;\n  }\n\n  startAgent(id: string) {\n    this.db.raw.prepare(\"UPDATE agents SET lifecycle = 'READY', updated_at = ? WHERE id = ?\").run(Date.now(), id);\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'agent.start', target: id, result: 'ok' });\n    this.scheduleNext(id);\n    this.emit();\n  }\n\n  stopAgent(id: string) {\n    const now = Date.now();\n    const active = this.db.raw.prepare(\"SELECT id FROM tasks WHERE agent_id = ? AND status IN ('RUNNING','QUEUED','PAUSED','WAITING_APPROVAL')\").all(id) as { id: string }[];\n    const taskIds = new Set<string>();\n    for (const task of active) {\n      for (const descendant of this.collectTaskTree(task.id)) taskIds.add(descendant);\n    }\n    const cancelled = this.cancelTaskSet(\n      [...taskIds],\n      now,\n      '数字员工已停止',\n      '父任务因员工停止而取消',\n      new Set(active.map((task) => task.id)),\n      () => {\n        this.db.raw.prepare(\"UPDATE agents SET lifecycle = 'DISABLED', updated_at = ? WHERE id = ?\").run(now, id);\n      }\n    );\n    this.notifyCancelledTasks(cancelled);\n    this.settleCancelledTaskDependents(cancelled);\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'agent.stop', target: id, result: 'ok' });\n    this.emit();\n    for (const agentId of new Set(cancelled.map((task) => task.agentId))) {\n      if (agentId !== id) this.scheduleNext(agentId);\n    }\n  }\n\n  /** Validate and normalize prerequisites before a task row is committed. */\n  private normalizeDependencyTaskIds(agentId: string, taskId: string, raw: unknown): string[] {\n    if (raw === undefined) return [];\n    if (!Array.isArray(raw)) throw new Error('任务依赖必须是数组');\n    if (raw.length > MAX_TASK_DEPENDENCIES) throw new Error(`任务依赖不能超过 ${MAX_TASK_DEPENDENCIES} 项`);\n    const ids: string[] = [];\n    const seen = new Set<string>();\n    for (const value of raw) {\n      if (typeof value !== 'string' || value.length === 0 || value.length > 128) {\n        throw new Error('任务依赖 ID 无效');\n      }\n      if (value === taskId) throw new Error('任务不能依赖自身');\n      if (seen.has(value)) throw new Error(`任务依赖重复：${value}`);\n      seen.add(value);\n      ids.push(value);\n    }\n    if (ids.length === 0) return ids;\n    const targetOrg = this.db.raw.prepare('SELECT organization_id FROM agents WHERE id = ?').get(agentId) as\n      { organization_id: string } | undefined;\n    if (!targetOrg?.organization_id) throw new Error('任务所属组织不存在');\n    for (const dependencyId of ids) {\n      const dependency = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(dependencyId) as Row | undefined;\n      if (!dependency) throw new Error(`任务依赖不存在或已删除：${dependencyId}`);\n      const dependencyOrg = this.db.raw.prepare('SELECT organization_id FROM agents WHERE id = ?').get(String(dependency.agent_id)) as\n        { organization_id: string } | undefined;\n      if (!dependencyOrg?.organization_id || dependencyOrg.organization_id !== targetOrg.organization_id) {\n        throw new Error(`任务依赖跨组织：${dependencyId}`);\n      }\n    }\n    return ids;\n  }\n\n  private dependencyIds(taskId: string): string[] {\n    return (this.db.raw.prepare(\n      'SELECT dependency_task_id FROM task_dependencies WHERE task_id = ? ORDER BY dependency_task_id'\n    ).all(taskId) as { dependency_task_id: string }[]).map((row) => String(row.dependency_task_id));\n  }\n\n  private dependencyGateForIds(ids: readonly string[]): TaskDependencyGate {\n    const pending: string[] = [];\n    const failed: string[] = [];\n    for (const dependencyId of ids) {\n      const dependency = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(dependencyId) as Row | undefined;\n      // A missing prerequisite is corruption. Treat it as failed rather than\n      // allowing a dependent task to run against an unknown input.\n      if (!dependency) {\n        failed.push(dependencyId);\n        continue;\n      }\n      const status = dependency.status as TaskStatus;\n      if (status === 'COMPLETED') continue;\n      if (status === 'FAILED' || status === 'CANCELLED' || status === 'INTERRUPTED') failed.push(dependencyId);\n      else pending.push(dependencyId);\n    }\n    return { ready: pending.length === 0 && failed.length === 0, pending, failed };\n  }\n\n  private dependencyGate(taskId: string): TaskDependencyGate {\n    return this.dependencyGateForIds(this.dependencyIds(taskId));\n  }\n\n  private dependentTaskIds(taskId: string): string[] {\n    return (this.db.raw.prepare(\n      `SELECT td.task_id\n       FROM task_dependencies td\n       JOIN tasks t ON t.id = td.task_id\n       WHERE td.dependency_task_id = ? AND t.deleted_at IS NULL`\n    ).all(taskId) as { task_id: string }[]).map((row) => String(row.task_id));\n  }\n\n  /**\n   * Recursively cancel dependents when an upstream task cannot produce its\n   * contract. The transaction commits all dependency decisions before any\n   * executor abort/notification is attempted.\n   */\n  private cascadeDependencyFailure(rootTaskId: string, reason: string, now: number): CancelledTaskRecord[] {\n    const queue = [rootTaskId];\n    const visited = new Set<string>();\n    const cancelled: CancelledTaskRecord[] = [];\n    this.db.transaction(() => {\n      while (queue.length > 0) {\n        const upstreamId = queue.shift()!;\n        if (visited.has(upstreamId)) continue;\n        visited.add(upstreamId);\n        for (const dependentId of this.dependentTaskIds(upstreamId)) {\n          for (const candidateId of this.collectTaskTree(dependentId)) {\n            if (visited.has(candidateId)) continue;\n            const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(candidateId) as Row | undefined;\n            if (!row || !ACTIVE_TASK_STATUSES.includes(row.status as typeof ACTIVE_TASK_STATUSES[number])) continue;\n            if (!this.cancelTaskInternal(candidateId, now, reason)) continue;\n            this.db.raw.prepare(\"UPDATE tasks SET stage = '依赖失败', error = ? WHERE id = ? AND status = 'CANCELLED'\")\n              .run(reason, candidateId);\n            cancelled.push({\n              id: candidateId,\n              agentId: String(row.agent_id),\n              title: String(row.title ?? candidateId),\n              error: reason\n            });\n            queue.push(candidateId);\n          }\n        }\n      }\n    });\n    return cancelled;\n  }\n\n  /** Wake dependents after completion, or fail-closed and wake their queues\n   * after a non-success terminal transition. */\n  private settleTaskDependents(taskId: string, status: TaskStatus, reason: string): void {\n    const dependentAgents = new Set<string>();\n    for (const dependentId of this.dependentTaskIds(taskId)) {\n      const row = this.db.raw.prepare('SELECT agent_id FROM tasks WHERE id = ? AND deleted_at IS NULL').get(dependentId) as\n        { agent_id: string } | undefined;\n      if (row?.agent_id) dependentAgents.add(String(row.agent_id));\n    }\n    if (status !== 'COMPLETED') {\n      const cancelled = this.cascadeDependencyFailure(taskId, reason, Date.now());\n      if (cancelled.length > 0) {\n        this.releaseCancelledTasks(cancelled);\n        this.notifyCancelledTasks(cancelled);\n        for (const item of cancelled) dependentAgents.add(item.agentId);\n      }\n    }\n    for (const agentId of dependentAgents) this.scheduleNext(agentId);\n  }\n\n  /** 创建任务：该员工无活跃任务且未超并发 → 立即经执行器派发；否则进入 QUEUED 等待 FIFO 调度。\n   *  opts.parentId：委派/追问的父任务；opts.sessionId：继承会话锚点（P2b 追问续跑）；\n   *  opts.workspaceOverride：任务级工作空间覆盖（团队共享工作空间）；\n   *  opts.engineOverride：任务级引擎覆盖（E-2 编码委派，员工归属不变）；\n   *  opts.sourceKey：外部来源的稳定消息 ID；重复键返回原任务并标记 deduplicated；\n   *  opts.conversationId：canonical conversation 外键。 */\n  createTask(agentId: string, title: string, source: Task['source'] = 'desktop', opts: CreateTaskOptions = {}): CreateTaskResult {\n    const now = Date.now();\n    const id = randomUUID();\n    const sourceKey = opts.sourceKey?.trim() || null;\n    const content = (opts.content ?? title).trim();\n    if (!content) throw new Error('任务内容不能为空');\n    if (content.length > 1_000_000) throw new Error('任务内容超过 1000000 字符');\n    const priority = opts.priority ?? 0;\n    if (!Number.isInteger(priority) || priority < -10 || priority > 10) throw new Error('任务优先级必须为 -10 到 10 的整数');\n    const approvalRequest = opts.initialApprovalRequest?.trim() || null;\n    if (source === 'delegated') {\n      if (!opts.parentId) throw new Error('委派任务必须关联父任务');\n      this.assertDelegationTarget(opts.parentId, agentId, Boolean(opts.allowAncestorAgentDelegation));\n    }\n    if (sourceKey) {\n      const existing = this.db.raw.prepare('SELECT * FROM tasks WHERE source = ? AND source_key = ?').get(source, sourceKey) as Row | undefined;\n      if (existing) {\n        if (opts.onPersisted) this.db.transaction(() => opts.onPersisted?.(String(existing.id)));\n        return Object.assign(this.mapTask(existing), { deduplicated: true as const });\n      }\n    }\n    const agent = this.getAgent(agentId);\n    if (!agent) throw new Error('员工不存在');\n    const dependencyTaskIds = this.normalizeDependencyTaskIds(agentId, id, opts.dependencyTaskIds);\n    const dependencyGate = this.dependencyGateForIds(dependencyTaskIds);\n    assertAndroidOperatorEngine(agent.kind, agent.engineId);\n    const mobileState = agent.kind === 'android_operator'\n      ? this.mobileDispatchPolicy?.canDispatch(agentId) ?? { bound: false, ready: false, reason: '手机控制服务尚未启动' }\n      : null;\n    if (mobileState && !mobileState.bound) throw new Error('Android 手机操作员尚未绑定设备');\n    // 引擎路由规则（settings.engine_routing）：按任务来源指定优先引擎。\n    // 显式 engineOverride（编码委派）优先级最高；路由规则仅在引擎健康时生效，\n    // 避免把任务路由到未安装的引擎上。\n    let engineOverride = agent.kind === 'android_operator' ? null : opts.engineOverride ?? null;\n    if (agent.kind === 'general' && !engineOverride) {\n      const routed = this.db.getSetting<Record<string, string>>('engine_routing', {})[source];\n      if (routed && routed !== agent.engineId) {\n        const row = this.db.raw.prepare('SELECT status FROM engines WHERE id = ?').get(routed) as { status: string } | undefined;\n        if (row?.status === 'HEALTHY') engineOverride = routed;\n      }\n    }\n    const projectId = this.resolveTaskProject(agentId, opts.parentId, opts.projectId);\n    const workspaceOverride = this.resolveProjectWorkspace(projectId, opts.workspaceOverride);\n    const requiresArtifacts = opts.requiresArtifacts ?? Boolean(projectId);\n    const active = this.agentOccupancy(agentId);\n    const guardReason = this.dispatchGuard();\n    const canRun = dependencyGate.ready && !approvalRequest && agent.lifecycle === 'READY' && active < Math.max(1, agent.concurrencyLimit) && guardReason === null && (!mobileState || mobileState.ready);\n    const queuedStage = dependencyGate.pending.length > 0\n      ? `等待前置任务（${dependencyGate.pending.length}）`\n      : guardReason ?? mobileState?.reason ?? '排队中';\n    const dependencyError = dependencyGate.failed.length > 0\n      ? `前置任务未成功完成，已阻止执行：${dependencyGate.failed.join(', ')}`\n      : null;\n    const initialStatus = dependencyError ? 'CANCELLED' : approvalRequest ? 'WAITING_APPROVAL' : canRun ? 'RUNNING' : 'QUEUED';\n    const initialStage = dependencyError ? '依赖失败' : approvalRequest ? '等待审批' : canRun ? STAGES[0] : queuedStage;\n    if (source === 'delegated' && !canRun) this.assertNoDelegationWaitCycle(opts.parentId!, agentId);\n    let inserted = false;\n    this.db.transaction(() => {\n      const transactionProjectId = this.resolveTaskProject(agentId, opts.parentId, opts.projectId);\n      if (transactionProjectId !== projectId) throw new Error('父任务或项目关联已发生变化');\n      const transactionWorkspace = this.resolveProjectWorkspace(transactionProjectId, opts.workspaceOverride);\n      if (transactionWorkspace !== workspaceOverride) throw new Error('项目工作目录已发生变化，请重新派发任务');\n      // Lookup and commit are separate calls. Recheck under the write\n      // transaction so an archived/moved target cannot cross the tenant gate.\n      if (source === 'delegated') {\n        this.assertDelegationTarget(opts.parentId!, agentId, Boolean(opts.allowAncestorAgentDelegation));\n        if (!canRun) this.assertNoDelegationWaitCycle(opts.parentId!, agentId);\n      }\n      inserted = this.db.raw.prepare(\n        `INSERT INTO tasks(\n          id, agent_id, project_id, conversation_id, input_message_id, title, content,\n          source, source_key, parent_id, status, priority, progress, stage, error,\n          session_id, workspace_override, engine_override, artifacts_required, created_at, started_at, ended_at\n         ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n         ON CONFLICT(source, source_key) WHERE source_key IS NOT NULL DO NOTHING`\n      ).run(\n        id, agentId, projectId, opts.conversationId ?? null, opts.inputMessageId ?? null,\n        title, content, source, sourceKey, opts.parentId ?? null, initialStatus, priority,\n         initialStage, dependencyError, opts.sessionId ?? null, workspaceOverride, engineOverride, requiresArtifacts ? 1 : 0,\n         now, canRun ? now : null, dependencyError ? now : null\n      ).changes > 0;\n      if (!inserted) return;\n      for (const dependencyTaskId of dependencyTaskIds) {\n        this.db.raw.prepare(\n          'INSERT INTO task_dependencies(task_id, dependency_task_id, created_at) VALUES(?, ?, ?)'\n        ).run(id, dependencyTaskId, now);\n      }\n      if (canRun) {\n        this.db.raw.prepare('INSERT INTO agent_runs(id, agent_id, task_id, pid, session_id, status, started_at, ended_at) VALUES(?, ?, ?, ?, ?, ?, ?, NULL)')\n          .run(randomUUID(), agentId, id, process.pid, randomUUID(), 'RUNNING', now);\n      }\n      if (dependencyError) {\n        this.db.raw.prepare('INSERT INTO task_events(id, task_id, event_type, payload, created_at) VALUES(?, ?, ?, ?, ?)')\n          .run(randomUUID(), id, 'dependency_blocked', JSON.stringify({ failed: dependencyGate.failed, error: dependencyError }), now);\n      } else if (approvalRequest) {\n        const approvalId = randomUUID();\n        this.db.raw.prepare(\n          'INSERT INTO approvals(id, task_id, agent_id, type, request, risk, status, created_at, decided_at) VALUES(?, ?, ?, ?, ?, ?, ?, ?, NULL)'\n        ).run(approvalId, id, agentId, DISPATCH_PLAN_APPROVAL_TYPE, approvalRequest, 'medium', 'pending', now);\n        this.db.raw.prepare('INSERT INTO task_events(id, task_id, event_type, payload, created_at) VALUES(?, ?, ?, ?, ?)')\n          .run(randomUUID(), id, 'approval_required', JSON.stringify({ approvalId, scope: 'dispatch_plan', request: approvalRequest, risk: 'medium' }), now);\n      } else {\n        this.db.raw.prepare('INSERT INTO task_events(id, task_id, event_type, payload, created_at) VALUES(?, ?, ?, ?, ?)')\n          .run(randomUUID(), id, canRun ? 'started' : 'queued', '{}', now);\n      }\n      opts.onPersisted?.(id);\n    });\n    if (!inserted) {\n      const existing = sourceKey\n        ? this.db.raw.prepare('SELECT * FROM tasks WHERE source = ? AND source_key = ?').get(source, sourceKey) as Row | undefined\n        : undefined;\n      if (!existing) throw new Error('任务创建失败');\n      return Object.assign(this.mapTask(existing), { deduplicated: true as const });\n    }\n    const created = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(id) as Row;\n    const task = this.mapTask(created);\n    if (canRun) this.dispatchTask(task, agent);\n    if (approvalRequest && !dependencyError) notify(this.db, '任务计划等待审批', approvalRequest);\n    if (dependencyError) {\n      for (const fn of this.finishListeners) {\n        try {\n          fn({ taskId: id, agentId, status: 'CANCELLED', title, result: null, error: dependencyError });\n        } catch { /* notification failure must not alter state */ }\n      }\n      this.settleTaskDependents(id, 'CANCELLED', dependencyError);\n    }\n    this.emit();\n    return task;\n  }\n\n  /**\n   * Sole commit point for a validated control-kernel plan. Planning is\n   * side-effect free; only this method may turn the plan into a runnable task.\n   */\n  applyDispatchPlan(request: KernelRequest, plan: DispatchPlan, state: DatabaseKernelState): CreateTaskResult {\n    if (request.requestId !== plan.requestId || request.conversationId !== plan.conversationId) {\n      throw new Error('调度计划与请求不匹配');\n    }\n\n    let stored = state.findPlan(request.requestId);\n    if (stored) stored = state.savePlan(request, plan);\n    if (stored?.status === 'failed') throw new Error('调度计划已标记失败');\n    if (stored?.status === 'committed') {\n      const existing = stored.taskId\n        ? this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(stored.taskId) as Row | undefined\n        : undefined;\n      if (!existing) throw new Error('已提交调度计划对应的任务不存在');\n      return Object.assign(this.mapTask(existing), { deduplicated: true as const });\n    }\n\n    const selected = request.workers.find((worker) => worker.agentId === plan.workerAgentId);\n    if (!selected || selected.engineId !== plan.workerEngineId) throw new Error('调度计划选择了不可用的执行员工');\n    const agent = this.getAgent(plan.workerAgentId);\n    if (!agent || agent.archived || agent.lifecycle !== 'READY') throw new Error('调度计划选择的员工当前不可执行');\n    if (agent.engineId !== plan.workerEngineId) throw new Error('员工执行引擎在规划后发生变化，请重新规划');\n    assertAndroidOperatorEngine(agent.kind, plan.workerEngineId);\n\n    stored ??= state.savePlan(request, plan);\n    if (stored.status === 'failed') throw new Error('调度计划已标记失败');\n    if (stored.status === 'committed') {\n      const existing = stored.taskId\n        ? this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(stored.taskId) as Row | undefined\n        : undefined;\n      if (!existing) throw new Error('已提交调度计划对应的任务不存在');\n      return Object.assign(this.mapTask(existing), { deduplicated: true as const });\n    }\n\n    const reviewConcerns = plan.advisorReviews\n      .filter((review) => !review.accepted)\n      .map((review) => `${review.advisorId}: ${review.summary}`)\n      .join('；')\n      .slice(0, 1_200);\n    const approvalRequest = plan.requiresHumanApproval\n      ? `控制核计划请求执行「${plan.title}」：${plan.rationale}${reviewConcerns ? `；复核意见：${reviewConcerns}` : ''}`\n      : undefined;\n    const task = this.createTask(plan.workerAgentId, plan.title, request.source, {\n      projectId: request.projectId ?? undefined,\n      conversationId: request.conversationId,\n      inputMessageId: request.inputMessageId,\n      sessionId: `conv-${request.conversationId}`,\n      sourceKey: `kernel:${request.requestId}`,\n      engineOverride: plan.workerEngineId,\n      content: plan.objective,\n      priority: plan.priority,\n      initialApprovalRequest: approvalRequest,\n      onPersisted: (taskId) => {\n        state.markCommitted(request.requestId, taskId);\n        this.db.audit({\n          id: randomUUID(),\n          actor: plan.leaderKernel,\n          action: 'kernel.plan.commit',\n          target: taskId,\n          result: `${plan.workerAgentId}:${plan.workerEngineId}`,\n          source: request.source\n        });\n      }\n    });\n    return task;\n  }\n\n  /**\n   * 等待任务到达终态（供团队流水线和委派工具使用；超时返回 null）。\n   * 传入 parentTaskId 时，父任务进入终态/消失会先取消子任务，避免\n   * 委派工具被中止后留下无人回收的 QUEUED/RUNNING 任务。\n   */\n  waitForTask(taskId: string, timeoutMs: number, parentTaskId?: string): Promise<Task | null> {\n    return new Promise((resolve) => {\n      const started = Date.now();\n      let delay = 500;\n      let settled = false;\n      const finish = (value: Task | null) => {\n        if (settled) return;\n        settled = true;\n        resolve(value);\n      };\n      const check = () => {\n        if (settled) return;\n        const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n        if (!row) return finish(null);\n        const t = this.mapTask(row);\n        if (TERMINAL_TASK_STATUSES.includes(t.status as typeof TERMINAL_TASK_STATUSES[number])) return finish(t);\n\n        if (parentTaskId) {\n          const parent = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(parentTaskId) as Row | undefined;\n          const parentLive = parent\n            ? !TERMINAL_TASK_STATUSES.includes(parent.status as typeof TERMINAL_TASK_STATUSES[number])\n            : false;\n          if (!parentLive) {\n            // cancelTask is idempotent with respect to a child that completed\n            // between the read above and this call.\n            try { this.cancelTask(taskId, '父任务已结束'); } catch { /* child may have completed concurrently */ }\n            const canceled = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n            return finish(canceled ? this.mapTask(canceled) : null);\n          }\n        }\n\n        if (Date.now() - started >= timeoutMs) return finish(null);\n        delay = Math.min(delay * 1.5, 4000);\n        setTimeout(check, delay);\n      };\n      check();\n    });\n  }\n\n  /** 追问/续跑（P2b）：新任务继承父任务的会话锚点，执行器以 resume/上下文重建方式继续 */\n  createFollowUpTask(parentTaskId: string, title: string): Task {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(parentTaskId) as Row | undefined;\n    if (!row) throw new Error('原任务不存在');\n    const parent = this.mapTask(row);\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'task.followUp', target: parentTaskId, result: 'ok' });\n    const source = parent.source === 'schedule' || parent.source === 'delegated' ? 'desktop' : parent.source;\n    return this.createTask(parent.agentId, title, source, {\n      parentId: parent.id,\n      sessionId: parent.sessionId ?? undefined,\n      conversationId: parent.conversationId ?? undefined,\n      content: title,\n      requiresArtifacts: parent.requiresArtifacts\n    });\n  }\n\n  /** 重新执行终态任务：保留归属与工作区，但不复用失败会话。 */\n  retryTask(taskId: string): Task {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as Row | undefined;\n    if (!row) throw new Error('原任务不存在或已删除');\n    const original = this.mapTask(row);\n    if (!['COMPLETED', 'FAILED', 'CANCELLED', 'INTERRUPTED'].includes(original.status)) throw new Error('任务尚未结束，不能重试');\n    const source = original.source === 'schedule' || original.source === 'delegated' ? 'desktop' : original.source;\n    const retried = this.createTask(original.agentId, original.title, source, {\n      parentId: original.id,\n      projectId: original.projectId ?? undefined,\n      conversationId: original.conversationId ?? undefined,\n      workspaceOverride: original.workspaceOverride ?? undefined,\n      engineOverride: original.engineOverride ?? undefined,\n      content: original.content,\n      requiresArtifacts: original.requiresArtifacts\n    });\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'task.retry', target: taskId, result: retried.id });\n    return retried;\n  }\n\n  /** 软删除终态任务：执行记录和成果来源仍保留在数据库中。 */\n  deleteTask(taskId: string): void {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as Row | undefined;\n    if (!row) throw new Error('任务不存在或已删除');\n    const task = this.mapTask(row);\n    if (!['COMPLETED', 'FAILED', 'CANCELLED', 'INTERRUPTED'].includes(task.status)) throw new Error('请先取消任务，再执行删除');\n    const activeChild = this.db.raw.prepare(\"SELECT id FROM tasks WHERE parent_id = ? AND deleted_at IS NULL AND status IN ('RUNNING','QUEUED','WAITING_APPROVAL','PAUSED')\").get(taskId) as { id: string } | undefined;\n    if (activeChild) throw new Error('该任务仍有执行中的后续任务，暂不能删除');\n    const activeDependent = this.db.raw.prepare(\n      `SELECT td.task_id\n       FROM task_dependencies td\n       JOIN tasks t ON t.id = td.task_id\n       WHERE td.dependency_task_id = ?\n         AND t.deleted_at IS NULL\n         AND t.status IN ('RUNNING','QUEUED','WAITING_APPROVAL','PAUSED')`\n    ).get(taskId) as { task_id: string } | undefined;\n    if (activeDependent) throw new Error('该任务仍有未完成的依赖后续任务，暂不能删除');\n    this.db.raw.prepare('UPDATE tasks SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL').run(Date.now(), taskId);\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'task.delete', target: taskId, result: 'soft-deleted' });\n    this.emit();\n  }\n\n  /** 经执行器注册表派发。 */\n  private dispatchTask(task: Task, agent: Agent) {\n    // 任务级引擎覆盖优先（E-2 编码委派）：子任务仍归属原员工，仅执行引擎不同\n    const requestedEngineId = task.engineOverride || agent.engineId;\n    const binding: ExecutionBinding = {\n      requestedEngineId,\n      resolvedEngineId: null,\n      executorKind: 'unavailable',\n      usedFallback: false\n    };\n    this.executors.dispatch(\n      task,\n      { ...agent, engineId: requestedEngineId },\n      this.makeCallbacks(task.id, agent.id, binding, agent.kind),\n      (resolved) => {\n        Object.assign(binding, resolved);\n        this.db.raw.prepare(\n          'UPDATE agent_runs SET requested_engine_id = ?, resolved_engine_id = ?, executor_kind = ? WHERE task_id = ? AND ended_at IS NULL'\n        ).run(resolved.requestedEngineId, resolved.resolvedEngineId, resolved.executorKind, task.id);\n        this.db.audit({\n          id: randomUUID(),\n          actor: 'system',\n          action: 'task.executorResolved',\n          target: task.id,\n          result: JSON.stringify(resolved),\n          source: task.source\n        });\n      }\n    );\n  }\n\n  /** 任务事件落库（13.2 审计可追溯；详情页时间线数据源） */\n  private recordEvent(taskId: string, eventType: string, payload: Record<string, unknown>, now: number) {\n    this.db.raw.prepare('INSERT INTO task_events(id, task_id, event_type, payload, created_at) VALUES(?, ?, ?, ?, ?)')\n      .run(randomUUID(), taskId, eventType, JSON.stringify(payload), now);\n  }\n\n  /** Return a mobile task to FIFO while its process has not acquired a lease.\n   * Retrying an already-issued non-idempotent phone command would be unsafe;\n   * this path is limited to preparation-time offline/lease races. */\n  private deferMobilePreparation(taskId: string, reason: string): boolean {\n    const now = Date.now();\n    let changed = false;\n    this.db.transaction(() => {\n      changed = this.db.raw.prepare(\n        `UPDATE tasks\n         SET status = 'QUEUED', stage = ?, error = NULL, started_at = NULL, ended_at = NULL\n         WHERE id = ? AND status = 'RUNNING'`\n      ).run(reason, taskId).changes > 0;\n      if (!changed) return;\n      this.db.raw.prepare(\n        \"UPDATE agent_runs SET ended_at = ?, status = 'INTERRUPTED' WHERE task_id = ? AND ended_at IS NULL\"\n      ).run(now, taskId);\n      this.recordEvent(taskId, 'queued', { reason: 'mobile-preparation-deferred', detail: reason }, now);\n    });\n    if (changed) this.emit();\n    return changed;\n  }\n\n  /** Ignore output arriving after cancellation/timeout and release the small\n   * per-task accounting entry after late child-process callbacks settle. */\n  private closeOutputState(taskId: string) {\n    const state = this.outputStates.get(taskId) ?? { chars: 0, events: 0, truncated: false, closed: false };\n    state.closed = true;\n    this.outputStates.set(taskId, state);\n    setTimeout(() => {\n      if (this.outputStates.get(taskId) === state) this.outputStates.delete(taskId);\n    }, OUTPUT_STATE_TTL_MS);\n  }\n\n  /** 执行器回调：统一走“状态更新 + task_events 同事务”模式；终态触发该员工 FIFO 补位 */\n  private makeCallbacks(taskId: string, agentId: string, binding: ExecutionBinding, agentKind: Agent['kind']): ExecutorCallbacks {\n    const finish = async (status: 'COMPLETED' | 'FAILED' | 'INTERRUPTED', info: { result?: string; error?: string }) => {\n      if (this.finalizingTasks.has(taskId)) return;\n      this.finalizingTasks.add(taskId);\n      const completionSignaledAt = Date.now();\n      this.closeOutputState(taskId);\n      const boundedResult = typeof info.result === 'string' ? info.result.slice(0, MAX_TASK_RESULT_CHARS) : undefined;\n      let finalStatus = status;\n      let finalError = info.error;\n      let artifactManifest: ProjectArtifactManifest | null = null;\n\n      if (status === 'COMPLETED' && this.projectArtifactCompletionValidator) {\n          const task = this.db.raw.prepare(\n            'SELECT * FROM tasks WHERE id = ?'\n          ).get(taskId) as { project_id: string | null; artifacts_required?: number; started_at: number | null; created_at: number | null } | undefined;\n        if (task?.project_id && Number(task.artifacts_required ?? 0) === 1) {\n          const executionStartedAt = Number.isSafeInteger(task.started_at)\n            ? Number(task.started_at) : completionSignaledAt;\n          // Approval and dependency resumes reset started_at for watchdog\n          // purposes. A worker can have already written a real artifact while\n          // that resume is being finalized, so the task creation time remains\n          // the lower bound for admission. The scanner still rejects stale,\n          // symlinked, out-of-root, and unchanged files.\n          const createdAt = Number.isSafeInteger(task.created_at) ? Number(task.created_at) : executionStartedAt;\n          const startedAt = Math.min(createdAt, executionStartedAt);\n          this.db.transaction(() => {\n            const changed = this.db.raw.prepare(\n              \"UPDATE tasks SET stage = ? WHERE id = ? AND status = 'RUNNING'\"\n            ).run('校验项目产物', taskId).changes;\n            if (changed > 0) this.recordEvent(taskId, 'stage', { stage: '校验项目产物' }, completionSignaledAt);\n          });\n          this.emit();\n          try {\n            const evidence = await this.projectArtifactCompletionValidator.validateTaskCompletion({\n              taskId,\n              projectId: task.project_id,\n              startedAt,\n              endedAt: completionSignaledAt\n            });\n            if (evidence.ok) artifactManifest = evidence.manifest;\n            else {\n              finalStatus = 'FAILED';\n              finalError = evidence.error;\n            }\n          } catch {\n            finalStatus = 'FAILED';\n            finalError = '项目产物校验服务异常，任务未标记为完成';\n          }\n        }\n      }\n\n      const now = Date.now();\n      // 真实执行鉴权失败：如实把引擎标为 AUTH_REQUIRED，不掩盖\n      const authFailed = binding.resolvedEngineId !== null\n        && binding.executorKind !== 'unavailable'\n        && isExecutorAuthenticationFailure(finalError);\n      // 终态守卫（数据层最后防线）：只有非终态任务才能落终态。\n      // 迟到回调（看门狗中断后进程才退出、用户取消后执行器才收尾、执行器双重回调）\n      // 一律丢弃，绝不把已 INTERRUPTED/CANCELLED 的任务改写成 COMPLETED。\n      const LIVE = \"('QUEUED','RUNNING','WAITING_APPROVAL','PAUSED')\";\n      let applied = false;\n      this.db.transaction(() => {\n        if (finalStatus === 'COMPLETED') {\n          applied = this.db.raw.prepare(`UPDATE tasks SET status = 'COMPLETED', progress = 100, stage = '完成', result = ?, ended_at = ? WHERE id = ? AND status IN ${LIVE}`)\n            .run(boundedResult ?? null, now, taskId).changes > 0;\n          if (!applied) return;\n          if (artifactManifest) this.recordEvent(taskId, 'artifact_manifest', { manifest: artifactManifest }, now);\n          const result = boundedResult ?? '';\n          this.recordEvent(taskId, 'result', { available: result.length > 0, chars: result.length }, now);\n          this.recordEvent(taskId, 'completed', { progress: 100 }, now);\n        } else {\n          applied = this.db.raw.prepare(`UPDATE tasks SET status = ?, error = ?, ended_at = ? WHERE id = ? AND status IN ${LIVE}`)\n            .run(finalStatus, finalError ?? null, now, taskId).changes > 0;\n          if (!applied) return;\n          if (status === 'COMPLETED' && finalStatus === 'FAILED') {\n            this.recordEvent(taskId, 'artifact_validation_failed', { error: finalError ?? '' }, now);\n          }\n          this.recordEvent(taskId, finalStatus === 'FAILED' ? 'failed' : 'interrupted', { error: finalError ?? '' }, now);\n        }\n        this.db.raw.prepare('UPDATE agent_runs SET ended_at = ?, status = ? WHERE task_id = ? AND ended_at IS NULL').run(now, finalStatus, taskId);\n        if (authFailed && binding.resolvedEngineId) {\n          this.db.raw.prepare(\"UPDATE engines SET status = 'AUTH_REQUIRED', auth_status = 'required' WHERE id = ?\").run(binding.resolvedEngineId);\n        }\n      });\n      // 守卫拦下的迟到回调：不通知、不推 webhook、不触发补位，只做一次并发释放后返回\n      if (!applied) {\n        this.finalizingTasks.delete(taskId);\n        this.emit();\n        this.scheduleNext(agentId);\n        return;\n      }\n      if (finalStatus === 'FAILED') {\n        const t = this.db.raw.prepare('SELECT title FROM tasks WHERE id = ?').get(taskId) as { title: string } | undefined;\n        notify(this.db, '任务执行失败', `${t?.title ?? taskId}：${(finalError ?? '').slice(0, 120)}`);\n      }\n      if (authFailed) notify(this.db, '引擎需要重新登录', '执行引擎鉴权失败，已标记为待登录，请到引擎中心处理');\n      this.settleTaskDependents(\n        taskId,\n        finalStatus,\n        finalError ?? `前置任务 ${taskId} 以 ${finalStatus} 结束`\n      );\n      // 终态订阅（webhook 等对外通知）：查询落库后的最终数据,异常不影响主流程\n      {\n        const t = this.db.raw.prepare('SELECT title FROM tasks WHERE id = ?').get(taskId) as { title: string } | undefined;\n        for (const fn of this.finishListeners) {\n          try {\n            fn({ taskId, agentId, status: finalStatus, title: t?.title ?? taskId, result: boundedResult ?? null, error: finalError ?? null });\n          } catch { /* 通知失败不影响调度 */ }\n        }\n      }\n      this.finalizingTasks.delete(taskId);\n      this.emit();\n      this.scheduleNext(agentId);\n    };\n    return {\n      onStage: (id, stage) => {\n        const now = Date.now();\n        this.db.transaction(() => {\n          const changed = this.db.raw.prepare(\"UPDATE tasks SET stage = ? WHERE id = ? AND status = 'RUNNING'\").run(stage, id).changes;\n          if (changed > 0) this.recordEvent(id, 'stage', { stage }, now);\n        });\n        this.emit();\n      },\n      onProgress: (id, progress) => {\n        const now = Date.now();\n        this.db.transaction(() => {\n          const changed = this.db.raw.prepare(\"UPDATE tasks SET progress = ? WHERE id = ? AND status = 'RUNNING'\").run(progress, id).changes;\n          if (changed > 0) this.recordEvent(id, 'progress', { progress }, now);\n        });\n        this.emit();\n      },\n      onOutput: (id, chunk) => {\n        // 高频增量文本：保留有限预算后再落事件库/推送，避免长任务\n        // 造成 SQLite、IPC 和 React 状态同时线性增长。\n        const state = this.outputStates.get(id) ?? { chars: 0, events: 0, truncated: false, closed: false };\n        this.outputStates.set(id, state);\n        if (state.closed || !chunk || state.events >= MAX_TASK_OUTPUT_EVENTS || state.chars >= MAX_TASK_OUTPUT_CHARS) return;\n        const remaining = MAX_TASK_OUTPUT_CHARS - state.chars;\n        const accepted = chunk.slice(0, remaining);\n        if (!accepted) return;\n        state.chars += accepted.length;\n        state.events += 1;\n        this.recordEvent(id, 'output', { chunk: accepted }, Date.now());\n        for (const fn of this.outputListeners) fn(id, accepted);\n        if (accepted.length < chunk.length || state.events >= MAX_TASK_OUTPUT_EVENTS || state.chars >= MAX_TASK_OUTPUT_CHARS) {\n          state.truncated = true;\n        }\n      },\n      onSession: (id, sessionId) => {\n        // P2b：会话锚点落库（仅首次），追问时继承\n        this.db.raw.prepare('UPDATE tasks SET session_id = ? WHERE id = ? AND session_id IS NULL').run(sessionId, id);\n      },\n      onReleased: () => {\n        if (this.resumeAfterRelease.delete(taskId)) this.resumePausedTask(taskId);\n        this.emit();\n        this.scheduleNext(agentId);\n      },\n      onDone: (id, result) => { void finish('COMPLETED', { result }); },\n      onError: (id, message) => {\n        const preparationRace = agentKind === 'android_operator'\n          && /手机任务准备失败：.*(?:Android device is offline|active control lease)/i.test(message);\n        if (preparationRace && this.deferMobilePreparation(taskId, '手机暂时不可用，等待连接或当前控制会话释放')) return;\n        void finish(/超时|中断/.test(message) ? 'INTERRUPTED' : 'FAILED', { error: message });\n      }\n    };\n  }\n\n  /**\n   * Count occupied Agent slots across durable task state and executor resources.\n   * ACP children remain present in the registry after their task reaches a\n   * terminal state, so the union must be counted without double-counting a\n   * PAUSED child that is represented in both places.\n   */\n  private agentOccupancy(agentId: string, excludeTaskId?: string): number {\n    // A dispatch-plan approval has not acquired an execution slot. Runtime\n    // tool approvals remain counted through the live executor registry below.\n    const occupying = ['RUNNING', 'PAUSED'];\n    let active = (this.db.raw.prepare(\"SELECT COUNT(*) c FROM tasks WHERE agent_id = ? AND status IN ('RUNNING','PAUSED')\").get(agentId) as { c: number }).c;\n\n    if (excludeTaskId) {\n      const excluded = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(excludeTaskId) as Row | undefined;\n      if (excluded?.agent_id === agentId && occupying.includes(excluded.status as string)) {\n        active = Math.max(0, active - 1);\n      }\n    }\n\n    for (const taskId of this.executors.activeTaskIdsForAgent(agentId)) {\n      if (taskId === excludeTaskId) continue;\n      const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n      if (!row || !occupying.includes(row.status as string)) active += 1;\n    }\n    return active;\n  }\n\n  private resumePausedTask(taskId: string): boolean {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n    if (!row || row.status !== 'PAUSED') return false;\n    const agentId = row.agent_id as string;\n    const agent = this.getAgent(agentId);\n    if (!agent || agent.lifecycle !== 'READY') return false;\n    if (this.agentOccupancy(agentId, taskId) >= Math.max(1, agent.concurrencyLimit)) return false;\n\n    // Watchdog time is measured per running segment; the paused interval does\n    // not count toward maxRunMinutes.\n    const changed = this.db.raw.prepare(\"UPDATE tasks SET status = 'RUNNING', started_at = ? WHERE id = ? AND status = 'PAUSED'\").run(Date.now(), taskId).changes;\n    if (changed === 0) return false;\n    const resumed = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n    if (!resumed) return false;\n    this.dispatchTask(this.mapTask(resumed), agent);\n    return true;\n  }\n\n  /** FIFO 调度：任务到达终态后，启动该员工最早的 QUEUED 任务（6.2 基础调度；资源保护时暂停） */\n  private scheduleNext(agentId: string) {\n    if (this.schedulingAgents.has(agentId)) return;\n    this.schedulingAgents.add(agentId);\n    try {\n    const agent = this.getAgent(agentId);\n    if (!agent || agent.lifecycle !== 'READY') return;\n    if (this.dispatchGuard() !== null) return;\n    if (agent.kind === 'android_operator' && !this.mobileDispatchPolicy?.canDispatch(agentId).ready) return;\n    const active = this.agentOccupancy(agentId);\n    if (active >= Math.max(1, agent.concurrencyLimit)) return;\n    let prunedOrphan = false;\n    while (true) {\n      const rows = this.db.raw.prepare(\"SELECT * FROM tasks WHERE agent_id = ? AND status = 'QUEUED' ORDER BY created_at\").all(agentId) as Row[];\n      if (rows.length === 0) {\n        if (prunedOrphan) this.emit();\n        return;\n      }\n      let dispatched = false;\n      for (const row of rows) {\n      if (row.source === 'delegated' && !this.delegationChainIsLive(row)) {\n        const cancelled = this.cancelTaskSet(\n          this.collectTaskTree(String(row.id)),\n          Date.now(),\n          '父任务已经结束，排队中的委派已取消',\n          '上级委派已经结束'\n        );\n        if (cancelled.length === 0) return;\n        prunedOrphan = true;\n        this.notifyCancelledTasks(cancelled);\n        this.settleCancelledTaskDependents(cancelled);\n        this.db.audit({ id: randomUUID(), actor: 'system', action: 'task.cancelOrphanedDelegation', target: String(row.id), result: 'ok' });\n        for (const affectedAgentId of new Set(cancelled.map((task) => task.agentId))) {\n          if (affectedAgentId !== agentId) this.scheduleNext(affectedAgentId);\n        }\n        continue;\n      }\n      const gate = this.dependencyGate(String(row.id));\n      if (!gate.ready) {\n        if (gate.failed.length === 0) continue;\n        const reason = `前置任务未成功完成，已阻止执行：${gate.failed.join(', ')}`;\n        const cancelled = this.cancelTaskSet(\n          this.collectTaskTree(String(row.id)),\n          Date.now(),\n          reason,\n          reason\n        );\n        if (cancelled.length === 0) continue;\n        prunedOrphan = true;\n        this.notifyCancelledTasks(cancelled);\n        this.settleCancelledTaskDependents(cancelled);\n        for (const affectedAgentId of new Set(cancelled.map((task) => task.agentId))) {\n          if (affectedAgentId !== agentId) this.scheduleNext(affectedAgentId);\n        }\n        continue;\n      }\n      const now = Date.now();\n      this.db.transaction(() => {\n        this.db.raw.prepare(\"UPDATE tasks SET status = 'RUNNING', stage = ?, started_at = ? WHERE id = ? AND status = 'QUEUED'\").run(STAGES[0], now, row.id as string);\n        this.db.raw.prepare('INSERT INTO agent_runs(id, agent_id, task_id, pid, session_id, status, started_at, ended_at) VALUES(?, ?, ?, ?, ?, ?, ?, NULL)')\n          .run(randomUUID(), agentId, row.id as string, process.pid, randomUUID(), 'RUNNING', now);\n        this.recordEvent(row.id as string, 'started', {}, now);\n      });\n      const task = this.mapTask(row);\n      task.status = 'RUNNING';\n      this.dispatchTask(task, agent);\n      this.emit();\n      dispatched = true;\n      break;\n      }\n      if (dispatched) return;\n      // Every queued row is waiting on a prerequisite. A later completion\n      // will call this method through settleTaskDependents.\n      return;\n    }\n    } finally {\n      this.schedulingAgents.delete(agentId);\n    }\n  }\n\n  /** 设备上线或控制租约释放后，唤醒对应手机员工的 FIFO 队列。 */\n  wakeAgentQueue(agentId: string): void {\n    this.scheduleNext(agentId);\n  }\n\n  /** Resource guard recovery is system-wide, so every durable FIFO with queued work must be reconsidered. */\n  wakeQueuedAgentQueues(releasedReason?: string): number {\n    if (this.dispatchGuard() !== null) return 0;\n    const queued = (this.db.raw.prepare(\n      'SELECT * FROM tasks WHERE deleted_at IS NULL ORDER BY created_at DESC'\n    ).all() as Row[]).filter((task) => task.status === 'QUEUED');\n    if (releasedReason) {\n      for (const task of queued) {\n        if (task.stage !== releasedReason) continue;\n        this.db.raw.prepare(\"UPDATE tasks SET stage = '排队中' WHERE id = ? AND status = 'QUEUED'\").run(task.id as string);\n      }\n    }\n    const agentIds = [...new Set(queued.map((task) => task.agent_id as string))];\n    for (const agentId of agentIds) this.scheduleNext(agentId);\n    if (queued.length > 0) this.emit();\n    return agentIds.length;\n  }\n\n  /** Return the root task and delegated descendants, cycle-safe. parent_id is\n   * also used by follow-ups/retries, which are independent executions and\n   * must not be cancelled as delegation children. */\n  private collectTaskTree(rootTaskId: string): string[] {\n    const queue = [rootTaskId];\n    const seen = new Set<string>();\n    const result: string[] = [];\n    while (queue.length > 0) {\n      const parentId = queue.shift()!;\n      if (seen.has(parentId)) continue;\n      seen.add(parentId);\n      result.push(parentId);\n      const children = this.db.raw.prepare(\n        \"SELECT id FROM tasks WHERE parent_id = ? AND deleted_at IS NULL AND source = 'delegated'\"\n      ).all(parentId) as { id: string }[];\n      for (const child of children) {\n        if (child?.id && !seen.has(child.id)) queue.push(child.id);\n      }\n    }\n    return result;\n  }\n\n  /**\n   * Mark a single live task cancelled. The guarded UPDATE is deliberately the\n   * first state transition; executor aborts happen only after the whole set is\n   * durable, so synchronous onError/onDone callbacks cannot win the race.\n   */\n  private cancelTaskInternal(taskId: string, now: number, reason: string): boolean {\n    const changed = this.db.raw.prepare(\n      \"UPDATE tasks SET status = 'CANCELLED', ended_at = ? WHERE id = ? AND status IN ('RUNNING','QUEUED','WAITING_APPROVAL','PAUSED')\"\n    ).run(now, taskId).changes > 0;\n    if (!changed) return false;\n    this.db.raw.prepare(\"UPDATE agent_runs SET ended_at = ?, status = 'CANCELLED' WHERE task_id = ? AND ended_at IS NULL\").run(now, taskId);\n    this.db.raw.prepare(\"UPDATE approvals SET status = 'rejected', decided_at = ? WHERE task_id = ? AND status = 'pending'\").run(now, taskId);\n    this.recordEvent(taskId, 'cancelled', { reason }, now);\n    return true;\n  }\n\n  private releaseCancelledTasks(cancelled: CancelledTaskRecord[]): void {\n    for (const task of cancelled) {\n      this.resumeAfterRelease.delete(task.id);\n      this.closeOutputState(task.id);\n      try { this.broker.abandonTask(task.id); } catch { /* best effort */ }\n      try { this.executors.abort(task.id); } catch { /* best effort */ }\n    }\n  }\n\n  /**\n   * Cancel a set of tasks atomically, then release broker/executor resources.\n   * The caller supplies root/descendant messages for finish subscribers.\n   */\n  private cancelTaskSet(\n    taskIds: string[],\n    now: number,\n    rootReason: string,\n    descendantReason: string,\n    rootTaskIds = new Set(taskIds.slice(0, 1)),\n    beforePersist?: () => void\n  ): CancelledTaskRecord[] {\n    const cancelled: CancelledTaskRecord[] = [];\n    this.db.transaction(() => {\n      beforePersist?.();\n      for (const taskId of taskIds) {\n        const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as Row | undefined;\n        if (!row || !ACTIVE_TASK_STATUSES.includes(row.status as typeof ACTIVE_TASK_STATUSES[number])) continue;\n        const error = rootTaskIds.has(taskId) ? rootReason : descendantReason;\n        const record = {\n          id: taskId,\n          agentId: String(row.agent_id),\n          title: String(row.title ?? taskId),\n          error\n        };\n        if (!this.cancelTaskInternal(taskId, now, error)) continue;\n        cancelled.push(record);\n      }\n    });\n\n    // State is already terminal before either callback-capable resource is\n    // touched. A failing abort must not prevent the rest of the tree from\n    // being released.\n    this.releaseCancelledTasks(cancelled);\n    return cancelled;\n  }\n\n  private notifyCancelledTasks(cancelled: CancelledTaskRecord[]): void {\n    for (const task of cancelled) {\n      for (const fn of this.finishListeners) {\n        try {\n          fn({ taskId: task.id, agentId: task.agentId, status: 'CANCELLED', title: task.title, result: null, error: task.error });\n        } catch { /* notification failure must not alter state */ }\n      }\n    }\n  }\n\n  /**\n   * A cancellation request may include a delegation tree. Every task that was\n   * durably cancelled is an upstream prerequisite in its own right, so settle\n   * each distinct id instead of only settling the user-facing root.\n   */\n  private settleCancelledTaskDependents(cancelled: readonly CancelledTaskRecord[]): void {\n    const settled = new Set<string>();\n    for (const task of cancelled) {\n      if (settled.has(task.id)) continue;\n      settled.add(task.id);\n      this.settleTaskDependents(task.id, 'CANCELLED', task.error);\n    }\n  }\n\n  /** Cancel a task and all active descendants; public API remains one-arg compatible. */\n  cancelTask(taskId: string, reason = '用户取消任务') {\n    const task = this.db.raw.prepare('SELECT agent_id, status FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as { agent_id: string; status: TaskStatus } | undefined;\n    if (!task) throw new Error('任务不存在或已删除');\n    if (!ACTIVE_TASK_STATUSES.includes(task.status as typeof ACTIVE_TASK_STATUSES[number])) throw new Error('任务已经结束，不能取消');\n\n    const cancelled = this.cancelTaskSet(this.collectTaskTree(taskId), Date.now(), reason, '父任务已取消');\n    const rootCancelled = cancelled.some((item) => item.id === taskId);\n    if (!rootCancelled) {\n      // Another terminal transition won between the initial read and our\n      // guarded UPDATE. Preserve the existing API error instead of emitting a\n      // duplicate cancellation event.\n      const latest = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ? AND deleted_at IS NULL').get(taskId) as Row | undefined;\n      if (!latest) throw new Error('任务不存在或已删除');\n      if (latest.status === 'RUNNING' && latest.stage === '等待执行取消确认') return;\n      if (!ACTIVE_TASK_STATUSES.includes(latest.status as typeof ACTIVE_TASK_STATUSES[number])) throw new Error('任务已经结束，不能取消');\n      return;\n    }\n\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: 'task.cancel', target: taskId, result: 'ok' });\n    this.notifyCancelledTasks(cancelled);\n    this.settleCancelledTaskDependents(cancelled);\n    this.emit();\n    for (const agentId of new Set(cancelled.map((item) => item.agentId))) this.scheduleNext(agentId);\n  }\n\n  pauseTask(taskId: string) {\n    const changed = this.db.raw.prepare(\"UPDATE tasks SET status = 'PAUSED' WHERE id = ? AND status = 'RUNNING'\").run(taskId).changes;\n    if (changed > 0) {\n      this.executors.abort(taskId);\n      this.db.audit({ id: randomUUID(), actor: 'system', action: 'task.pause', target: taskId, result: 'ok', source: 'orchestrator' });\n    }\n    this.emit();\n  }\n\n  resumeTask(taskId: string) {\n    const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n    if (!row || row.status !== 'PAUSED') return;\n    if (this.executors.isExecuting(taskId)) {\n      this.resumeAfterRelease.add(taskId);\n      this.emit();\n      return;\n    }\n    this.resumePausedTask(taskId);\n    this.db.audit({ id: randomUUID(), actor: 'system', action: 'task.resume', target: taskId, result: 'ok', source: 'orchestrator' });\n    this.emit();\n  }\n\n  private dispatchPlanReadiness(taskId: string, agent: Agent): { ready: boolean; stage: string } {\n    if (agent.archived) return { ready: false, stage: '员工已归档' };\n    if (agent.lifecycle !== 'READY') return { ready: false, stage: `员工未就绪（${agent.lifecycle}）` };\n    const dependency = this.dependencyGate(taskId);\n    if (dependency.failed.length > 0) {\n      return { ready: false, stage: `等待前置任务失败（${dependency.failed.join(', ')}）` };\n    }\n    if (!dependency.ready) return { ready: false, stage: `等待前置任务（${dependency.pending.length}）` };\n    const guardReason = this.dispatchGuard();\n    if (guardReason) return { ready: false, stage: guardReason };\n    if (agent.kind === 'android_operator') {\n      const mobile = this.mobileDispatchPolicy?.canDispatch(agent.id)\n        ?? { bound: false, ready: false, reason: '手机控制服务尚未启动' };\n      if (!mobile.ready) return { ready: false, stage: mobile.reason };\n    }\n    if (this.agentOccupancy(agent.id, taskId) >= Math.max(1, agent.concurrencyLimit)) {\n      return { ready: false, stage: '排队中' };\n    }\n    return { ready: true, stage: STAGES[0] };\n  }\n\n  decideApproval(approvalId: string, approve: boolean) {\n    const now = Date.now();\n    const ap = this.db.raw.prepare('SELECT * FROM approvals WHERE id = ?').get(approvalId) as Row | undefined;\n    if (!ap || ap.status !== 'pending') return;\n    const scope = approvalScope(ap.type);\n    const taskId = ap.task_id as string;\n\n    if (scope === 'dispatch_plan') {\n      const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n      if (!row || row.status !== 'WAITING_APPROVAL') return;\n      const agent = this.getAgent(row.agent_id as string);\n      const readiness = agent && approve\n        ? this.dispatchPlanReadiness(taskId, agent)\n        : { ready: false, stage: '审批被拒绝' };\n\n      this.db.transaction(() => {\n        this.db.raw.prepare('UPDATE approvals SET status = ?, decided_at = ? WHERE id = ?').run(approve ? 'approved' : 'rejected', now, approvalId);\n        this.recordEvent(taskId, 'approval_decided', { approvalId, scope, approved: approve }, now);\n        if (!approve) {\n          this.db.raw.prepare(\"UPDATE tasks SET status = 'FAILED', ended_at = ?, error = '审批被拒绝' WHERE id = ? AND status = 'WAITING_APPROVAL'\").run(now, taskId);\n          this.recordEvent(taskId, 'failed', { error: '审批被拒绝' }, now);\n          return;\n        }\n        if (!agent || !readiness.ready) {\n          this.db.raw.prepare(\"UPDATE tasks SET status = 'QUEUED', stage = ?, started_at = NULL WHERE id = ? AND status = 'WAITING_APPROVAL'\")\n            .run(readiness.stage, taskId);\n          this.recordEvent(taskId, 'queued', { reason: readiness.stage, afterApproval: true }, now);\n          return;\n        }\n        this.db.raw.prepare(\"UPDATE tasks SET status = 'RUNNING', stage = ?, started_at = ? WHERE id = ? AND status = 'WAITING_APPROVAL'\")\n          .run(STAGES[0], now, taskId);\n        this.db.raw.prepare(\n          'INSERT INTO agent_runs(id, agent_id, task_id, pid, session_id, status, started_at, ended_at) VALUES(?, ?, ?, ?, ?, ?, ?, NULL)'\n        ).run(randomUUID(), agent.id, taskId, process.pid, randomUUID(), 'RUNNING', now);\n        this.recordEvent(taskId, 'started', { afterApproval: true }, now);\n      });\n\n      if (approve && agent && readiness.ready) {\n        const started = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n        if (started?.status === 'RUNNING') this.dispatchTask(this.mapTask(started), agent);\n      }\n      this.db.audit({ id: randomUUID(), actor: 'admin', action: approve ? 'approval.approve' : 'approval.reject', target: approvalId, result: readiness.ready ? 'running' : approve ? 'queued' : 'rejected' });\n      this.emit();\n      if (!approve) {\n        this.settleTaskDependents(taskId, 'FAILED', '前置任务审批被拒绝');\n        this.scheduleNext(ap.agent_id as string);\n      }\n      return;\n    }\n\n    // P1b：命中活跃执行器（工具循环正挂起等待）→ 仅唤醒，不重新派发；拒绝也不 fail 整个任务\n    const wasLive = this.broker.decide(approvalId, approve);\n    this.db.transaction(() => {\n      this.db.raw.prepare('UPDATE approvals SET status = ?, decided_at = ? WHERE id = ?').run(approve ? 'approved' : 'rejected', now, approvalId);\n      this.recordEvent(taskId, 'approval_decided', { approvalId, scope, approved: approve }, now);\n      if (approve || wasLive) {\n        // 重置 started_at：审批等待期不计入看门狗时长（否则长时间等审批的任务恢复即被误杀）\n        this.db.raw.prepare(\"UPDATE tasks SET status = 'RUNNING', started_at = ? WHERE id = ? AND status = 'WAITING_APPROVAL'\").run(now, taskId);\n      } else {\n        this.db.raw.prepare(\"UPDATE tasks SET status = 'FAILED', ended_at = ?, error = '审批被拒绝' WHERE id = ? AND status = 'WAITING_APPROVAL'\").run(now, taskId);\n      }\n    });\n    // 非活跃执行器（种子数据/重启后遗留）且批准 → 重新派发执行（13.2 审批链路）\n    if (approve && !wasLive) {\n      const row = this.db.raw.prepare('SELECT * FROM tasks WHERE id = ?').get(taskId) as Row | undefined;\n      const agent = row ? this.getAgent(row.agent_id as string) : null;\n      if (row && agent && row.status === 'RUNNING' && !this.executors.isExecuting(row.id as string)) {\n        const activeRun = this.db.raw.prepare('SELECT id FROM agent_runs WHERE task_id = ? AND ended_at IS NULL LIMIT 1')\n          .get(row.id as string) as { id: string } | undefined;\n        if (!activeRun) {\n          this.db.raw.prepare(\n            'INSERT INTO agent_runs(id, agent_id, task_id, pid, session_id, status, started_at, ended_at) VALUES(?, ?, ?, ?, ?, ?, ?, NULL)'\n          ).run(randomUUID(), agent.id, row.id as string, process.pid, randomUUID(), 'RUNNING', now);\n        }\n        this.dispatchTask(this.mapTask(row), agent);\n      }\n    }\n    this.db.audit({ id: randomUUID(), actor: 'admin', action: approve ? 'approval.approve' : 'approval.reject', target: approvalId, result: 'ok' });\n    this.emit();\n    if (!approve && !wasLive) {\n      this.settleTaskDependents(taskId, 'FAILED', '前置任务审批被拒绝');\n      this.scheduleNext(ap.agent_id as string);\n    }\n  }\n}\n\nexport function formatDuration(ms: number): string {\n  const sec = Math.floor(ms / 1000);\n  const d = Math.floor(sec / 86400);\n  const h = Math.floor((sec % 86400) / 3600);\n  const m = Math.floor((sec % 3600) / 60);\n  if (d > 0) return `${d}天 ${h}小时`;\n  if (h > 0) return `${h}小时 ${m}分`;\n  return `${m}分 ${sec % 60}秒`;\n}\n"
